WFJ.Data.add("quest", {
  [7003] = { "Giganti rimpiccioliti", "Usa l'⟦Zorbin's Ultra-Shrinker=Ultra Riduttore di Zorbin⟧ per rimpicciolire i giganti di qualsiasi tipo che trovi a Feralas, rendendoli più gestibili. Porta 15 Residuo di Miniaturizzazione, che trovi sulle versioni rimpicciolite di questi giganti, a ⟦Zorbin Fandazzle=Zorbin Saldaleva⟧, ai moli della Costa dell'Oblio, a Feralas.", "Se resto qui fuori, dovrò fare qualcosa per i giganti! Di certo non fanno bene agli affari, no?\n\nSto lavorando a una variante di un raggio rimpicciolente gnomesco, ma per costruirlo uso i superiori progressi tecnologici dei GOBLIN! Per evitarmi inconvenienti come la morte, vorrei che lo provassi tu su uno qualsiasi dei giganti di Feralas. Dopo averli rimpiccioliti, dovresti trovare su di loro del residuo di miniaturizzazione: portamene un po'!", "Il residuo di miniaturizzazione, te lo assicuro, è una merce preziosa per l'ingegneria! Be', è prezioso nel senso che mi aiuta a far sì che il raggio non faccia qualcosa di deludente come esplodere in mano a chi lo usa.\n\nOh, intendo i raggi diversi da quello che ho dato a te. Assolutamente!", "Splendifantastico! Non solo sono felice di vederti tornare con il residuo, ma anche con tutte le appendici principali intatte! Cioè, be', non c'è mai stato alcun pericolo a usare l'Ultra Riduttore, giusto?\n\nApprezzo davvero l'impegno che ci hai messo per me, {name}. Sei davvero amic<o/a> dei goblin di tutto il mondo. Accetta questo come segno della mia gratitudine!", 0x236b774b, 0xee4452cf, 0x95a0e065, 0xfba8b795, 0xfdd0c9ae, "....." },
  [7021] = { "⟦Great-father Winter=Babbo Inverno⟧ è arrivato!", "Parla con ⟦Greatfather Winter=Babbo Inverno⟧: si trova vicino all'area dei venditori della Masseria Buongusto, a Orgrimmar.", "Buon Grande Inverno, amico! Non dimenticare di salutare ⟦Greatfather Winter=Babbo Inverno⟧, che al momento si trova a Orgrimmar! Se quest'anno sei stat<o/a> buon<o/a>, riceverai doni meravigliosi il giorno della Festa del Grande Inverno. Non dimenticare di dirgli cosa speri di ricevere quest'anno!\n\nE non dimenticare di fare scorta di dolcetti da regalare a chi è stato buono quest'anno. Abbiamo un'ampia scelta. Dalla nostra fattoria alla tua tavola: è la bontà genuina della Masseria Buongusto!", nil, "Oh oh oh, salve. Sono ⟦Greatfather Winter=Babbo Inverno⟧ e, per gentile concessione della brava gente della Masseria Buongusto... \"Dalla nostra fattoria alla tua tavola: è la bontà genuina della Masseria Buongusto\"... ti auguro una fantastica Festa del Grande Inverno.\n\nSe quest'anno sei stat<o/a> buon<o/a>, forse riceverai dei dolcetti dalla Masseria Buongusto come regalo per la Festa del Grande Inverno. Urrà.", 0x9a9ce503, 0x591cc909, 0x68b6c09d, nil, 0x296b27e3, "...m." },
  [7022] = { "⟦Greatfather Winter=Babbo Inverno⟧ è arrivato!", "Parla con ⟦Greatfather Winter=Babbo Inverno⟧: si trova vicino all'area dei venditori della Masseria Buongusto, a ⟦Ironforge=Forgiardente⟧.", "Buon Grande Inverno, amico! Non dimenticare di salutare ⟦Greatfather Winter=Babbo Inverno⟧! Se quest'anno sei stat<o/a> buon<o/a>, riceverai doni meravigliosi il giorno della Festa del Grande Inverno. Non dimenticare di dirgli cosa speri di ricevere quest'anno!\n\nE non dimenticare di fare scorta di dolcetti da regalare a chi è stato buono quest'anno. Abbiamo un'ampia scelta. Dalla nostra fattoria alla tua tavola: è la bontà genuina della Masseria Buongusto!", nil, "Oh oh oh, salve. Sono ⟦Greatfather Winter=Babbo Inverno⟧ e, per gentile concessione della brava gente della Masseria Buongusto... \"Dalla nostra fattoria alla tua tavola: è la bontà genuina della Masseria Buongusto\"... ti auguro una fantastica Festa del Grande Inverno.\n\nSe quest'anno sei stat<o/a> buon<o/a>, forse riceverai dei dolcetti dalla Masseria Buongusto come regalo per la Festa del Grande Inverno. Urrà.", 0xddbfaa79, 0x01d48083, 0xba4aa7ab, nil, 0x296b27e3, "...m." },
  [7023] = { "⟦Greatfather Winter=Babbo Inverno⟧ è arrivato!", "Parla con ⟦Greatfather Winter=Babbo Inverno⟧: si trova vicino all'area dei venditori della Masseria Buongusto, a ⟦Ironforge=Forgiardente⟧.", "Buon Grande Inverno, amico! Non dimenticare di salutare ⟦Greatfather Winter=Babbo Inverno⟧, che al momento si trova a ⟦Ironforge=Forgiardente⟧! Se quest'anno sei stat<o/a> buon<o/a>, riceverai dei dolcetti meravigliosi nel giorno della Festa del Grande Inverno. Non dimenticare di dirgli cosa speri di ricevere quest'anno!\n\nE non dimenticare di fare scorta di dolcetti da regalare a chi quest'anno è stato buono. Abbiamo un'ampia scelta. Dalla nostra fattoria alla tua tavola: è la bontà genuina della Masseria Buongusto!", nil, "Oh oh oh, salve. Sono ⟦Greatfather Winter=Babbo Inverno⟧ e, per gentile concessione della brava gente della Masseria Buongusto... \"Dalla nostra fattoria alla tua tavola: è la bontà genuina della Masseria Buongusto\"... ti auguro una fantastica Festa del Grande Inverno.\n\nSe quest'anno sei stat<o/a> buon<o/a>, forse riceverai dei dolcetti dalla Masseria Buongusto come regalo per la Festa del Grande Inverno. Urrà.", 0xddbfaa79, 0x01d48083, 0x79ea1c26, nil, 0x296b27e3, "...m." },
  [7024] = { "⟦Great-father Winter=Babbo Inverno⟧ è arrivato!", "Parla con ⟦Greatfather Winter=Babbo Inverno⟧: si trova vicino all'area dei venditori della Masseria Buongusto, a Orgrimmar.", "Buon Grande Inverno, amico! Non dimenticare di salutare ⟦Greatfather Winter=Babbo Inverno⟧, che al momento si trova a Orgrimmar! Se quest'anno sei stat<o/a> buon<o/a>, riceverai doni meravigliosi il giorno della Festa del Grande Inverno. Non dimenticare di dirgli cosa speri di ricevere quest'anno!\n\nE non dimenticare di fare scorta di dolcetti da regalare a chi è stato buono quest'anno. Abbiamo un'ampia scelta. Dalla nostra fattoria alla tua tavola: è la bontà genuina della Masseria Buongusto!", nil, "Oh oh oh, salve. Sono ⟦Greatfather Winter=Babbo Inverno⟧ e, per gentile concessione della brava gente della Masseria Buongusto... \"Dalla nostra fattoria alla tua tavola: è la bontà genuina della Masseria Buongusto\"... ti auguro una fantastica Festa del Grande Inverno.\n\nSe quest'anno sei stat<o/a> buon<o/a>, forse riceverai dei dolcetti dalla Masseria Buongusto come regalo per la Festa del Grande Inverno. Urrà.", 0x9a9ce503, 0x591cc909, 0x68b6c09d, nil, 0x296b27e3, "...m." },
  [7025] = { "Dolcetti per ⟦Greatfather Winter=Babbo Inverno⟧", "Porta 5 Pan di Zenzero e un ⟦Ice Cold Milk=Latte Ghiacciato⟧ a ⟦Greatfather Winter=Babbo Inverno⟧ a ⟦Ironforge=Forgiardente⟧.", "Ehi, puoi fare un favore a ⟦Greatfather Winter=Babbo Inverno⟧, ehm, <bimbo/bimba>?\n\nNon per parlare di me in terza persona senza motivo, ma ⟦Greatfather Winter=Babbo Inverno⟧ è all'opera da tutto il giorno e un dolcetto gli farebbe proprio comodo. Qualche biscotto di pan di zenzero e del latte ghiacciato per mandarli giù sarebbero proprio l'ideale. Credi di poter dare una mano a ⟦Greatfather Winter=Babbo Inverno⟧ e andarmene a prendere un po'?", "Tutto questo parlare di dolcetti mi ha fatto venire voglia di mangiarne qualcuno. Mmmm... biscotti di pan di zenzero e latte...", "Sei proprio un bell'aiutante per il vecchio ⟦Greatfather Winter=Babbo Inverno⟧, {name}. Buona Festa del Grande Inverno.\n\nEcco un pensierino... sai, per il disturbo.", 0xec79af5f, 0x98d20954, 0xd3822e00, 0x11c73f24, 0x004980cd, ".....", nil, nil, 0xcc6e16c8, nil, nil },
  [7028] = { "Mali contorti", "Raccogli 25 Sculture di Cristallo Teradrico per Willow, a ⟦Desolace=Desolanda⟧.", "Le caverne di cristallo di Terramok si trovano a ovest, nel profondo di Maraudon... È un luogo antico, ricco di storia. E io intendo metterci le mani sopra, almeno in parte, {class}. Dietro le porte gigantesche giacciono nascoste reliquie degli Dei Antichi.\n\nSe sei dispost<o/a> ad affrontare i mali contorti che si trovano a Maraudon, credo di poterti ricompensare a dovere. Raccogli le sculture di cristallo teradrico che trovi e riportale a me.\n\nUna volta avute le sculture, potrò... studiarle. Questi poteri sono rimasti assopiti troppo a lungo...", "Niente domande!\n\nSai cosa ti ho chiesto.", "Ah ah ah! Lo sapevo che saresti tornat<o/a>.\n\n<Willow borbotta.>\n\n...Così facile da convincere.\n\n...Farebbe qualsiasi cosa per il giusto prezzo. Eh eh eh...", 0xeb949bcd, 0x2ae5de19, 0x1db4989e, 0x6691d3a6, 0xc35764ff, "....." },
  [7029] = { "La corruzione di Vyletongue", "Riempi la ⟦Coated Cerulean Vial=Fiala Cerulea Ricoperta⟧ alla pozza di cristallo arancione di Maraudon.\n\nUsa la ⟦Filled Cerulean Vial=Fiala Cerulea Piena⟧ sulle Vylestem Vine per costringere i ⟦Noxxious Scion=Seguace Nocivo⟧ corrotti a uscire allo scoperto.\n\nCura 8 piante uccidendo i ⟦Noxxious Scion=Seguace Nocivo⟧, poi torna da ⟦Vark Battlescar=Vark Sfregio Fondo⟧, a ⟦Shadowprey Village=Predombra⟧.", "Un satiro di nome Vyletongue ha corrotto le caverne di Maraudon, soffocando la crescita di molte delle piante al loro interno.\n\nPrendi questa fiala, {name}. Riempila alla pozza di cristallo arancione che si trova dentro le caverne; il rivestimento interno della fiala neutralizzerà le tossine, trasformando il liquido in un rimedio curativo.\n\nTrova le viti Gamboatroce nelle caverne arancioni e versa su di esse il liquido purificato. La corruzione verrà purgata dalla pianta, ma sappi che Vyletongue continuerà a controllarla. Potrebbe usarla contro di te...", "Se riesci a curare la pianta, ricomincerà a crescere. Dobbiamo fare il possibile, {name}...", "Grazie di avermela riportata, {name}. Con il liquido rimasto che mi hai portato potrò continuare i miei studi.\n\nC'è ancora molto da fare, ma hai aiutato a curare parte della corruzione che Vyletongue ha diffuso in Maraudon. Ti prego, prendi questo con la mia gratitudine.", 0x7d91904f, 0x2b955e84, 0xe082ee66, 0x364cece8, 0x5d10207c, "....." },
  [7041] = { "La corruzione di Vyletongue", "Riempi la ⟦Coated Cerulean Vial=Fiala Cerulea Ricoperta⟧ alla pozza di cristallo arancione di Maraudon.\n\nUsa la ⟦Filled Cerulean Vial=Fiala Cerulea Piena⟧ sulle Vylestem Vine per costringere i ⟦Noxxious Scion=Seguace Nocivo⟧ corrotti a uscire allo scoperto.\n\nCura 8 piante uccidendo i ⟦Noxxious Scion=Seguace Nocivo⟧, poi torna da Talendria, al ⟦Nijel's Point=Presidio di Nijel⟧.", "Un satiro di nome Vyletongue ha corrotto le caverne di Maraudon, soffocando la crescita di molte delle piante al loro interno.\n\nPrendi questa fiala, {name}. Riempila alla pozza arancione corrotta che si trova dentro le caverne; il rivestimento interno della fiala neutralizzerà le tossine, trasformando il liquido in un rimedio curativo.\n\nTrova le viti Gamboatroce nelle caverne arancioni e versa su di esse il liquido purificato. La corruzione verrà purgata dalla pianta, ma sappi che Vyletongue continuerà a controllarla. Potrebbe usarla contro di te...", "Se riesci a curare la pianta, ricomincerà a crescere. Dobbiamo fare il possibile, {name}...", "Grazie di avermela riportata, {name}. Con il liquido rimasto che mi hai portato potrò continuare i miei studi.\n\nC'è ancora molto da fare, ma hai aiutato a curare parte della corruzione che Vyletongue ha diffuso in Maraudon. Ti prego, prendi questo con la mia gratitudine.", 0x7d91904f, 0xa6b69606, 0xfab7c5bd, 0x364cece8, 0x5d10207c, "....." },
  [7042] = { "Dolci rubati del Grande Inverno", "Trova l'investigatore della Masseria Buongusto scomparso nelle regioni innevate delle ⟦Alterac Mountains=Montagne d'Alterac⟧.", "Senti... non voglio rovinare la magia della stagione, ma la Masseria Buongusto avrebbe bisogno di un po' di aiuto, del tipo che voi avventurieri siete famosi per dare.\n\nCi manca un'importante spedizione di dolci che doveva rifornirci per la stagione, e ora ci manca anche l'agente della Masseria Buongusto che avevamo mandato sul campo a cercarla! Ti prego: secondo l'ultima notizia, la spedizione era nelle ⟦Alterac Mountains=Montagne d'Alterac⟧, ed è lì che il nostro uomo è andato a cercarla.\n\nVedi se sono lì, sani e salvi!", nil, "M-m-mi senti! Sia l-l-lodato il b-b-bilancio!\n\nNon sono davvero un p-p-pupazzo di neve: mi c-c-chiamo Sacks e l-l-lavoro per la f-f-filiale di ⟦Ironforge=Forgiardente⟧ della Masseria Buongusto... Mi hanno m-m-mandato qui a cercare un p-p-pacco scomparso, quando sono stato attaccato da una c-c-creatura che non avevo mai visto p-p-prima!\n\nChe f-f-freddo...", 0x3874de93, 0xfed7fa48, 0x497a89c9, nil, 0xe02f2537, "...m." },
  [7043] = { "Sei proprio cattivo...", "Trova il ⟦Stolen Treats=Dolce Rubato⟧ e riportalo a ⟦Wulmort Jinglepocket=Wulmort Taschepiene⟧ a ⟦Ironforge=Forgiardente⟧. Si crede che l'ultimo ad averlo avuto sia l'Abominable Greench, che si trova da qualche parte nelle regioni innevate delle ⟦Alterac Mountains=Montagne d'Alterac⟧.", "Una c-c-creatura chiamata «⟦The Abominable Greench=L'Abominevole Greench⟧» è quella c-c-che ha rubato la nostra spedizione di d-d-dolci, {name}. Ma s-s-sta' attent<o/a>! È lui c-c-che mi ha ridotto in questo s-s-stato, tutto coperto di neve!\n\nTi s-s-servirà un po' d'aiuto per a-a-affrontarlo. L'ho visto g-g-girare dappertutto dove ci sono gli y-y-yeti; di s-s-sicuro è qui da qualche p-p-parte! T-t-trova i dolci, {name}, r-r-riportali alla Masseria Buongusto a ⟦Ironforge=Forgiardente⟧ e d-d-di' loro che ho b-b-bisogno di essere s-s-scongelato!", "{name}, la nostra Festa del Grande Inverno sarà rovinata senza quei dolci per rifornirci! Persino Graccu non potrà condividere i suoi deliziosi pasticci di carne con tutti i bravi bambini e le brave bambine in questa stagione...", "L'hai trovato! Hai salvato la Festa del Grande Inverno della Masseria Buongusto!\n\nPovero Sacks... manderemo di sicuro una squadra lassù a trovare un modo per scongelarlo. Speriamo che torni in tempo per il giorno della Festa; dovrà però recuperare le ore di lavoro perse. Comunque, niente di tutto questo sarebbe stato possibile senza di te!", 0xdc4f5e6e, 0x8c241804, 0x01913b07, 0x5cb087ef, 0x84619c0c, "....." },
  [7044] = { "Leggende di Maraudon", "Recupera le due parti dello ⟦Scepter of Celebras=Scettro di Celebras⟧: la ⟦Celebrian Rod=Verga Celebriana⟧ e il ⟦Celebrian Diamond=Diamante Celebriano⟧.\n\nTrova un modo per parlare con Celebras.", "Un satiro oscuro chiamato sire Linguatroce ha diffuso il suo male in queste caverne tortuose, avvelenando la mente di tutti coloro che vi si trovano. Dimora ancora oltre i cristalli viola.\n\nLinguatroce ha anche creato un simbolo vivente della sua corruzione, chiamato Noxxion, che dimora oltre i cristalli arancioni. Insieme hanno rubato le due parti dello scettro di mio fratello. Celebras, mio fratello... vaga alla cieca là dentro, maledetto dalla corruzione.\n\nDevi aiutarlo! Trova i pezzi e parla con mio fratello... in qualche modo.", "Mi sono risvegliato da un incubo che sembrava non dovesse finire mai...", "Ora che hai recuperato le due parti del mio scettro, spero che un giorno Maraudon possa liberarsi della corruzione di Vyletongue.", 0x9af58870, 0xf9e13397, 0x41cb6b05, 0x82ff0f35, 0x9c0b7265, "....." },
  [7045] = { "Un grazie dalla Masseria Buongusto!", "Parla con ⟦Greatfather Winter=Babbo Inverno⟧ a ⟦Ironforge=Forgiardente⟧.", "Noi della Masseria Buongusto ti siamo grati per aver recuperato i dolci rubati, {name}. Per questo vorremmo offrirti un regalo speciale... consegnato nientemeno che da ⟦Greatfather Winter=Babbo Inverno⟧ in persona!\n\nTi prego, parla con ⟦Greatfather Winter=Babbo Inverno⟧: ti darà il tuo regalo della Festa del Grande Inverno da parte di tutti noi della Masseria Buongusto. Dalla nostra fattoria alla tua tavola, è sempre la bontà genuina della Masseria Buongusto... grazie a te, naturalmente!", nil, "Oh oh oh, salve, avventurier<o/a>!\n\nI goblin mi hanno detto che ti sei guadagnat<o/a> un regalo speciale in queste feste, e sono lieto di dartelo. Ecco qua: buona Festa del Grande Inverno, quest'anno e in tutte le stagioni a venire.", 0xfdb1c16f, 0x466d6e14, 0x1ebc2085, nil, 0xc8c04af1, "...m." },
  [7046] = { "Lo ⟦Scepter of Celebras=Scettro di Celebras⟧", "Assisti ⟦Celebras the Redeemed=Celebras il Redento⟧ mentre crea lo ⟦Scepter of Celebras=Scettro di Celebras⟧.\n\nParla con lui quando il rituale sarà concluso.", "Un tempo il mio scettro era per me una fonte di speranza. Il suo potere mi concedeva la libertà di spostarmi rapidamente in queste caverne. Speravo di portare pace allo spirito di mio zio... È un compito che ora affido a te.\n\nPerché le due parti tornino a essere una sola, avrò bisogno del tuo aiuto per compiere il rituale. Seguimi, ti prego, e ascolta le mie istruzioni mentre incanalo l'energia necessaria a riunire la verga e il diamante.\n\nInsieme creeremo di nuovo lo ⟦Scepter of Celebras=Scettro di Celebras⟧!", "Se vuoi ricominciare il rituale, abbandona il nostro primo tentativo e poi parlami di nuovo.", "Prendi questo, e sappi che il potere che ora ti è concesso va usato per il bene. Prosegui il tuo viaggio attraverso le caverne e, con un po' di speranza, troverai i resti di mio zio. Ti attendono molti pericoli, {name}.\n\nParlami di nuovo, se dovesse essercene bisogno.", 0x8ee6a5f3, 0xa2c0701f, 0xdf0c447d, 0x4b5207a1, 0xada0789a, "....." },
  [7061] = { "La ⟦The Feast of Winter Veil=Vigilia di Grande Inverno⟧", "Se vuoi, leggi il libro «⟦The Feast of Winter Veil=Vigilia di Grande Inverno⟧» per saperne di più sulla festa. Quando hai finito, consegnalo a ⟦Cairne Bloodhoof=Cairne Zoccolo Sanguinario⟧, a ⟦Thunder Bluff=Picco del Tuono⟧.", "Ecco: se vuoi saperne di più sulla Festa del Grande Inverno, leggi questo libro. Anche se credo che la nostra interpretazione della leggenda sia quella giusta, sono abbastanza studioso di leggende da apprezzare che tutte le informazioni siano raccolte in un'unica fonte.\n\nQuando hai finito, porta il libro a ⟦Cairne Bloodhoof=Cairne Zoccolo Sanguinario⟧, a ⟦Thunder Bluff=Picco del Tuono⟧. So per certo che gli farebbe piacere sapere che altri si interessano alle tradizioni del nostro popolo.", "Ti do il benvenuto a Mulgore e nella nostra umile comunità di ⟦Thunder Bluff=Picco del Tuono⟧, amico. Mi interesso sempre a chi sceglie di interessarsi al regno, al suo popolo e alle sue tradizioni. È per questo che ti trovi davanti a me?", "Le leggende e le tradizioni legate al Grande Inverno sono svanite dai pensieri della gente nel corso degli anni. Sì, so che i goblin stanno aiutando a far rivivere la stagione per i propri fini, ma il fatto che il nostro popolo vi rifletta, almeno in qualche forma, aiuta a mantenere vive queste tradizioni.\n\nIl tuo desiderio di andare oltre le cose materiali e conoscere il nostro passato ti fa onore, giovane {class}. Rendo omaggio alla tua saggezza.", 0xe673c3f4, 0x05622809, 0x0f6ff760, 0x35cce9a8, 0xb689b4a4, "....." },
  [7062] = { "Il senso della festa", "Parla con lo storico Karnik, alla Lega degli Esploratori di ⟦Ironforge=Forgiardente⟧, della Festa del Grande Inverno.", "Regali, dolcetti, doni... bah, dico io!\n\nQuei goblin inquinano il vero significato di questa stagione: la Festa del Grande Inverno. È un tempo di rinnovamento; la terra dorme sotto una coltre di neve portata da ⟦Greatfather Winter=Babbo Inverno⟧, che NON è quel buffone impacciato vestito di rosso laggiù!\n\nSe vuoi scoprire da te che cosa sia davvero la Festa, chiedi allo storico Karnik, alla Lega degli Esploratori. Sono sicuro che si stupirà che a qualcuno importi della storia più che dei regali.", nil, "La Festa del Grande Inverno, dici? Ahimè, un tempo aveva un significato più profondo per noi nani. Oggi sembra che altri abbiano trasformato la leggenda di ⟦Greatfather Winter=Babbo Inverno⟧ in qualcosa che aiuta a vendere dolciumi e regali.\n\nNon c'è da stupirsi che Goli sia amareggiato per un cambiamento del genere. Lui e altri nani come lui si aggrappano al nostro passato come a uno stendardo di guerra. Anche se credo che un po' di festa faccia sempre bene, è importante ricordare le origini della Festa.", 0x64e6e152, 0x703c0a33, 0x2a88d079, nil, 0xeebd4aa1, "...m." },
  [7063] = { "La ⟦The Feast of Winter Veil=Vigilia di Grande Inverno⟧", "Se vuoi, leggi il libro «⟦The Feast of Winter Veil=Vigilia di Grande Inverno⟧» per saperne di più sulla festa. Quando hai finito, consegnalo a re Magni Barbabronzea, a ⟦Ironforge=Forgiardente⟧.", "Ecco: se vuoi saperne di più sulla Festa del Grande Inverno, leggi questo libro. Anche se credo che la nostra interpretazione della leggenda sia quella giusta, sono abbastanza erudito da apprezzare che tutte le informazioni siano raccolte in un'unica fonte.\n\nQuando hai finito, porta il libro a re Magni Barbabronzea. So per certo che gli farebbe piacere sapere che altri si interessano alle leggende più antiche.", "Ti do il benvenuto nel Regno di ⟦Ironforge=Forgiardente⟧, amico. Mi interesso sempre a chi sceglie di interessarsi al regno, al suo popolo e alle sue tradizioni. È per questo che ti trovi davanti a me?", "Le leggende e le tradizioni legate al Grande Inverno sono svanite dai pensieri della gente nel corso degli anni. Pur riconoscendo che i goblin stanno aiutando a far rivivere la stagione per i propri fini, il fatto che i cittadini vi pensino, almeno in qualche forma, aiuta a mantenere vive queste tradizioni.\n\nIl tuo desiderio di andare oltre le cose materiali e conoscere il nostro passato ti fa onore, giovane {class}. Rendo omaggio alla tua erudizione.", 0xe673c3f4, 0x836487fd, 0x99477be7, 0x6d6ae1e2, 0x335365c7, "....." },
  [7064] = { "Corruzione della terra e del seme", "Uccidi ⟦Princess Theradras=Principessa Theradras⟧ e torna da Selendra, vicino a ⟦Shadowprey Village=Predombra⟧, a ⟦Desolace=Desolanda⟧.", "Nelle profondità di Maraudon vive una malvagia creatura del caos: la principessa Theradras, una forza elementale della terra legata agli Dei Antichi. Secoli fa, lei e Zaetar, primo figlio di Cenarius, iniziarono una relazione. La prole nata dalla loro unione divenne nota ai popoli di Kalimdor come i centauri. Che creature riconoscenti: i centauri uccisero Zaetar, e ora custodiscono le sue spoglie. La mia missione qui è trovare chi sia abbastanza potente da uccidere Theradras, così da recuperare le spoglie di Zaetar prima di tornare a ⟦Stonetalon=Petrartiglio⟧.", "Preferirei combattere questa battaglia da soli, ma non ci restano altre scelte: abbiamo bisogno di chi è più potente, e le razze di Azeroth hanno dimostrato senza ombra di dubbio di poter superare simili prove quando lavorano insieme. Per questo ci rivolgiamo a te per un aiuto.\n\nSpero solo che basti.\n\nZaetar, fratello di Remulos, ha portato molte sofferenze in questo mondo, e alla fine questo ha causato la sua stessa morte. Spero solo di non aver causato altre morti chiedendoti di aiutarci.", "Questa è una notizia meravigliosa, {name}! Grazie!\n\nParlerò con Marandis e chiederò il suo saggio parere sulle spoglie di Zaetar, ma almeno hai superato il compito più difficile.\n\nMi è stato detto che, se la nostra missione avesse avuto successo, avrei avuto il permesso di ricompensare chi ci ha aiutati. Mi sono stati dati questi oggetti come pegno da parte del nostro popolo: puoi sceglierne uno.", 0xf63286e3, 0x39812881, 0xa03316b0, 0x5dd13056, 0x57b19b51, "....." },
  [7065] = { "Corruzione della terra e del seme", "Uccidi ⟦Princess Theradras=Principessa Theradras⟧ e torna dal protettore Marandis al ⟦Nijel's Point=Presidio di Nijel⟧, a ⟦Desolace=Desolanda⟧.", "Nelle profondità di Maraudon vive una creatura del caos e del male, {name}. La principessa Theradras è una forza elementale della terra in qualche modo legata agli Dei Antichi. Secoli fa, Zaetar, primo figlio di Cenarius, andò a cercarla. La prole della loro... relazione sono le creature conosciute come centauri. Che creature riconoscenti: i centauri uccisero Zaetar, e ora Theradras custodisce le sue spoglie. La mia missione qui è trovare chi sia abbastanza potente da uccidere Theradras, così da recuperare le spoglie di Zaetar prima di tornare a ⟦Stonetalon=Petrartiglio⟧.", "Sento il peso di imporre la mia supplica alle razze mortali, ma non ci restano altre scelte. Le razze di Azeroth hanno dimostrato senza ombra di dubbio di poter superare simili prove quando lavorano insieme, ed è a loro che chiedo aiuto.\n\nSpero solo che basti.\n\nZaetar, fratello di Remulos, ha portato molte sofferenze in questo mondo, e alla fine questo ha causato la sua stessa morte. C'è una lezione per tutti noi, se siamo abbastanza saggi da vederla.", "Questa è una notizia meravigliosa, {name}! Grazie!\n\nAnche se mi preoccupa che tu non sia riuscit<o/a> a riportare le spoglie di Zaetar, chi sono io per mettere in dubbio la volontà del primogenito di Cenarius? Forse ora la volontà dei centauri si spezzerà e la loro sete di sangue si placherà: possiamo solo sperarlo.\n\nIn caso di successo della nostra missione, mi sono stati dati questi oggetti per ricompensare chiunque ci avesse aiutati. Puoi sceglierne uno come pegno di gratitudine.", 0xf63286e3, 0x7c3b8219, 0x4160b7a5, 0x014b5981, 0xc549a228, "....." },
  [7066] = { "Il ⟦Seed of Life=Seme della Vita⟧", "Cerca Remulos a ⟦Moonglade=Radaluna⟧ e dagli il ⟦Seed of Life=Seme della Vita⟧.", "I centauri nati dalla colpa, i miei figli e le mie figlie, hanno bisogno del loro padre.\n\nGuardati intorno: questo luogo risuona di speranza e di tutto ciò che predica mio padre Cenarius. È nato da me! E non posso portarglielo via... nemmeno per i loro crimini contro di me.\n\nMa c'è una cosa che vorrei chiederti, per dare pace all'animo di mio fratello. Prendi questo... è il primo seme caduto dalla vita che le mie spoglie hanno nutrito. Digli che il mio spirito rimane qui, e che continuo a vivere. Sono certo che capirà.", "Hai addosso l'odore della corruzione, {name}... come molti avventurieri di questi tempi. Ma in te c'è qualcosa di diverso. Sei venut<o/a> a parlarmi di qualcosa? Hai un'aura che mi sembra familiare, ma non riesco a capire da dove.\n\nTi prego, ti scongiuro, dimmi perché hai chiesto udienza presso di me.", "Dunque mio fratello ha finalmente trovato la pace? Sono fiero di aver vissuto abbastanza da vedere questo giorno. In tutta la sua arroganza e la sua rabbia, credevo davvero che fosse perduto per noi, ma questo... questo simbolo del suo sacrificio dimostra soltanto che non è perduto: è soltanto rinato. Prende il suo posto nella natura, come era suo dovere.\n\nGrazie, {name}. Portandomi questo, hai custodito un po' della speranza che credevo di aver perduto. Questo seme un giorno sarà importante per i popoli di questa terra dilaniata dalla guerra... lo sento.", 0xe1cc854f, 0xd69615e8, 0x3d27e50c, 0xd29e327e, 0x9f7959fd, "....." },
  [7067] = { "⟦The Pariah's Instructions=Istruzioni dell'Emarginato⟧", "Leggi le Istruzioni dell'Emarginato. Poi recupera l'⟦Amulet of Union=Amuleto dell'Unione⟧ a Maraudon e riportalo all'Emarginato centauro, nel sud di ⟦Desolace=Desolanda⟧.", "Anche se sono stato esiliato come eretico, le mie convinzioni restano vere: questo basta a spingermi avanti. Ma perché il mio destino si compia, mi serve l'aiuto di un estraneo... qualcuno che non appartenga a nessuna tribù di centauri.\n\nIl compito richiede che qualcuno entri nelle sale sacre di Maraudon, una tomba che il mio popolo protegge e in cui solo i più devoti hanno il permesso di entrare.\n\nSe accetti di aiutarmi, ti basta annuire. Ti passerò una pergamena con le mie istruzioni. Leggila e rifletti sulle mie parole.", "Cosa hai deciso, {name}? Puoi aiutarmi? Metterai piede sul suolo sacro per aiutarmi a forgiare un'unica, grande tribù di centauri!?", "È lui, {race}! È proprio lui! Ora posso cominciare la grande impresa di unire le tribù. Grazie.\n\nPrendi questo per il tuo impegno, ti prego. Spero che la prossima volta che ci incontreremo sarà in circostanze molto diverse.", 0xd8aa8c13, 0x644fa901, 0x17cdfc7b, 0xa3331956, 0x76f3983f, "....." },
  [7068] = { "Frammenti di Cristalli d'Ombra", "Raccogli 10 Frammento di Cristalli d'Ombra a Maraudon e riportali a Uthel'nay a Orgrimmar.", "Magie potenti si trovano nel luogo sacro dei centauri... il luogo sacro di Maraudon. Le tribù di centauri di ⟦Desolace=Desolanda⟧ proteggono quel posto con la vita, ma non possono impedirci di prendere quello che ci serve.\n\nTu, tu vai in questo posto chiamato Maraudon e trovi le creature di roccia fatte di cristalli d'ombra. Tu porti a me i cristalli viola, e Uthel'nay fa qualcosa per te per il tuo tempo.\n\nIl posto è pericoloso, quindi forse tu porti qualche amico.", "Tu trovato i cristalli? Rituali di potere, incantesimi di grande forza: quei cristalli d'ombra forse molto utili in tutti i tipi di magie arcane.", "Ah, questi essere perfetti per mie magie. Ecco, tu prendi uno di questi monili e va' per la tua strada... io avere tanto da studiare.", 0xc66ff161, 0xa2e2dbe6, 0x385bc6e0, 0xcae8139d, 0x09e2939a, "....." },
  [7070] = { "Frammenti di Cristalli d'Ombra", "Raccogli 10 Frammento di Cristalli d'Ombra a Maraudon e riportali all'arcimago Tervosh a Theramore, sulla costa di ⟦Dustwallow Marsh=Acquemorte⟧.", "Di recente ho cominciato a studiare vari cristalli e le loro proprietà arcane. Lady Proudmoore mi ha dato il permesso di chiedere ai viaggiatori diretti in ⟦Desolace=Desolanda⟧ di cercare un luogo chiamato Maraudon. All'interno del tempio in rovina ci sono grandi elementali composti di pietre violacee che ho chiamato cristalli d'ombra.\n\nSe decidi di andare da quelle parti e trovi qualcuno di quei cristalli, te ne sarei molto grato. Potrei perfino ricavarne un monile per te, se lo desideri.", "Hai già fatto il viaggio? Mi rendo conto che sarebbe piuttosto pericoloso, ma se ci riuscissi, ne varrebbe davvero la pena.", "Sono perfetti, {name}. A dire il vero sono tornati di là anche altri avventurieri, e con i loro cristalli sono riuscito a ricavare questi... ti prego, prendine uno per il tuo duro lavoro. E grazie ancora per altri campioni da studiare.", 0xc66ff161, 0xec999ae3, 0x8f09c391, 0x23f22516, 0x340dad0c, "....." },
  [7081] = { "I cimiteri della ⟦Alterac Valley=Valle d'Alterac⟧", "Assalta un cimitero, poi torna dal sergente Durgen Piccatonante nelle ⟦Alterac Mountains=Montagne d'Alterac⟧.", "I cimiteri della ⟦Alterac Valley=Valle d'Alterac⟧ sono territori preziosi. Sia l'⟦Horde=Orda⟧ sia l'⟦Alliance=Alleanza⟧ combattono ferocemente per questi luoghi sacri. Tu, {name}, sei pront<o/a> a unirti alla lotta?\n\nVoglio che tu assalti un cimitero nemico. Trova un cimitero con uno stendardo dell'⟦Horde=Orda⟧ nel mezzo e strappalo da terra! Fallo, e il tuo compito sarà concluso...\n\nMa se riesci anche a tenere il cimitero per qualche minuto, le nostre truppe arriveranno presto a darti il cambio.", "{name}, non hai ancora assaltato un cimitero. Torna da me quando avrai portato a termine il compito!", "Ben fatto! I cimiteri sono vitali per il nostro controllo della ⟦Alterac Valley=Valle d'Alterac⟧. Ogni volta che ne conquisti uno, aiuti a garantire la sovranità dell'Alleanza qui.\n\nOra va', {name}. Torna in battaglia, e se vedi un cimitero sotto il controllo dell'Orda... sai cosa fare!", 0x0ef1232d, 0xee980018, 0x60742525, 0x6410f753, 0xa806e851, "....." },
  [7082] = { "I cimiteri d'Alterac", "Assalta un cimitero, poi torna dalla caporale Teeka Ringhiorosso nelle ⟦Alterac Mountains=Montagne d'Alterac⟧.", "Le linee del fronte nella ⟦Alterac Valley=Valle d'Alterac⟧ cambiano di continuo. I territori passano di mano in mano mentre affrontiamo i nostri avversari in combattimenti mortali. E i cimiteri, {name}, sono i luoghi dove le battaglie infuriano di più.\n\nVoglio che tu attacchi un cimitero tenuto dall'⟦Alliance=Alleanza⟧! Trova un cimitero con uno stendardo dell'⟦Alliance=Alleanza⟧ nel mezzo e strappalo da terra.\n\nFallo e il tuo compito per me sarà concluso, ma... se tieni il cimitero per qualche minuto, sarà nostro e le truppe verranno a darti il cambio.", "Attacca un cimitero tenuto dall'⟦Alliance=Alleanza⟧!", "Ben fatto, {name}! Con ogni cimitero sotto il nostro controllo, gli spiriti dei nostri nemici vagheranno sempre più smarriti e senza meta.", 0x365e6d1f, 0xd4c28523, 0xa7601704, 0x81601597, 0x8a202126, "....." },
  [7101] = { "Torri e fortilizi", "Conquista una torre nemica, poi torna dalla caporale Teeka Ringhiorosso nelle ⟦Alterac Mountains=Montagne d'Alterac⟧.", "Le torri e i fortilizi sono posizioni importanti, e dobbiamo conquistarli e tenerli tutti! Perciò voglio che tu attacchi un fortilizio controllato dal nemico.\n\nPer farlo, entra in uno che abbia uno stendardo dell'⟦Alliance=Alleanza⟧. Dentro vedrai un altro stendardo. Strappalo, e al suo posto comparirà uno stendardo bianco dell'⟦Horde=Orda⟧. Ben fatto!\n\nA quel punto il tuo compito per me sarà concluso, ma se tieni la posizione abbastanza a lungo, e se l'⟦Alliance=Alleanza⟧ non se la riprende, verrà distrutta!", "Non hai ancora assaltato un fortilizio, {name}! Aspetti che siano altri a prendersi la tua gloria?", "Ho saputo del successo della tua missione! Ne sono lieto...\n\nOra le nostre truppe possono avanzare impunemente e mostrare all'⟦Alliance=Alleanza⟧ che la ⟦Alterac Valley=Valle d'Alterac⟧ non è posto per loro!", 0xfe4de82e, 0x1a2354d0, 0xf14c6692, 0x80a3e6d5, 0x1ed25e52, "....." },
  [7102] = { "Torri e fortilizi", "Distruggi lo stendardo di una torre o di un fortilizio nemico, poi torna dal sergente Durgen Piccatonante nelle ⟦Alterac Mountains=Montagne d'Alterac⟧.", "Le torri e i fortilizi sono posizioni difensive chiave, perciò dobbiamo tenerne il più possibile! Voglio che tu attacchi una torre o un fortilizio nella ⟦Alterac Valley=Valle d'Alterac⟧.\n\nPer farlo, entra in una torre con uno stendardo dell'⟦Horde=Orda⟧ in cima. Dentro vedrai un altro stendardo nemico. Strappalo, e al suo posto comparirà uno stendardo bianco dell'⟦Alliance=Alleanza⟧. Ben fatto!\n\nA quel punto la tua missione per me sarà conclusa, ma se tieni la zona abbastanza a lungo, e se l'⟦Horde=Orda⟧ non se la riprende, verrà distrutta!", "Non hai ancora assaltato una torre, {name}! Che cosa aspetti?", "Ho ricevuto un rapporto dal campo secondo cui hai aiutato a conquistare uno stendardo nemico. Ben fatto, {name}! Con le loro truppe a distanza fuori posizione, possiamo spostare in avanti la linea di battaglia!", 0xfe4de82e, 0x881b36ad, 0x7db5ba5f, 0x5db7f738, 0xbff4343f, "....." },
  [7121] = { "Il quartiermastro", "Parla con il quartiermastro dei Piccatonante.", "{name}, il nostro quartiermastro mi ha incaricato di mandargli le nuove reclute. Gli servono rifornimenti dai depositi nascosti nelle miniere d'Alterac, e probabilmente manderà te a prenderli.\n\nSegui la strada. Troverai il nostro quartiermastro a ovest.", nil, "Fa piacere vedere truppe fresche qui, {name}, ma con un po' di fortuna finirai presto in azione e non resterai fresc<o/a> a lungo!\n\nParlami di nuovo. Ho dei compiti di cui devo discutere con te...", 0x9297b1d8, 0x5b898a2d, 0x2651f8ba, nil, 0x22790563, "...m." },
  [7122] = { "Conquista una miniera", "Conquista una miniera che non sia sotto il controllo dei Piccatonante, poi torna dal sergente Durgen Stormpike nelle ⟦Alterac Mountains=Montagne d'Alterac⟧.", "Le miniere della ⟦Alterac Valley=Valle d'Alterac⟧ custodiscono ben più che minerali. Sia i Lupi Bianchi sia i Piccatonante hanno nascosto le scorte in eccesso nelle miniere di Ferrofondo e di Dentefreddo... non è una cattiva idea, se solo riuscissimo a mantenerne il controllo!\n\nConquista una miniera, poi torna da me. Per conquistare una miniera, entra in una che non controlliamo e uccidi il suo capo. Fatto questo, la miniera sarà nostra e manderemo truppe a proteggerla!", "Non hai ancora conquistato la miniera, {name}!\n\nQuando controlleremo una miniera, sarà molto più facile ricavarne minerali e rifornimenti.", "Ce l'hai fatta! Ben fatto, {name}!\n\nQuando controlliamo una miniera e vi teniamo delle truppe, è molto più facile ricavarne minerali e rifornimenti.", 0x3ee7a5e5, 0x6d34d083, 0xded25628, 0x0830eb62, 0x62b3948e, "....." },
  [7123] = { "Parla con il nostro quartiermastro", "Parla con il quartiermastro dei Lupi Bianchi.", "{name}, il quartiermastro dei Lupi Bianchi cerca reclute per incarichi che portano nelle miniere della ⟦Alterac Valley=Valle d'Alterac⟧. Parla con lui; ti dirà di più.\n\nSegui la strada verso ovest fino al fortilizio, poi prendi l'uscita ovest e troverai il nostro quartiermastro.", nil, "Salute, {name}! Fa piacere vedere <un/una> {class} come te, <desideroso/desiderosa> di fare la sua parte per l'⟦Horde=Orda⟧. Parlami di nuovo, perché ho compiti vitali per te...", 0x7103eddb, 0xf96af497, 0x2e72736a, nil, 0x7f986c13, "...m.", nil, nil, nil, nil, 0x306868db },
  [7124] = { "Conquista una miniera", "Conquista una miniera, poi torna dalla caporale Teeka Ringhiorosso nelle ⟦Alterac Mountains=Montagne d'Alterac⟧.", "Mentre la battaglia infuria sulle terre della ⟦Alterac Valley=Valle d'Alterac⟧, infuria anche nelle miniere di Dentefreddo e di Ferrofondo. Sono entrambe ricche di minerali ed entrambe servono da deposito per i rifornimenti: non stupisce che siano tanto ambite!\n\nAiuta il nostro sforzo bellico, {name}! Conquista una delle miniere per l'⟦Horde=Orda⟧! Per conquistare una miniera, entra in una che non controlliamo e uccidi il suo capo. Fatto questo, la miniera sarà nostra e manderemo truppe a proteggerla!", "Non hai ancora conquistato una miniera, {name}! Trovane una che non controlliamo e sconfiggi il suo capo!", "Hai conquistato una miniera! Con i nostri guerrieri a proteggerla, sarà molto più semplice estrarre minerali dalle sue profondità o raccogliere i rifornimenti nascosti lì.\n\nBen fatto, {name}. Ciò che hai compiuto è un grande aiuto per il nostro sforzo bellico.", 0x3ee7a5e5, 0x4079d0e8, 0x09ff1a23, 0x524d28bc, 0xf7493bdd, "....." },
  [7141] = { "La battaglia d'Alterac", "Entra nella ⟦Alterac Valley=Valle d'Alterac⟧, sconfiggi il generale dell'⟦Horde=Orda⟧, Drek'thar, poi torna dalla prospettrice Molapietra nelle ⟦Alterac Mountains=Montagne d'Alterac⟧.", "La ⟦Explorers' League=Lega degli Esploratori⟧ crede che nella ⟦Alterac Valley=Valle d'Alterac⟧ ci siano dei reperti, ma gli orchi dei Lupi Bianchi non ci lasciano esplorare. Non possiamo permettere all'⟦Horde=Orda⟧ di fermare le nostre ricerche! Sconfiggi il generale dei Lupi Bianchi, ⟦Drek'Thar=Drek'thar⟧. Morto lui, gli orchi perderanno il loro vantaggio.\n\n⟦Drek'Thar=Drek'thar⟧ si trova nella ⟦Frostwolf Keep=Rocca dei Lupi Bianchi⟧, nel sud della ⟦Alterac Valley=Valle d'Alterac⟧. Sconfiggilo, poi torna da me.", "Va', {name}. Va' nella ⟦Alterac Valley=Valle d'Alterac⟧ e sconfiggi il generale degli orchi!", "Ben fatto, {name}! Ora che l'Orda si è presa una bella batosta con la morte del suo generale, avremo il respiro che ci serve per esplorare!", 0xfad36f94, 0xed62d3d9, 0xf217086f, 0xbb5127ce, 0x5e1fca36, "....." },
  [7142] = { "La battaglia per Alterac", "Entra nella ⟦Alterac Valley=Valle d'Alterac⟧ e sconfiggi il generale dei nani, ⟦Vanndar Stormpike=Vanndar Piccatonante⟧. Poi torna da ⟦Voggah Deathgrip=Voggah Morsanera⟧ nelle ⟦Alterac Mountains=Montagne d'Alterac⟧.", "I nani Piccatonante e i loro alleati hanno invaso la ⟦Alterac Valley=Valle d'Alterac⟧, e dobbiamo cacciarli! Per vincere la battaglia per Alterac dobbiamo sconfiggere il loro generale, ⟦Vanndar Stormpike=Vanndar Piccatonante⟧!\n\nTroverai Vanndar a Dun Baldar, nel nord della ⟦Alterac Valley=Valle d'Alterac⟧.\n\nDistruggilo, {name}, poi torna da me.", "Non tollereremo i nani in casa nostra! Piomba sui nostri nemici e sconfiggi il loro capo, il generale Stormpike!", "Ben fatto, {name}! I Piccatonante non hanno speranze in questa folle invasione.\n\nAh! Finora tutto quello che sono riusciti a fare è farsi uccidere il generale!", 0x7151ae32, 0x226f738f, 0xe28e0e37, 0x15e3437d, 0x2a78fe49, "....." },
  [7161] = { "Il banco di prova", "Raggiungi la Caverna degli Zampafurente, a sud-est della base principale nella ⟦Alterac Valley=Valle d'Alterac⟧, e trova lo ⟦Frostwolf Banner=Stendardo dei Lupi Bianchi⟧. Riporta lo ⟦Frostwolf Banner=Stendardo dei Lupi Bianchi⟧ al maestro di guerra Laggrond.", "Salute, {class}. È passato molto tempo dall'ultima volta che abbiamo potuto rispondere al richiamo della battaglia. I vecchi sentimenti tardano a destarsi, ma una volta risvegliati fanno ribollire il sangue. La furia della battaglia ritorna...\n\nTutti i nuovi arrivati nella Valle devono prima compiere il rito della battaglia.\n\nNel profondo della caverna degli gnoll Zampafurente c'è uno stendardo dei Lupi Bianchi. Avventurati là dentro e recupera lo stendardo. Riportamelo e ti concederò il fregio di iniziato dei Lupi Bianchi.", "Svegliati! Svegliati, {name}! Non è un sogno. Sei davvero nel bel mezzo di una battaglia furiosa!", "Quel bruciore che senti è la tua anima che si risveglia. Il tuo spirito ha accolto la chiamata alle armi.\n\nOra sei <uno/una> dei Lupi Bianchi, {name}. Congratulazioni.\n\nPorta sempre con te questo fregio. Man mano che salirai di grado tra i Lupi Bianchi, sostituirò il fregio con altri, più potenti.\n\nForse un giorno sarai <osannato/osannata> dal ⟦Frostwolf Clan=Clan Lupi Bianchi⟧. Se quel giorno arriverà, ti sarà concesso l'Eye of Command.", 0x04d66e20, 0x28b91a77, 0x2c393304, 0xa9b6cff9, 0x79b63c2d, "....." },
  [7162] = { "Il banco di prova", "Raggiungi la Caverna di Algidala, a sud-ovest di Dun Baldar nella ⟦Alterac Valley=Valle d'Alterac⟧, e recupera lo ⟦Stormpike Banner=Stendardo dei Piccatonante⟧. Riporta lo ⟦Stormpike Banner=Stendardo dei Piccatonante⟧ al tenente Haggerdin nelle ⟦Alterac Mountains=Montagne d'Alterac⟧.", "Sei arrivat<o/a> appena in tempo, {class}. Questi selvaggi dei Lupi Bianchi non si arrendono mai! Dobbiamo mostrare loro la potenza dei Piccatonante. Devono piegarsi alla nostra superiorità.\n\nPrima di dirigerti sul campo di battaglia, vorrai unirti alle file dei Piccatonante.\n\nA sud-ovest di Dun Baldar troverai la Caverna di Algidala. Nel profondo della caverna è piantato uno ⟦Stormpike Banner=Stendardo dei Piccatonante⟧. Avventurati là dentro e recupera quello stendardo. Riportamelo e ti sarai guadagnat<o/a> un fregio di iniziato dei Piccatonante.", "Attent<o/a> alle arpie della regione, {class}. Non ci penseranno due volte a strapparti la gola!", "Prendi questo fregio e indossalo con orgoglio, {name}. Man mano che crescerà il tuo grado tra i Piccatonante, crescerà anche il fregio. Torna da me man mano che guadagni onore presso i Piccatonante, e sostituirò il tuo fregio con altri, più potenti.\n\nForse un giorno diventerai una leggenda su questo campo di battaglia. Se quel giorno arriverà, ti sarà concesso l'Eye of Command.", 0x04d66e20, 0xc4061330, 0x0ec79653, 0x04014edf, 0x21a33717, "....." },
  [7163] = { "Alzati e fatti riconoscere", nil, nil, "<Il maestro di guerra Laggrond ti saluta.>\n\nÈ giunto il tuo momento, {name}. Hai fatto molto per il ⟦Frostwolf Clan=Clan Lupi Bianchi⟧ e così ti sei guadagnat<o/a> un posto non solo come soldato dei Lupi Bianchi, ma anche come <amico/amica>.\n\nBen fatto! Presenta il tuo fregio di iniziato.", "Questo nuovo fregio rispecchia il tuo grado tra i Lupi Bianchi. Tienilo sempre con te.\n\nE, {class}... muori con onore!", 0xf6a70096, nil, nil, 0xf180292a, 0xb16f59f2, ".mm.." },
  [7164] = { "Onorato nel clan", nil, nil, "È bello rivederti, {class}. Non mi aspettavo che tornassi. Eppure hai dato prova di coraggio e di onore come soldato dei Lupi Bianchi.\n\nIl tuo momento è giunto di nuovo, {name}. Ti sei guadagnat<o/a> un nuovo grado e, con esso, un nuovo fregio che attesta la tua ascesa.\n\nPresenta il tuo fregio.", "<Il maestro di guerra Laggrond fa il saluto militare.>\n\nVa', {name}! Continua a difendere i Lupi Bianchi. Questa guerra va vinta! Per ⟦Drek'Thar=Drek'thar⟧! Per il Capoguerra!", 0x47970b10, nil, nil, 0x9a6b061c, 0x88edba81, ".mm.." },
  [7165] = { "Reverenza guadagnata", nil, nil, "Tanti caduti. Il sangue inzuppa i campi. Eppure... tu vivi... Hai perseverato. Hai guidato i nostri eserciti a molte vittorie. Per questo, soldato, ti sei guadagnat<o/a> un nuovo grado.\n\nPresenta il tuo fregio.", "<Il maestro di guerra Laggrond ruggisce.>\n\nHanno già cominciato a raccontare le tue gesta, soldato. I Piccatonante tremano di paura quando si pronuncia il tuo nome. Avanti così!", 0x5151253a, nil, nil, 0x47380b2f, 0x1981d18b, ".mm.." },
  [7166] = { "Eroi leggendari", nil, nil, "Irradi comando e potere, {class}. Osannat<o/a> agli occhi dei Lupi Bianchi: il nemico trema al solo sentire il tuo nome.\n\nAlzati, <Eroe/Eroina> dei Lupi Bianchi. Alzati e ricevi onore!\n\nPresenta il tuo fregio.", "Presto tutti sul campo di battaglia saranno sotto il tuo sguardo vigile. Il comando della Valle e delle sue truppe sarà tuo!", 0x183f4102, nil, nil, 0x51a77e3b, 0xcebe3776, ".mm.." },
  [7167] = { "L'Eye of Command", nil, nil, "⟦Drek'Thar=Drek'thar⟧ canta le tue lodi. Kalimdor è in fermento per i racconti delle tue gesta. Il Capoguerra è raggiante: la tua strenua difesa del nostro clan gli ha fatto molto piacere.\n\nTi sei guadagnat<o/a> l'Eye of Command.\n\nPresenta il tuo fregio, comandante {name}.", "Incanala il potere del fregio. Fa' che il nemico senta le tue parole. La potenza dell'⟦Horde=Orda⟧ è indiscutibile!", 0x4cd4f1de, nil, nil, 0xcc2b7cbc, 0x2879f838, ".mm.." },
  [7168] = { "Alzati e fatti riconoscere", nil, nil, "I più non vivono abbastanza a lungo da elevarsi al di sopra della propria mediocrità. Hai dimostrato di essere un soldato esemplare, {class}. È giunto il momento.\n\nPresenta il tuo fregio.", "Che i nostri nemici vedano che a colpirli è stato un soldato di grado! Combatti per la gloria dei Piccatonante!", 0xf6a70096, nil, nil, 0x259975b2, 0xc0c34438, ".mm.." },
  [7169] = { "Onorato nella Guardia", nil, nil, "La base è in fermento per le notizie delle tue imprese nel ⟦Field of Strife=Pian della Discordia⟧! Hai inferto colpi possenti al nostro nemico, schiacciandone il morale! Per questo ti sei guadagnat<o/a> un grado d'onore tra i Piccatonante.\n\nPresenta il tuo fregio.", "Il re è stato informato del tuo eroismo al fronte, {class}. Continua la tua strenua difesa della ⟦Stormpike Guard=Guardia dei Piccatonante⟧!", 0xe9b6400b, nil, nil, 0x17f2f423, 0xf8145b52, ".mm.." },
  [7170] = { "Reverenza guadagnata", nil, nil, "Devo saperlo, {name}. Quando guardi il nemico dritto negli occhi, vedi la paura? Ora si fanno piccoli in tua presenza? Devono capire di essere sconfitti!\n\nTi sei guadagnat<o/a> la reverenza della Guardia. Presenta il tuo fregio!", "Quando ci siamo conosciuti, non avrei mai immaginato di avere davanti <un/una> <futuro/futura> <eroe/eroina>. Avanti così, soldato!", 0x5151253a, nil, nil, 0x55b1b3b3, 0x49a6b49c, ".mm.." },
  [7171] = { "Eroi leggendari", nil, nil, "Davanti a me c'è <un/una> grande <eroe/eroina> dell'⟦Alliance=Alleanza⟧, ormai osannat<o/a>.\n\n<Il tenente Haggerdin fa il saluto militare.>\n\nPochi hanno ottenuto un grado simile tra i Piccatonante. Ho visto il nemico cadere davanti a te. Ho visto la sua determinazione sgretolarsi in tua presenza. Quando entri nella mischia, diventi il faro di speranza delle nostre forze!\n\nPresenta il tuo fregio.", "Di certo sarai tu a portare l'Eye of Command!", 0x183f4102, nil, nil, 0x2e17a93c, 0x01ec6f86, ".mm.." },
  [7172] = { "L'Eye of Command", nil, nil, "Fa' sentire loro la tua voce, comandante {name}! Fa' che conoscano la paura. Mostra loro quale potere hanno i Piccatonante tra le loro file!\n\nPresenta il tuo fregio.", "Sei tu che devi guidare le nostre truppe alla vittoria, comandante! I soldati sono al tuo comando. Eseguiranno i tuoi ordini diretti. Guidali... Schiaccia i Lupi Bianchi.", 0x4cd4f1de, nil, nil, 0xeffb93ec, 0xc004124f, ".mm.." },
  [7181] = { "La leggenda di Korrak", "Secondo la leggenda, il capo dei possenti troll Asciafredda compare quando vuole per seminare il caos tra gli abitanti della ⟦Alterac Valley=Valle d'Alterac⟧.\n\nSe Korrak dovesse farsi vedere, distruggilo e torna dal maestro di guerra Laggrond.", "I Piccatonante invasori non sono l'unica minaccia nella regione, soldato. La guerra nella Valle si combatte su due fronti. Anche i troll cannibali Asciafredda si contendono il potere.\n\nSono guidati da ⟦Korrak the Bloodrager=Korrak la Furia del Sangue⟧, una bestia crudele e astuta.\n\nUn attacco contro Korrak potrebbe infliggere un colpo devastante al clan degli Asciafredda. Uccidi la bestia e sarai ricompensat<o/a>!", nil, nil, 0xed7de448, 0xd4561934, 0xff819931, nil, nil, "...mm" },
  [7201] = { "L'ultimo elemento", "Raggiungi i ⟦Blackrock Depths=Sotterranei di Roccianera⟧ e recupera 10 ⟦Essence of the Elements=Essenza degli Elementi⟧. Il tuo primo istinto è di cercare tra i golem e i loro costruttori. Ricordi anche che Vivian Lagrave ha borbottato qualcosa sugli elementali.", "C'è lavoro per chi si avventura nelle profondità, {name}.\n\nI Ferroscuro sono diventati maestri nella creazione di golem estremamente potenti.\n\nI primi rapporti delle nostre spie indicano che i nani usano una fonte di energia unica per dare alle loro creazioni un potere distruttivo senza pari.\n\nImmagina cosa potremmo fare con i nostri abomini se mettessimo le mani su questa essenza degli elementi! Metti a soqquadro quella città se serve, ma non tornare finché non avrai trovato l'essenza! Il compenso varrà il rischio.", "Mostramele!", "Magnifico! Le farò mandare subito con un corriere a ⟦Undercity=Sepulcra⟧!\n\nQuanto a te, ecco la paga, come promesso. Tieniti il resto, sudicia bestia!", 0x19b2e88f, 0xfd70e576, 0xf6bdad3c, 0xeae5b052, 0x635624c4, "....." },
  [7202] = { nil, "Secondo la leggenda, il capo dei possenti troll Asciafredda compare quando vuole per seminare il caos tra gli abitanti della ⟦Alterac Valley=Valle d'Alterac⟧.\n\nSe Korrak dovesse farsi vedere, distruggilo e torna dal tenente Haggerdin nelle ⟦Alterac Mountains=Montagne d'Alterac⟧.", "I troll Asciafredda, nativi della regione, sono selvaggi spietati che non desiderano altro che aggiungere le nostre ossa al loro stufato disgustoso.\n\nDobbiamo mostrare loro la nostra forza!\n\nAbbiamo recuperato dalle loro caverne dei tomi che descrivono la loro gerarchia. Questi reperti indicano che il loro capo, ⟦Korrak the Bloodrager=Korrak la Furia del Sangue⟧, tende a restare nascosto finché non ha un motivo per farsi vedere.\n\nLa morte di Korrak sarebbe la morte del clan degli Asciafredda! Uccidilo e torna.", nil, nil, 0x7f5c48d4, 0xe603d27a, 0x8a04047a, nil, nil, "e..mm" },
  [7221] = { "Parla con la prospettrice Molapietra", "Parla con la prospettrice Molapietra nella guarnigione di Dun Baldar.", "Ah, {name}, ti presenti per il servizio? Ottimo, ai Piccatonante serve chiunque riusciamo a radunare!\n\nParla con la prospettrice Molapietra a Dun Baldar. Sta reclutando per una missione vitale in territorio nemico. Troverai Molapietra nella parte più bassa della guarnigione di Dun Baldar.\n\nE tieni gli occhi aperti mentre attraversi Dun Baldar. C'è parecchio da fare per <un/una> {class} che lavora sodo e non ha paura di sporcarsi le mani.", nil, nil, 0x98c2799b, 0x0a68d03c, 0x33ca6bdc, nil, nil, "...mm", nil, nil, 0x88b33eac, nil, nil },
  [7222] = { "Parla con ⟦Voggah Deathgrip=Voggah Morsanera⟧", "Parla con Voggah nella ⟦Frostwolf Keep=Rocca dei Lupi Bianchi⟧.", "<Un/Una> {class}? Bene! Siamo lieti di vederti ad Alterac, {name}. Nani intrusi e i loro alleati invadono la nostra valle, e accogliamo chiunque nell'⟦Horde=Orda⟧ voglia unirsi a noi in un giusto massacro!\n\nParla con ⟦Voggah Deathgrip=Voggah Morsanera⟧. Cerca agenti per un'importante missione nella roccaforte dell'Alleanza nella ⟦Alterac Valley=Valle d'Alterac⟧!\n\nTroverai Voggah nella ⟦Frostwolf Keep=Rocca dei Lupi Bianchi⟧.", nil, nil, 0xc1f1cfcf, 0xb95ee89f, 0xed8789bc, nil, nil, "...mm" },
  [7223] = { "⟦Armor Scraps=Pezzi di Armature⟧", "Porta 20 ⟦Armor Scraps=Pezzi di Armature⟧ a ⟦Murgot Deepforge=Murgot Forgiafonda⟧, a Dun Baldar.", "Nella ⟦Alterac Valley=Valle d'Alterac⟧ si combatte senza sosta, e i rifornimenti che riceviamo da ⟦Ironforge=Forgiardente⟧ non bastano a equipaggiare le nostre truppe veterane.\n\nSe trovi pezzi di armature sul campo di battaglia, aiuta lo sforzo bellico e portali a me!", "Hai portato dei pezzi di armature, {name}?", "Sono dei bei pezzi, {name}. Posso usarli per forgiare nuovo equipaggiamento per le nostre truppe.\n\nSe le mie scorte saliranno abbastanza, forse le nostre unità veterane scenderanno in campo!", 0x69379f11, 0x1807f1cc, 0x38242264, 0x59127735, 0xc2035332, "....." },
  [7224] = { "Bottino nemico", "Porta 20 ⟦Armor Scraps=Pezzi di Armature⟧ al fabbro Regzar, nel ⟦Frostwolf Village=Villaggio dei Lupi Bianchi⟧.", "Quando combatti il nemico, raccogli i pezzi delle sue armature e portameli. Li userò per fare armature per le nostre truppe!", "Come va la caccia, {name}? Hai dei pezzi di armature per me?", "Questi andranno benissimo. Li fonderò, li rattopperò e nessuno saprà mai che vengono da quei codardi dei Piccatonante!\n\nGrazie, {name}. E lascia che ti lucidi un po' quell'armatura...", 0x665bfb65, 0x8eea36b9, 0xd25d0295, 0xee41626a, 0xea2bbb5f, "....." },
  [7241] = { "In difesa dei Lupi Bianchi", "Raggiungi la ⟦Alterac Valley=Valle d'Alterac⟧, sulle ⟦Alterac Mountains=Montagne d'Alterac⟧. Trova il maestro di guerra Laggrond, che si trova fuori dall'ingresso del tunnel, e parlagli per iniziare la tua carriera di soldato dei Lupi Bianchi. Troverai la ⟦Alterac Valley=Valle d'Alterac⟧ a nord del ⟦Tarren Mill=Mulino di Tarren⟧, ai piedi delle ⟦Alterac Mountains=Montagne d'Alterac⟧.", "I tamburi di guerra risuonano in una terra lontana, {class}. Il clan prediletto del tuo Capoguerra è sotto l'attacco della perfida ⟦Stormpike Guard=Guardia dei Piccatonante⟧ di ⟦Ironforge=Forgiardente⟧.\n\nA giudicare dal tuo aspetto, vedo che sei davvero temprat<o/a> dalla battaglia e pront<o/a> a sposare la causa dei Lupi Bianchi.\n\nOra tocca a te compiere il prossimo passo della tua evoluzione.\n\nA nord del ⟦Tarren Mill=Mulino di Tarren⟧, ad Alterac, troverai l'ingresso della ⟦Alterac Valley=Valle d'Alterac⟧. È lì che troverai il maestro di guerra Laggrond. Sbrigati, {class}, la battaglia è alle porte!", nil, "Per diventare un soldato dei Lupi Bianchi, bisogna prima essere messi alla prova...", 0xfae48c83, 0x66ddcb30, 0x720a3a61, nil, 0x668caba0, "...m." },
  [7261] = { "L'imperativo sovrano", "Raggiungi la ⟦Alterac Valley=Valle d'Alterac⟧, nelle ⟦Hillsbrad Foothills=Alture di Colletorto⟧. Fuori dal tunnel d'ingresso, trova il tenente Haggerdin e parlagli.\n\nPer la gloria di Bronzebeard!", "Stiamo combattendo una battaglia brutale nelle valli di Alterac. I troll cannibali Asciafredda ci attaccano da un lato e il selvaggio ⟦Frostwolf Clan=Clan Lupi Bianchi⟧ dall'altro. Entrambi vanno sterminati nel nome di re Magni Barbabronzea! Conquistare, sfoltire e convertire quella terra è un imperativo sovrano e territoriale per il regno di ⟦Ironforge=Forgiardente⟧.\n\nAhimè, i soldati non crescono sugli alberi! Presentati al tenente Haggerdin, fuori dalla ⟦Alterac Valley=Valle d'Alterac⟧, per iniziare il tuo servizio e guadagnarti onore tra i Piccatonante.", nil, "Mettiamoci al lavoro!", 0xb7b70a8b, 0x5fa8b95f, 0x252df73c, nil, 0x11d89b67, "...m." },
  [7281] = { "Amore fraterno", "Inoltrati nel territorio dei Piccatonante e uccidi ⟦Commander Karl Philips=Comandante Karl Philips⟧. Quando avrai finito, torna dal comandante Louis Philips.", "Che tragedia... Mio fratello mi affronta sul campo di battaglia: è un comandante dei Piccatonante.\n\nDei quattro comandanti dei Piccatonante, è senza dubbio il più pericoloso. Forse, se verrà ucciso, la Regina delle Banshee potrà convertirlo come ha fatto con me, e mostrargli i suoi errori...\n\nTroverai mio fratello nel cuore del territorio nemico. Uccidilo e torna da me. Confido che tu sia in grado di portare a termine questa missione, soldato.\n\nE, soldato, non andarci da sol<o/a>.", "Quanto deve soffrire a restare tra i vivi, mentre il suo amato fratello è asceso alla perfezione.", "Il tuo eroismo non passerà inosservato, {name}.\n\nNon devo perdere tempo, se voglio salvarlo. Bisogna avvisare Sylvanas!", 0xe7d8245f, 0x343b6536, 0x71625dbe, 0x9676ad25, 0x5d8df78e, "....." },
  [7282] = { "Amore fraterno", "Inoltrati nel territorio dei Lupi Bianchi e uccidi ⟦Commander Louis Philips=Comandante Louis Philips⟧. Quando avrai finito, torna dal comandante Karl Philips.", "Bisogna porre fine alle sue sofferenze, soldato! Non sa quello che fa. È diventato un servo senza mente della temibile Regina delle Banshee.\n\nAttraversa il ⟦Field of Strife=Pian della Discordia⟧ e spingiti nel cuore del territorio dei Lupi Bianchi. Trova mio fratello e distruggilo. Il suo tormento deve finire.", "È con il cuore pesante che do un ordine simile, soldato.", "Ti sei ricordat<o/a> di bruciare il cadavere, vero?", 0xe7d8245f, 0x64276aa1, 0xc6b30ac3, 0x476a1a98, 0xaae31659, "....." },
  [7301] = { "Signori del cielo caduti", "Raggiungi il territorio dei Lupi Bianchi e cerca il comandante di squadriglia Slidore, il comandante di squadriglia Vipore e il comandante di squadriglia Ichman. Se porterai a termine la missione, torna dal comandante Duffy.", "Li teniamo prigionieri, {race}. Parlo dei loro comandanti di stormo. È stata una battaglia furiosa nei cieli, ma alla fine sono caduti! Purtroppo i nostri migliori piloti sono stati abbattuti durante un contrattacco alla ⟦Frostwolf Keep=Rocca dei Lupi Bianchi⟧. Devi scoprire che fine hanno fatto.\n\nPerlustra Tower Point West e la ⟦Frostwolf Keep=Rocca dei Lupi Bianchi⟧. Sono gli ultimi posti in cui sono stati visti. Perlustra a fondo queste zone.", "Hai qualcosa che mi interessi sentire?", "Incredibile! Li hai liberati, vero? Vero??? Be', almeno sappiamo dove li tenevano.", 0x6d34555a, 0xf46c68a4, 0x9ce6f09e, 0x5aab64b2, 0xe9d4b48e, "....." },
  [7302] = { "Signori del cielo caduti", "Scopri che fine hanno fatto il comandante di squadriglia Guse, il comandante di squadriglia Jeztor e il comandante di squadriglia Mulverick. Se porterai a termine la missione, torna dal comandante Mulfort.", "Il nostro supporto aereo è allo sbando, {name}. I comandanti di stormo sono stati abbattuti sopra il territorio nemico. Devi scoprire che fine hanno fatto, così potremo tentare un salvataggio!\n\nGuse è stato visto l'ultima volta mentre sorvolava il ⟦Icewing Bunker=Fortilizio di Algidala⟧. Il ⟦Jeztor's War Rider=Cavalcaguerra di Jeztor⟧ è stato avvistato vicino alla segheria dei Piccatonante. Mulverick... quello sconsiderato è stato visto precipitare vicino al Dun'Baldar North Bunker.\n\nÈ tutto ciò che so. In marcia! Perlustra a fondo queste zone.", "A che punto è la caccia, soldato?", "Ben fatto! Le informazioni che hai recuperato saranno preziosissime per la nostra causa.", 0x6d34555a, 0x0c7e950b, 0xeadb4a89, 0xf4f7d78d, 0xaacc5616, "....." },
  [7321] = { "⟦Soothing Turtle Bisque=Zuppa Cremosa di Tartaruga⟧", "Porta 10 pezzi di ⟦Turtle Meat=Carne di Tartaruga⟧ e delle ⟦Soothing Spices=Spezie Esotiche⟧ a Christoph Jeffcoat, al ⟦Tarren Mill=Mulino di Tarren⟧.", "Chi dice che i non morti non sanno niente di cucina? Prendi per esempio la mia ricetta segreta della zuppa di tartaruga. Conosco gente che tornerebbe dal regno dei morti solo per gustarne una scodella! Eh, eh...\n\nA proposito, ultimamente non sono riuscito a prepararne. Andavo io stesso al Lago Lordamere a cacciare le snapjaw, quelle bestiacce, ma non riesco a staccarmi dal mio lavoro qui.\n\nSe mi porti un po' di ⟦Turtle Meat=Carne di Tartaruga⟧ dalle snapjaw e delle Spezie Esotiche, ti mostrerò come si fa!", "Hai trovato gli ingredienti? Te lo dico io, quei vermi dell'Alleanza sono fin troppi da queste parti ormai... Secondo me si sono già avvicinati troppo...", "La mia Zuppa Cremosa di Tartaruga ti scalderà in una notte fredda... se ti interessano queste cose.", 0xc8acfcb2, 0x5b979eb8, 0xb1398037, 0x0b383a67, 0x5b8e08bd, "....." },
  [7361] = { "Favore presso i ⟦Darkspear=Lanciascura⟧", "Ti è stato ordinato di uccidere i giocatori elfi della notte avversari nella ⟦Alterac Valley=Valle d'Alterac⟧.\n\nUccidi un elfo della notte e torna da ⟦Najak Hexxen=Najak Maleficus⟧, alla ⟦Frostwolf Keep=Rocca dei Lupi Bianchi⟧, con una ⟦Severed Night Elf Head=Testa Mozzata di Elfo della Notte⟧.", "<Najak ringhia.>\n\nPrima che esistessero gli elfi della notte c'erano i troll. È dai troll che sono venuti gli elfi della notte.\n\nI loro attacchi ribelli contro il mio popolo non saranno tollerati. Staghelm vuole spazzarci via, non lasciare traccia di chi ha generato lui e quelli come lui. Non accadrà!\n\nPer ogni elfo della notte che ucciderai e decapiterai, Najak ti concederà il favore dei ⟦Darkspear=Lanciascura⟧. La voce delle tue imprese si spargerà per Kalimdor e per i Regni Orientali. Va' ora, e servi i ⟦Darkspear=Lanciascura⟧!", "Vogliono sterminarci? Saranno loro a essere sterminati.", "{name}, è solo uno fra migliaia. Ma è comunque un lavoro ben fatto.", 0xbb842c90, 0x55dbcc07, 0x51444619, 0xc293408d, 0x749c39af, "....." },
  [7362] = { "Alleato dei tauren", "Ti è stato ordinato di uccidere i giocatori gnomi avversari nella ⟦Alterac Valley=Valle d'Alterac⟧.\n\nUccidi uno gnomo e torna da ⟦Ravak Grimtotem=Ravak Totem Truce⟧, alla ⟦Frostwolf Keep=Rocca dei Lupi Bianchi⟧, con un ⟦Tuft of Gnome Hair=Ciuffo di Capelli di Gnomo⟧.", "L'antica megera mi ha mandato in questa zona di guerra a studiare le altre razze. Più precisamente, devo raccogliere campioni di gnomo. A Magatha interessa soprattutto la loro capacità di sopravvivere. Già, gli gnomi, per quanto pietosamente deboli e minuscoli, mostrano una grande tenacia, in combattimento e fuori.\n\nPer tua fortuna, cerco gente rude che esegua gli ordini di Magatha. Torna da me con ciuffi di capelli di gnomo e i tauren ti conosceranno come loro alleat<o/a>.", "Non m'importa da dove vengano i capelli, {race}.", "Già, questo è proprio gnomo. Ben fatto, {race}, ma c'è altro lavoro da fare.", 0x65d13387, 0xddab1d4c, 0x42538f61, 0x4ba8f1be, 0x1e4f0d2b, "....." },
  [7363] = { "La condizione umana", "Ti è stato ordinato di uccidere i giocatori umani avversari nella ⟦Alterac Valley=Valle d'Alterac⟧.\n\nUccidi un umano e torna dal comandante Louis Philips (che si sposta tra il fronte e la Rocca dei Lupi Bianchi) con una ⟦Human Bone Chip=Scheggia d'Osso Umano⟧.\n\nLa cura per la condizione umana è a portata di mano!", "Gli umani sono così profondamente detestabili.\n\n<Il comandante Philips fa una smorfia.>\n\nÈ vero che sono un soldato dei Lupi Bianchi, ma resto un servitore di Sylvanas.\n\nDurante il mio servizio, faccio qualche lavoretto extra per gli speziali oscuri di ⟦Undercity=Sepulcra⟧.\n\nMi è stato affidato il compito di raccogliere schegge d'osso umano, da usare per curare la condizione umana.\n\nSono autorizzato a passare questo compito ai miei subordinati.\n\nTrovali. Uccidili. Portami le loro schegge d'osso.", "Sì, è vero. Mio fratello è un umano. Che vergogna... Una macchia sul mio stato di servizio quasi immacolato.", "Sarebbe più facile se accettassero la loro malattia e si arrendessero al tuo tocco guaritore. Ma probabilmente sarebbe anche meno divertente. Continua così! Li cureremo, in un modo o nell'altro.", 0xd69d3463, 0x7cca400f, 0xea160936, 0x27c2c300, 0x563eb6c3, "....." },
  [7364] = { "Taglia di Gnomeregan", "Ti è stato ordinato di uccidere i giocatori tauren avversari nella ⟦Alterac Valley=Valle d'Alterac⟧.\n\nUccidi un tauren e torna da ⟦Dirk Swindle=Dirk Truffetta⟧, a Dun'Baldar, con uno ⟦Tauren Hoof=Zoccolo di Tauren⟧.", "L'alto inventore in persona mi ha mandato su questo campo di battaglia a difendere i miei fratelli e le mie sorelle gnomi. Ci è giunta voce che i tauren prendono di mira e uccidono gli gnomi. E il peggio è che strappano ciuffi dei gloriosi capelli gnomeschi dai cadaveri dei caduti. Queste atrocità vanno fermate. Dobbiamo ricambiare!\n\nLi voglio senza zoccoli, {class}. Portami i loro zoccoli! Dimostrati alleat<o/a> degli gnomi.", "Falli zoppicare, {name}. Devono imparare che il popolo degli gnomi non si lascia mettere i piedi in testa!", "*Dirk getta lo zoccolo su un mucchio alle sue spalle.*", 0x10be540e, 0xa4846809, 0xfb9be150, 0xaa25b738, 0xa1a51d0a, "....." },
  [7365] = { "Il requiem di Staghelm", "Ti è stato ordinato di uccidere i giocatori troll avversari nella ⟦Alterac Valley=Valle d'Alterac⟧.\n\nUccidi un troll e torna da Athramanis, a Dun'Baldar, con un ⟦Darkspear Troll Mojo=Mojo di Troll Lanciascura⟧.", "Staghelm ha dato l'ordine. Tutti i troll sul campo di battaglia vanno sterminati. Le loro assurde pretese di aver generato gli elfi della notte vanno accolte con la forza e con il dovuto pregiudizio.\n\nUccidili e torna da me con il loro mojo. Lo ripeto: voglio che tu rubi il loro mojo.", "Sento ancora la puzza di quei troll fetidi.", "Grazie, {name}. L'aria è un po' più pulita.", 0x08cdaa41, 0xe58b9166, 0x2adc4321, 0x7dc3e477, 0x3fcbf2b4, "....." },
  [7366] = { "La misericordia dell'arcivescovo", "Ti è stato ordinato di uccidere i giocatori Reietti avversari nella ⟦Alterac Valley=Valle d'Alterac⟧.\n\nUccidi un Reietto e torna dal comandante Karl Philips (che si sposta tra la segheria e la miniera) con un ⟦Forsaken Heart=Cuore di Non Morto⟧.", "L'arcivescovo è tanto gentile quanto saggio. Che un uomo guardi con misericordia una simile marmaglia...\n\n<Il comandante Philips scuote la testa, incredulo.>\n\nTroppo gentile... davvero troppo gentile.\n\nL'arcivescovo ci chiede di avere pietà dei non morti e di concedere loro una morte rapida e definitiva. Per questa grande dimostrazione di misericordia, ci servono soltanto i loro cuori neri e marci di malattia.\n\nPortami i cuori dei Reietti, perché siano bruciati in una cerimonia nella ⟦Cathedral of Light=Cattedrale della Luce⟧. Sbrigati, {name}!", "Benedictus! Non sono che un granello nell'ombra della sua grandezza. Sia lodato!", "Sia lodato Benedictus! Un'altra anima perduta, presto salvata dalle fiamme incandescenti della Luce!\n\nVa', o soldato della Luce! Altri devono essere salvati!", 0xe121e255, 0x175b2ded, 0x9ca82885, 0xb55cdc18, 0x1852056e, "....." },
  [7367] = { "Disinnescare la minaccia", "Trova il ⟦Frostwolf Explosives Expert=Esperto di Esplosivi dei Lupi Bianchi⟧ e uccidilo. Quando avrai finito, torna dallo ⟦Stormpike Explosives Expert=Esperto di Esplosivi dei Piccatonante⟧.", "I Lupi Bianchi hanno disseminato di trappole il loro fronte e le loro basi, {class}. Devi stare attent<o/a> a dove metti i piedi quando invadi il territorio nemico.\n\nSe vuoi assestare loro un colpo deciso, devi distruggere la fonte delle loro munizioni antiuomo: parlo del loro esperto di esplosivi. Se lo uccidi, potrai disinnescare le mine in sicurezza. Finché lui resterà a terra, anche le mine resteranno a terra.\n\nProbabilmente lo troverai in una torre vicino al ⟦Iceblood Garrison=Presidio di Brinarossa⟧. Buona fortuna!", nil, nil, 0x76f2dd62, 0x23693407, 0xd11d881e, nil, nil, "...mm" },
  [7368] = { "Disinnescare la minaccia", "Trova lo ⟦Stormpike Explosives Expert=Esperto di Esplosivi dei Piccatonante⟧ e uccidilo. Quando avrai finito, torna dal ⟦Frostwolf Explosives Expert=Esperto di Esplosivi dei Lupi Bianchi⟧.", "So tutto sulle mine. Dopotutto, sono io a piazzare tutte le mine sul fronte, qui.\n\nSe vuoi disinnescare i campi minati dei Piccatonante, non devi far altro che uccidere il loro esperto di esplosivi. Quel nano codardo si nasconde di sicuro nella prima torre del ⟦Field of Strife=Pian della Discordia⟧. Fallo fuori e quelle mine, una volta disinnescate, non torneranno più.\n\nSe riesci a ucciderlo, torna qui e fammelo sapere. Nessuna buona azione deve restare senza ricompensa.", nil, nil, 0x76f2dd62, 0xdfc6b932, 0x418a5840, nil, nil, "...mm" },
  [7383] = { "La corona della terra", "Riempi la ⟦Amethyst Phial=Fiala di Ametista⟧ e riportala a ⟦Corithras Moonrage=Corithras Lunafuria⟧, a Dolanaar.", "Non tutto andava bene a Teldrassil, però. I piani accurati di Staghelm per il nuovo Albero del Mondo si erano realizzati come sperava, ma c'era un piccolo problema, un problema a cui si possono attribuire molti dei guai di Teldrassil.\n\nMa non ne parlerò ancora. Devi visitare l'ultimo pozzo lunare, a nord-ovest, nella Radura dell'Oracolo. Sotto i rami dell'Albero dell'Oracolo si trova il primo e il più potente dei nostri pozzi. Prendi una fiala della sua acqua e torna da me.", "Insieme ai druidi, l'Albero dell'Oracolo e l'arcidruido hanno sorvegliato con cura la crescita di Teldrassil. Ma anche se abbiamo una nuova casa, la nostra vita immortale non ci è stata restituita.", "Trovarsi al cospetto dell'Albero dell'Oracolo... è quasi come sentire la saggezza prendere forma. Lasciami continuare il racconto...\n\nQuando Teldrassil fu cresciuto, l'arcidruido si rivolse ai draghi per avere le loro benedizioni, come quelle che i draghi avevano concesso a Nordrassil in tempi antichi. Ma Nozdormu, Signore del Tempo, rifiutò di dare la sua benedizione, rimproverando il druido per la sua arroganza. D'accordo con Nozdormu, anche Alexstrasza rifiutò Staghelm, e senza la sua benedizione la crescita di Teldrassil è stata imperfetta e imprevedibile...", 0x6a9c354f, 0x00e3b1b6, 0xa9b364df, 0xb7686ed0, 0x195e31f7, "....." },
  [7401] = { "Ricercati: NANI!", "Ti è stato ordinato di uccidere i giocatori nani avversari nella ⟦Alterac Valley=Valle d'Alterac⟧.\n\nUccidi un nano e strappagli la colonna vertebrale. Porta la ⟦Dwarf Spine=Colonna Vertebrale di Nano⟧ al sergente Yazra Ringhiorosso, alla ⟦Frostwolf Keep=Rocca dei Lupi Bianchi⟧.", "Per ordine del sergente Yazra Ringhiorosso, tutti i nani sul campo di battaglia vanno uccisi a vista.\n\nSe uccidi un nano in combattimento, strappagli la colonna vertebrale e lascia un mucchio smidollato di puzza e marciume come monito per chiunque osi opporsi alla potenza dei Lupi Bianchi.\n\nTorna dal sergente Yazra Ringhiorosso con la prova del tuo eroismo.", "Io tratto ironia all'ingrosso, soldato.", "Ora hai licenza di decimare nani a dozzine, {class}!\n\n<Yazra fissa per un attimo un punto lontano.>\n\nLa prima spina dorsale strappata non si scorda mai...", 0x0c8299d4, 0xc0cbc4eb, 0x534ec6af, 0xf47a1bad, 0xf0ebc0d0, "....." },
  [7402] = { "Ricercati: ORCHI!", "Ti è stato ordinato di uccidere i giocatori orchi avversari nella ⟦Alterac Valley=Valle d'Alterac⟧.\n\nUccidi un orco e porta il suo ⟦Orc Tooth=Dente d'Orco⟧ al caporale Noreg Piccatonante, a Dun Baldar.", "Per ordine del caporale Noreg Stormpike, tutti i soldati abili dei Piccatonante sono tenuti a uccidere qualunque orco nemico incontrino sul campo di battaglia.\n\nI soldati sono tenuti a strappare una zanna o un dente dalle fauci del nemico e a presentare detto dente come prova della loro impresa.\n\nIndossare guanti protettivi.", "Ti serve una pinza per strappare i denti?", "Bene, {name}. Mi aspetto i topolini.", 0xb38692af, 0x57619e21, 0x9dce9870, 0xefeadcea, 0xa31eaed3, "....." },
  [7441] = { "Pusillin e l'anziano ⟦Azj'Tordin=Azj'tordin⟧", "Raggiungi ⟦Dire Maul=Maglio Infausto⟧ e trova l'imp Pusillin. Convinci Pusillin, con ogni mezzo necessario, a consegnarti il ⟦Book of Incantations=Libro degli Incantesimi⟧ di ⟦Azj'Tordin=Azj'tordin⟧.\n\nSe recuperi il ⟦Book of Incantations=Libro degli Incantesimi⟧, torna da ⟦Azj'Tordin=Azj'tordin⟧ al ⟦Lariss Pavilion=Padiglione di Lariss⟧, a Feralas.", "Ho abbassato la guardia per un solo istante, <straniero/straniera>. Nella fretta di sfuggire alla stretta del principe caduto, sono stato derubato. Un demone tra i più immondi, l'imp Pusillin, mi ha sottratto il libro degli incantesimi e la chiave delle sale un tempo grandiose di Eldre'Thalas.\n\nLa chiave non m'interessa più, perché ho scambiato la mia immortalità con la libertà, ma ho un disperato bisogno del mio libro degli incantesimi.\n\nTrova l'imp Pusillin e recupera il mio libro.\n\nCerca Pusillin nel Warpwood Quarter di ⟦Dire Maul=Maglio Infausto⟧.", "Non rimpiango nulla, <straniero/straniera>. La Regina è scomparsa da tempo. Le opere degli Shen'Dralar sono state guastate dalla follia del principe Tortheldrin. Cerco solo la libertà... la fuga...", "L'hai trovato! Sia maledetto quel miserabile imp. Ahimè, i miei beni materiali sono a dir poco scarsi. Puoi scegliere tra ciò che ho da offrire.", 0x059f80f6, 0xe43a7809, 0x19ed981b, 0x94b8d9e2, 0x5062574d, "....." },
  [7461] = { "La follia interiore", "Devi distruggere i guardiani che circondano i 5 pilastri che alimentano la Prison of Immol'thar. Una volta spenti i pilastri, il campo di forza che circonda Immol'thar si dissolverà.\n\nEntra nella Prison of Immol'thar ed elimina l'immondo demone che si trova al suo centro. Infine, affronta ⟦Prince Tortheldrin=Principe Tortheldrin⟧ nell'Athenaeum.\n\nSe porterai a termine questa missione, torna dallo ⟦Shen'dralar Ancient=Antica Shen'dralar⟧ nel cortile.", "Hai sentito abbastanza? Sei <un/una> <uomo/donna> d'azione?\n\nQuesta follia deve finire. L'epoca degli immortali è passata da tempo. Distruggi i guardiani che circondano i pilastri per abbassare il campo di forza. Fatto questo, distruggi Immol'thar. Con il potere del principe molto indebolito, attaccalo e mettigli fine. Dai pace agli spiriti di questa città, avventurier<o/a>.", "Stai in guardia, avventurier<o/a>. Il principe sa essere... persuasivo.", "Ti ringraziamo, <eroe/eroina>.", 0x3d8cb4ce, 0x6181dda9, 0x29a10d44, 0x4fc25a7c, 0x6a0ceb7f, ".....", nil, nil, 0xca71c4f1, nil, nil },
  [7462] = { "Il tesoro degli Shen'dralar", "Torna nell'Athenaeum e trova il tesoro degli Shen'dralar. Reclama la tua ricompensa!", "Nella biblioteca, l'Athenaeum, troverai un antico forziere nascosto sotto la scalinata. Prendi ciò che desideri.", nil, "Apri il forziere e trovi...", 0xe29bd883, 0x031a4aa1, 0x4ca8e2d2, nil, 0x549f5efb, "...m." },
  [7463] = { "Ristoro arcano", "Raggiungi il Warpwood Quarter di ⟦Dire Maul=Maglio Infausto⟧ e uccidi l'elementale dell'acqua ⟦Hydrospawn=Idrogenio⟧. Porta l'⟦Hydrospawn Essence=Essenza di Idrogenio⟧ allo storico Lydros, nell'Athenaeum.", "<Un/Una> mag<o/a> {race}! Che meraviglia. Non vedevo uno della tua specie da... oh, quanti sono ormai? 500 anni!\n\nHo qualcosa che placherà la tua sete, ma prima devi svolgere un compito per me.\n\n<Lydros ridacchia.>\n\nC'è un'anomalia a Eldre'Thalas. Un elementale dell'acqua si è stabilito nell'ala est. La sua presenza va catalogata!\n\nRaggiungi il Warpwood Quarter ed estrai una parte dell'essenza elementale dell'⟦Hydrospawn=Idrogenio⟧. Riportamela e ti insegnerò un utile incantesimo.", "Sì? Ci conosciamo?", "Magnifico! Chi eri, già? Oh, non ha importanza. Cosa dovevo darti? Mmh... be', sei <un/una> mag<o/a>, forse questo ti sarà utile.", 0x66eabbdb, 0x2fdbc927, 0x6ab187dc, 0xb6829be6, 0xc75847ce, "....." },
  [7481] = { "Leggende elfiche", "Cerca Telmius Dreamseeker a ⟦Dire Maul=Maglio Infausto⟧. Riferisci al saggio Korolusk, all'⟦Camp Mojache=Accampamento Mojache⟧, qualunque informazione tu riesca a trovare.", "Diversi anni fa, un maestro elfico solitario di nome Telmius Dreamseeker fuggì dalla devastazione della sua patria portando con sé diversi antichi manufatti elfici.\n\nLa ricerca di questo maestro perduto ci ha condotti dalle rovine di Quel'Thalas, attraverso le ⟦Burning Steppes=Steppe Ardenti⟧ e le grandi distese del mare, fino al Feralas.\n\nSospettiamo che l'elfo abbia cercato rifugio nelle sale di Eldre'Thalas (oggi nota come ⟦Dire Maul=Maglio Infausto⟧).\n\nDevi trovarlo, avventurier<o/a>. Vivo o morto, il sapere che portava con sé va recuperato!", "La mia collega, la studiosa elfa della notte Runethorn, sta radunando i suoi alleati per questo compito.", "Peccato... che tragedia. Gli oggetti sono andati perduti, dici? Nessuna traccia di lui, eh?", 0x1f2f44c8, 0x48fcc84f, 0x0c64d56a, 0xd17d6d54, 0x25e7e4f2, "....." },
  [7482] = { "Leggende elfiche", "Cerca Telmius Dreamseeker a ⟦Dire Maul=Maglio Infausto⟧. Riferisci alla studiosa Runaspina, a Feathermoon, qualunque informazione tu riesca a trovare.", "Diversi anni fa, un maestro elfico solitario di nome Telmius Dreamseeker fuggì dalla devastazione della sua patria portando con sé diversi antichi manufatti elfici.\n\nLa ricerca di questo maestro perduto ci ha condotti dalle rovine di Quel'Thalas, attraverso le ⟦Burning Steppes=Steppe Ardenti⟧ e le grandi distese del mare, fino al Feralas.\n\nSospettiamo che l'elfo abbia cercato rifugio nelle sale di Eldre'Thalas (oggi nota come ⟦Dire Maul=Maglio Infausto⟧).\n\nDevi trovarlo, avventurier<o/a>. Vivo o morto, il sapere che portava con sé va recuperato!", "Il mio collega, il saggio tauren Korolusk, sta radunando i suoi alleati per questo compito.", "Peccato... che tragedia. Gli oggetti sono andati perduti, dici? Nessuna traccia di lui, eh?", 0x1f2f44c8, 0xb62937c9, 0x0c64d56a, 0x4a5e2edd, 0x25e7e4f2, "....." },
  [7486] = { "La ricompensa di un eroe", "Reclama la tua ricompensa dall'Hydraxis' Coffer.", "{name}, i servigi che hai reso ai Signori della Guerra hanno superato tutto ciò che potevamo aspettarci dagli abitanti di questo mondo.\n\nNon comprendiamo le idee del tuo popolo sulla gratitudine o sulla ricompensa delle buone azioni, ma in questo caso... forse una ricompensa è giustificata.\n\nSotto la risacca, alla base meridionale di quest'isola, troverai un forziere. Al suo interno troverai la tua... ricompensa.\n\nVa', {name}. Prendi la tua ricompensa.", nil, "La voce di Idraxis scende dalla superficie delle acque...\n\n«Scegli ciò che più ti si addice, {name}. Possa proteggerti dai nemici dei Seguaci di Idraxis.»", 0x13f3267c, 0x6a5366b3, 0x9e6438a6, nil, 0x2dd65d0e, "...m." },
  [7487] = { "⟦Attunement to the Core=Sintonia con il Nucleo⟧", "Raggiungi il portale d'ingresso del ⟦Molten Core=Nucleo Ardente⟧ nei ⟦Blackrock Depths=Sotterranei di Roccianera⟧ e recupera un ⟦Core Fragment=Frammento di Nucleo⟧. Quando avrai recuperato il ⟦Core Fragment=Frammento di Nucleo⟧, torna da ⟦Lothos Riftwaker=Lothos Destavarco⟧, al ⟦Blackrock Mountain=Massiccio Roccianera⟧.", "Intorno a noi i varchi si agitano, si squarciano e crollano, {race}. A meno di due passi da dove mi trovo c'è uno squarcio che attraversa le profondità del ⟦Blackrock Mountain=Massiccio Roccianera⟧ e conduce nelle fauci del Signore del Fuoco.\n\nSorpres<o/a>? Peccato... Le razze mortali non sanno comprendere ciò che non possono vedere, toccare o sentire.\n\nTi assicuro che il portale è lì e che è possibile accedervi.\n\nHo stuzzicato il tuo interesse? La sintonia è semplice. Inoltrati nei ⟦Blackrock Depths=Sotterranei di Roccianera⟧ e recupera un frammento del nucleo. Riportamelo e sintonizzerò la tua essenza con il portale.", "Saltare attraverso l'apertura adesso potrebbe finire in un disastro... per te.", "Attraversa l'apertura alla mia destra e ti ritroverai dentro il ⟦Molten Core=Nucleo Ardente⟧.", 0x9b377bde, 0x3bb79f5f, 0x5c97dddf, 0xd4ff6138, 0x5ad762e4, "....." },
  [7488] = { nil, "Porta la Lethtendris' Web a ⟦Latronicus Moonspear=Latronicus Lanciargentea⟧, alla Roccaforte di Piumaluna, nel Feralas.", "La maga Lethtendris, una crudele elfa del sangue la cui brutalità è pari solo alla sua perversa dipendenza dalla magia, è fuggita a ⟦Dire Maul=Maglio Infausto⟧. Ha creato un congegno, una ragnatela per imprigionare le energie magiche di quel luogo, e temiamo che, se nessuno la ferma, causerà danni irreparabili al nostro mondo!\n\nFermala, {name}. Trovala e prendi la sua ragnatela. Probabilmente è vicino ai satiri, nel Warpwood Quarter di ⟦Dire Maul=Maglio Infausto⟧. Portami la ragnatela, così che il suo potere possa tornare senza pericolo alle terre selvagge...", "Hai la ragnatela, {name}? La sua energia magica concentrata va dispersa!", "Hai recuperato la ragnatela! Ben fatto, {name}! Lethtendris, come molti elfi della sua risma, non vede i pericoli che l'abuso della magia può causare al nostro mondo. Credono di essere padroni della magia; non si rendono conto di essere schiavi della loro dipendenza. La sua morte mi rattrista, ma era necessaria.\n\nGrazie, {name}. Farò liberare senza pericolo le energie della ragnatela su un'area vasta, poi la distruggerò per impedire altri abusi della magia.", 0x249af7d4, 0x49bd9dd5, 0x20db493a, 0x54c6c753, 0x3dde233f, "e...." },
  [7489] = { nil, "Porta Lethtendris's Web a ⟦Talo Thornhoof=Talo Zoccolo Spinoso⟧, all'⟦Camp Mojache=Accampamento Mojache⟧, nel Feralas.", "L'elfa del sangue Lethtendris ha passato il limite. Era così smaniosa di accumulare potere magico che ha sfidato i suoi simili e ha creato un congegno dal disegno insidioso, una ragnatela fatta per assorbire le energie magiche contaminate di ⟦Dire Maul=Maglio Infausto⟧. Anche ora raccoglie quelle energie e intende scatenarle contro i suoi nemici.\n\nLethtendris va fermata. Cercala nel Warpwood Quarter di ⟦Dire Maul=Maglio Infausto⟧, sconfiggila e portami la sua ragnatela, così che possa essere consegnata a elfi del sangue più assennati perché la studino.", "{name}, hai Lethtendris's Web?", "Hai fatto un buon lavoro, {name}. Questa ragnatela racchiude enormi riserve della magia di ⟦Dire Maul=Maglio Infausto⟧, e temo i danni che si potrebbero scatenare se quelle energie fossero sfruttate da qualcuno di irresponsabile come Lethtendris. La sua morte mi rattrista, ma so che da viva non si sarebbe mai separata dalla sua ragnatela.\n\nGrazie, {name}. Manderò la ragnatela a studiosi di magia più responsabili di Lethtendris. Saranno loro i nuovi custodi del suo potere.", 0x249af7d4, 0x62d2a3d4, 0x15303a66, 0xa9088e0e, 0xdb7d743a, "e...." },
  [7490] = { "Vittoria per l'⟦Horde=Orda⟧", "Porta la ⟦Head of Onyxia=Testa di Onyxia⟧ a Thrall, a Orgrimmar.", "Hai compiuto l'impossibile. La madre della stirpe dello Stormo dei Draghi Neri giace morta ai tuoi piedi. Prendi la sua testa e presentala al tuo Capoguerra.", "<L'espressione stoica di Thrall cambia per un istante quando vede l'enorme testa di Onyxia. Per poco il possente Doomhammer non è stato sguainato.>", "Questa è una grande vittoria per l'⟦Horde=Orda⟧, {name}. Tante volte hai onorato il tuo Capoguerra. È giunto il momento che il Capoguerra onori te.", 0x7d8d6308, 0xc65979a5, 0x33ae514c, 0x79883f70, 0x51211934, "....." },
  [7491] = { "Sotto gli occhi di tutti", "Cerca il signore supremo Runthak nella ⟦Valley of Strength=Valle della Forza⟧.", "Il signore supremo Runthak attende il tuo arrivo nella ⟦Valley of Strength=Valle della Forza⟧.\n\n<Thrall ti saluta.>\n\nNon far aspettare il tuo pubblico, <eroe/eroina>.", nil, "Scegli la tua ricompensa e che abbia inizio la celebrazione della tua gloriosa vittoria.", 0x0f8c7c56, 0x54df7e16, 0x46902d31, nil, 0x4d9c39da, "...m." },
  [7492] = { "⟦Camp Mojache=Accampamento Mojache⟧", "Parla con ⟦Talo Thornhoof=Talo Zoccolo Spinoso⟧ all'⟦Camp Mojache=Accampamento Mojache⟧, nel Feralas.", "⟦Talo Thornhoof=Talo Zoccolo Spinoso⟧, un anziano tauren del Feralas, chiede aiuto. Ha dato pochi dettagli, ma ha detto di aver bisogno di agenti per una faccenda delicata... e grave.\n\nServi l'⟦Horde=Orda⟧, {name}. Va' all'⟦Camp Mojache=Accampamento Mojache⟧, nel Feralas, e parla con Talo.", nil, "Ah, è bello vedere <un/una> {class} rispondere alla mia chiamata. Ho bisogno dei tuoi servigi, {name}, e temo che ti porteranno lungo un sentiero pericoloso...\n\nUn sentiero che conduce a ⟦Dire Maul=Maglio Infausto⟧.", 0xa6ffc12b, 0x7b82476a, 0xc13a5b92, nil, 0x79feceef, "...m." },
  [7493] = { "Il viaggio è appena cominciato", nil, nil, nil, "Uccidi draghi e sei anche espert<o/a> nella conciatura? Non smetti di stupirmi, <eroe/eroina>. Mi inchino davanti a te.\n\nAccetta ciò che sto per insegnarti. Questa conoscenza si rivelerà preziosissima, se vuoi distruggere ciò che resta dello Stormo dei Draghi Neri.\n\nRealizza il mantello con le scaglie della madre della stirpe. Proteggerà te e i tuoi alleati dal soffio incendiario del Signore di ⟦Blackrock=Roccianera⟧... Nefarian.", 0xccab3732, nil, nil, nil, 0x76f38e96, ".mmm." },
  [7494] = { nil, "Parla con ⟦Latronicus Moonspear=Latronicus Lanciargentea⟧ alla Roccaforte di Piumaluna, nel Feralas.", "{name}! C'è bisogno del tuo aiuto nel Feralas!\n\nUna maga fuorilegge, Lethtendris, è fuggita nelle antiche rovine elfiche di Eldre'thalas, oggi chiamate ⟦Dire Maul=Maglio Infausto⟧. Si crede che abbia un oggetto carico di pericolosa energia magica, che va recuperato.\n\nLatronicus Moonspear cerca agenti che entrino a ⟦Dire Maul=Maglio Infausto⟧ e sottraggano l'oggetto a Lethtendris.\n\nServi l'⟦Alliance=Alleanza⟧! Cerca Latronicus alla Roccaforte di Piumaluna, nel Feralas.", nil, "Salute, {name}. Sono lieto di vederti, ma mi rammarico che il nostro incontro non avvenga in circostanze più piacevoli.\n\nAscolta bene, perché ho un compito vitale per te...", 0xfdb07f41, 0xe796dea4, 0x353288ef, nil, 0xfe011fb0, "e..m." },
  [7495] = { "Vittoria per l'⟦Alliance=Alleanza⟧", "Porta la ⟦Head of Onyxia=Testa di Onyxia⟧ al gran signore Bolvar Domadraghi, a ⟦Stormwind=Roccavento⟧.", "Hai compiuto l'impossibile. La madre della stirpe dello Stormo dei Draghi Neri giace morta ai tuoi piedi. Prendi la sua testa e presentala al gran signore.", "Per la barba di Uther!", "Per tanti anni sono rimasto prigioniero del suo sguardo ammaliatore. Finalmente vedo fatta giustizia e restituito l'onore di ⟦Stormwind=Roccavento⟧! Oggi celebriamo questa gloriosa vittoria!", 0xc2d46496, 0x505dad80, 0x560a0c47, 0x770e5d67, 0xe5878ffa, "....." },
  [7496] = { "Tempo di festeggiare", "Cerca il maggiore Mattingly nella ⟦Valley of Heroes=Valle degli Eroi⟧.", "Cerca il maggiore Mattingly nella ⟦Valley of Heroes=Valle degli Eroi⟧, {name}. Ti starà aspettando...", nil, "Pochi hanno l'onore di una simile cerimonia, {name}. Ti prego, scegli la tua ricompensa, così che possiamo dare inizio alla celebrazione.", 0x3703d072, 0xdc35ec0b, 0x4f451a8c, nil, 0x5d991116, "...m." },
  [7497] = { "Il viaggio è appena cominciato", nil, nil, nil, "Uccidi draghi e sei anche espert<o/a> nella conciatura? Non smetti di stupirmi, <eroe/eroina>. Mi inchino davanti a te.\n\nAccetta ciò che sto per insegnarti. Questa conoscenza si rivelerà preziosissima, se vuoi distruggere ciò che resta dello Stormo dei Draghi Neri.\n\nRealizza il mantello con le scaglie della madre della stirpe. Proteggerà te e i tuoi alleati dal soffio incendiario del Signore di ⟦Blackrock=Roccianera⟧... Nefarian.", 0xccab3732, nil, nil, nil, 0x76f38e96, ".mmm." },
  [7498] = { "⟦Garona: A Study on Stealth and Treachery=Garona: Studio sulla Furtività e sul Tradimento⟧", "Restituisci il libro ai legittimi proprietari.", "Il tomo porta il marchio dell'Athenaeum.", "Hai recuperato un tomo!", "Ottimo lavoro, {race}. Se trovi altri tomi, non esitare a riportarceli.\n\nCol passare del tempo, cambiamo spesso le ricompense per la restituzione dei tomi perduti e ne aggiungiamo di nuove.", 0x56d361ae, 0xdeb95520, 0x10e08c8e, 0xd98d4887, 0x8b9e3b1a, "....." },
  [7499] = { "⟦Codex of Defense=Codice della Difesa⟧", "Restituisci il libro ai legittimi proprietari.", "Il tomo porta il marchio dell'Athenaeum.", "Hai recuperato un tomo!", "Ottimo lavoro, {race}. Se trovi altri tomi, non esitare a riportarceli.\n\nCol passare del tempo, cambiamo spesso le ricompense per la restituzione dei tomi perduti e ne aggiungiamo di nuove.", 0x1bbcdca9, 0xdeb95520, 0x10e08c8e, 0xd98d4887, 0x8b9e3b1a, "....." },
  [7500] = { "⟦The Arcanist's Cookbook=Libro di Ricette dell'Arcanista⟧", "Restituisci il libro ai legittimi proprietari.", "Il tomo porta il marchio dell'Athenaeum.", "Hai recuperato un tomo!", "Ottimo lavoro, {race}. Se trovi altri tomi, non esitare a riportarceli.\n\nCol passare del tempo, cambiamo spesso le ricompense per la restituzione dei tomi perduti e ne aggiungiamo di nuove.", 0xa3796ce9, 0xdeb95520, 0x10e08c8e, 0xd98d4887, 0x8b9e3b1a, "....." },
  [7501] = { "La Luce e come brandirla", "Restituisci il libro ai legittimi proprietari.", "Il tomo porta il marchio dell'Athenaeum.", "Hai recuperato un tomo!", "Ottimo lavoro, {race}. Se trovi altri tomi, non esitare a riportarceli.\n\nCol passare del tempo, cambiamo spesso le ricompense per la restituzione dei tomi perduti e ne aggiungiamo di nuove.", 0x62c494c9, 0xdeb95520, 0x10e08c8e, 0xd98d4887, 0x8b9e3b1a, "....." },
