  [7503] = { "⟦The Greatest Race of Hunters=Grande Stirpe dei Cacciatori⟧", "Restituisci il libro ai legittimi proprietari.", "Il tomo porta il marchio dell'Athenaeum.", "Hai recuperato un tomo!", "Ottimo lavoro, {race}. Se trovi altri tomi, non esitare a riportarceli.\n\nCol passare del tempo, cambiamo spesso le ricompense per la restituzione dei tomi perduti e ne aggiungiamo di nuove.", 0x548d96c8, 0xdeb95520, 0x10e08c8e, 0xd98d4887, 0x8b9e3b1a, "....." },
  [7504] = { "⟦Holy Bologna: What the Light Won't Tell You=Sacra Lasagna: Cosa la Luce Non Vuole Farvi Sapere⟧", "Restituisci il libro ai legittimi proprietari.", "Il tomo porta il marchio dell'Athenaeum.", "Hai recuperato un tomo!", "Ottimo lavoro, {race}. Se trovi altri tomi, non esitare a riportarceli.\n\nCol passare del tempo, cambiamo spesso le ricompense per la restituzione dei tomi perduti e ne aggiungiamo di nuove.", 0xb0e98e7d, 0xdeb95520, 0x10e08c8e, 0xd98d4887, 0x8b9e3b1a, "....." },
  [7505] = { "⟦Frost Shock and You=Folgore del Gelo per Negati⟧", "Restituisci il libro ai legittimi proprietari.", "Il tomo porta il marchio dell'Athenaeum.", "Hai recuperato un tomo!", "Ottimo lavoro, {race}. Se trovi altri tomi, non esitare a riportarceli.\n\nCol passare del tempo, cambiamo spesso le ricompense per la restituzione dei tomi perduti e ne aggiungiamo di nuove.", 0x195c2263, 0xdeb95520, 0x10e08c8e, 0xd98d4887, 0x8b9e3b1a, "....." },
  [7506] = { "⟦The Emerald Dream=Sogno di Smeraldo⟧...", "Restituisci il libro ai legittimi proprietari.", "Il tomo porta il marchio dell'Athenaeum.", "Hai recuperato un tomo!", "Ottimo lavoro, {race}. Se trovi altri tomi, non esitare a riportarceli.\n\nCol passare del tempo, cambiamo spesso le ricompense per la restituzione dei tomi perduti e ne aggiungiamo di nuove.", 0xb075a617, 0xdeb95520, 0x10e08c8e, 0xd98d4887, 0x8b9e3b1a, "....." },
  [7507] = { "Il compendio di Nostro", "Riporta il ⟦Nostro's Compendium of Dragon Slaying=Compendio di Nostro sull'Uccisione dei Draghi⟧ all'Athenaeum.", "Hai scoperto qualcosa di grande importanza. Questo libro non somiglia a nessuno di quelli che hai visto finora.\n\nSembra che qualcuno, o qualcosa, sia riuscito a spezzare il sigillo dell'Athenaeum. Il testo all'interno è confuso e quasi illeggibile.", "Ah, una delle nostre raccolte più preziose. Questa manca da secoli.", "Avresti potuto ricavare parecchio oro da questo libro al mercato nero, {name}. Soprattutto perché il sigillo protettivo è stato spezzato, rendendo i segreti dell'uccisione dei draghi accessibili a chiunque abbia l'intelletto necessario per assimilare il sapere contenuto in queste pagine sacre.\n\nForse è il caso di una grande ricompensa... Be', una ricompensa che richiederà un enorme sforzo per essere ottenuta.\n\n<Lydros sogghigna.>", 0xd019ffa4, 0x30367b5a, 0x9a80f073, 0x9b3492ba, 0x2374beb3, "....." },
  [7508] = { "La forgiatura di Quel'Serrar", "Consegna la Lama Elfica Piatta e Spuntata allo storico Lydros.", "Se vuoi assumerti questo compito, presenta a Lydros la lama spuntata.", "Eccellente, cominciamo...", "Se riuscirai a entrare nell'antro del drago, a scaldare la lama sotto il suo soffio infuocato e infine a temprarla nel suo sangue, legherò la lama perché tu possa usarla.", 0x700c7e24, 0xd02c38a3, 0xd42b2fc9, 0xd2ab567a, 0x0d6cb539, "....." },
  [7509] = { "La forgiatura di Quel'Serrar", "Devi fare in modo che Onyxia sputi fuoco sull'⟦Unfired Ancient Blade=Antica Lama Cruda⟧. Fatto questo, raccogli la lama, ormai diventata una ⟦Heated Ancient Blade=Lama Temprata Antica⟧. Attenzione: la ⟦Heated Ancient Blade=Lama Temprata Antica⟧ non resterà calda per sempre, il tempo stringe.\n\nL'ultimo passo, prima di tornare da me, è uccidere la bestia e conficcare la ⟦Heated Ancient Blade=Lama Temprata Antica⟧ nel suo cadavere.\n\nFallo e Quel'Serrar sarà tua.", "Porta l'antica lama cruda nell'antro di Onyxia e affrontala in battaglia.\n\nPer scaldare la lama serve un po' di astuzia. Durante il combattimento, cercherà di certo di incenerirti con il suo soffio infuocato. Devi piantare l'antica lama cruda lì vicino e sperare che il soffio infuocato la scaldi. Se sopravvivi, raccogli la lama, ormai temprata, e finisci il drago.\n\nConficca l'antica lama temprata nel suo cadavere fumante per ottenere la lama trattata antica.", "Forse un giorno un altro brandirà la lama prismatica.", "<Lydros mormora qualcosa di incomprensibile.>\n\nCome promesso, {class}, la lama di Quel'Serrar.", 0x700c7e24, 0x4b267fc9, 0xb2e66075, 0x90d8fc2b, 0x41ddcb19, "....." },
  [7521] = { "Thunderaan il Ventoeterno", "Per liberare Thunderaan il Ventoeterno dalla sua prigione, devi presentare al gran signore Demitrian le metà destra e sinistra delle Manette del Ventoeterno, 10 lingotti di elementio e l'⟦Essence of the Firelord=Essenza del Signore del Fuoco⟧.", "Ti ho detto tutto ciò che so, {name}. Sei tu che devi trovare l'elementio. Sei tu che devi distruggere la forma corporea del Signore del Fuoco.\n\nFallo e otterrai la benedizione di Thunderaan.", "Metti in ginocchio il mondo, se devi!", "Neppure nei sogni osavo prevedere questo giorno.\n\nAmmira, mortale.\n\nAMMIRA COLUI CHE È PIÙ ANTICO DELL'ESISTENZA!\n\nAMMIRA COLUI CHE HA AFFRONTATO TITANI E DÈI!\n\nRISORGI, MIO PADRONE! SPEZZA LE TUE CATENE!", 0x30d08f81, 0x4425cb6b, 0xaaceb8e0, 0xb1d1afb9, 0x6900d53f, "....." },
  [7541] = { "Al servizio dell'⟦Horde=Orda⟧", nil, nil, nil, "Ci vorrà tempo perché i nostri studiosi esaminino il pendente che ci hai portato. Ma per il tuo servizio all'⟦Horde=Orda⟧ vorrei offrirti un piccolo pegno.\n\nGrazie, {name}. Le tue azioni portano onore a te e a noi.", 0x585442a8, nil, nil, nil, 0x4652c53f, ".mmm." },
  [7562] = { nil, "Parla con ⟦Mor'zul Bloodbringer=Mor'zul Nerosangue⟧ nelle ⟦Burning Steppes=Steppe Ardenti⟧.", "{name}, ti sei spint<o/a> a fondo nelle arti oscure. Il tuo dominio sulle creature di altri mondi è diventato così forte... che forse sei <pronto/pronta> a legare a te uno dei famigerati maldestrieri.\n\nIl rituale per evocare la bestia dalla sua dimora richiede grande potere e molte risorse, ma se desideri dominare quella cavalcatura epica, parla con ⟦Mor'zul Bloodbringer=Mor'zul Nerosangue⟧. È accampato vicino all'⟦Altar of Storms=Altare delle Tempeste⟧, nelle ⟦Burning Steppes=Steppe Ardenti⟧.\n\nVa', {name}. Questa missione sarà pericolosa, ma <uno/una> <Stregone/Strega> della tua levatura non si tira indietro davanti al pericolo!", nil, "Salute, {name}, e benvenut<o/a>. Sei qui per studiare vicino all'⟦Altar of Storms=Altare delle Tempeste⟧ come me, forse per sfruttarne l'energia per qualche scopo nascosto...\n\nOppure... sei qui per parlare con me? Sì, credo proprio di sì.\n\nVuoi dominare un maldestriero? Non è un'impresa facile. Ti costerà non poco sangue, sudore... e naturalmente oro. Ma un maldestriero di Xoroth è un premio che vale la pena conquistare, quindi, se ti interessa, continua ad ascoltare...", 0x70b8af5f, 0xf3dc644e, 0xffd05978, nil, 0xd348df70, "e..m." },
  [7563] = { "Furia di sangue", "Porta 30 bottiglie di ⟦Raging Beast's Blood=Sangue di Bestia Furente⟧ a ⟦Mor'zul Bloodbringer=Mor'zul Nerosangue⟧ nelle ⟦Burning Steppes=Steppe Ardenti⟧.", "I maldestrieri vivono in un altro mondo, sulle infuocate Plains of Xoroth, e per legare a te una di quelle celebri bestie devi invocare glifi potenti. Posso tracciarti i glifi su una pergamena, ma prima mi servirà un inchiostro speciale.\n\nNella lontana ⟦Winterspring=Fontefredda⟧ vive una razza di silvagufi. Un tempo erano creature pure, ma le emanazioni demoniache della ⟦Darkwhisper Gorge=Gola di Mormoscuro⟧ li hanno fatti impazzire e ora vagano per le nevi in preda alla frenesia.\n\nÈ il loro sangue che mi serve per l'inchiostro della tua pergamena. Portamelo.", "Hai visto i silvagufi infuriati, {name}? La magia di quelle creature è potente, e si concentra nel sangue che scorre nei loro corpi tormentati.", "Ah, molto bene. Farò distillare questo sangue in un inchiostro e lo userò per la pergamena che ti ho promesso. E forse ne terrò un pochino per me, visto che ho sentito dire che il suo sapore è davvero euforizzante...", 0x7adddd9f, 0x37c14049, 0x922b3e68, 0x41ff93b4, 0xa1bf07d8, "....." },
  [7564] = { nil, "Porta la ⟦Case of Blood=Cassa di Sangue⟧ a ⟦Gorzeeki Wildeyes=Gorzeeki Malalente⟧ nelle ⟦Burning Steppes=Steppe Ardenti⟧.", "Il mio servitore, Gorzeeki, è un alchimista di una certa abilità. Può preparare l'inchiostro che mi servirà per la tua pergamena. Ho raccolto il sangue che hai procurato; portalo a Gorzeeki perché possa mettersi al lavoro.", "Hai qualcosa per me? Non è un ragno grosso e succoso, vero? O magari uno scarafaggio? Spero che sia ancora vivo... Adoro masticarli quando sono ancora vivi...", "Oh, è sangue. Allora dev'essere del padrone Mor'zul. Ne va matto, e adora vederlo versare. Io invece preferisco che scorra nelle vene di un piccolo roditore. Così resta caldo... finché non lo vuoi.\n\nQuesto è sangue potente. Mor'zul deve preparare un'altra pergamena per evocare un maldestriero! Che emozione!\n\nSe è così, e sei tu a eseguire il rituale, allora... ti servirà molto più del sangue, <amico/amica> mi<o/a>.", 0xb9b269a3, 0x5a9443c3, 0xe186564e, 0x431c1ea4, 0x17f66757, "e...." },
  [7581] = { "Il legante della prigione", "Recati a ⟦Dire Maul=Maglio Infausto⟧, nel Feralas, e recupera 15 ⟦Satyr Blood=Sangue di Satiro⟧ dai ⟦Wildspawn Satyr=Satiro Proleselva⟧ che abitano il Warpwood Quarter. Poi torna da Daio, nella Landa Corrotta.", "Devi recuperare dai demoni minori un legante per la prigione del demone guardiano.\n\nIl sangue dei satiri Wildspawn che occupano ⟦Dire Maul=Maglio Infausto⟧ dovrebbe andare benissimo. Il sangue coagulato legherà i frammenti di Hederine e alimenterà la prigione di cristallo.", "Basterà solo il sangue dei satiri Wildspawn.", "Ah, un recupero eccellente. Il sangue sopprimerà le difese magiche del demone guardiano.", 0x0da2867e, 0xf791ccbd, 0x4a0a73cf, 0x88fa6d3b, 0x2845db33, "....." },
  [7582] = { "L'involucro della prigione", "Recati nella ⟦Darkwhisper Gorge=Gola di Mormoscuro⟧, a ⟦Winterspring=Fontefredda⟧, e recupera 5 ⟦Tears of the Hederine=Lacrime di Hederine⟧ dai demoni Hederine che occupano la gola. Torna da Daio, nella Landa Corrotta, quando avrai finito.", "I demoni Hederine che occupano le pendici del ⟦Mount Hyjal=Monte Hyjal⟧ secernono potenti veleni demoniaci che, se lasciati maturare, si induriscono in un denso cristallo antimagia. Questi cristalli sono ormai noti come ⟦Tears of the Hederine=Lacrime di Hederine⟧.\n\nNemmeno l'immenso potere di un demone guardiano riuscirebbe a infrangere le pareti di una prigione costruita con questo materiale.\n\nRecati nella ⟦Darkwhisper Gorge=Gola di Mormoscuro⟧, a ⟦Winterspring=Fontefredda⟧, e recupera le Lacrime.", "Gli Hederine non cederanno le loro preziose gemme senza combattere, {name}.", "Devo solo unire il sangue dei Wildspawn a questi cristalli e la prigione sarà pronta all'uso.", 0xc7e97794, 0x57e4bc82, 0xc64e1f45, 0xc76bfc02, 0xa09498ea, "....." },
  [7583] = { "Soggiogamento", "Addentrati nella Landa Corrotta e trova un ⟦Doomguard Commander=Demone Guardiano Comandante⟧.\n\nUsa la ⟦Glowing Crystal Prison=Prigione di Cristallo Luminoso⟧ sul ⟦Doomguard Commander=Demone Guardiano Comandante⟧. Preparati a un feroce assalto, perché il demone cercherà di sfuggire alla cattura.\n\nSe ci riesci, porta il ⟦Imprisoned Doomguard=Demone Guardiano Imprigionato⟧ a Daio, nella Landa Corrotta.", "La prigione è pronta. Ora viene la parte più difficile del compito.\n\nDevi trovare e catturare un ⟦Doomguard Commander=Demone Guardiano Comandante⟧ nella Landa Corrotta usando questa prigione di cristallo.\n\nAttenzione! Il demone guardiano è un avversario astuto e letale, e cercherà di distruggerti appena inizierai il rituale d'imprigionamento. Si dibatterà furiosamente nel tentativo di sfuggire alla prigione.\n\nNon si concentrerà su nient'altro che te, {name}. Per questo ti consiglio di portare con te compagni capaci di tenerti in vita!", "Mmh? Allora?", "Hai fatto ciò che ti ho chiesto. Sei <pronto/pronta> a ricevere la conoscenza per evocare e controllare la bestia.", 0x46ccd505, 0xfc958e98, 0x8267dd8d, 0xefa60722, 0x3fa4c997, "....." },
  [7601] = { "Gli ordini di Niby", "Parla con Impsy, a ⟦Felwood=Vilbosco⟧.", "Se devo insegnarti i segreti dell'evocazione di un servitore infernale, devi distruggere Kroshius e portarmi il nucleo infernale dai suoi resti in fiamme. Questo, però, non è facile come sembra. Kroshius si è quasi del tutto consumato. Devi riaccendere il suo cadavere e risollevarlo dalle macerie. Per farlo, però, dovrai raccogliere alcuni componenti da altre entità demoniache.\n\nIl mio imp, Impsy, ti metterà sulla buona strada.", nil, "Oh, cielo, ci risiamo.", 0xfdb31e0d, 0x0c9d6772, 0x56c5c901, nil, 0x34ba2cb4, "...m." },
  [7602] = { "Vilessenza Pura", "Impsy, a ⟦Felwood=Vilbosco⟧, ti ha chiesto di portargli tre Vilessenze Pure provenienti da tre luoghi diversi.\n\nI Legashi Satyr di Azshara custodiscono la Vilessenza Pura della loro regione. I Jaedenar Legionnaire di Jaedenar custodiscono la Vilessenza Pura della loro regione. Le Felguard Sentry delle ⟦Blasted Lands=Terre Devastate⟧ custodiscono la Vilessenza Pura della loro regione.\n\nRecupera le Vilessenze Pure e torna da Impsy a ⟦Felwood=Vilbosco⟧.", "Se vuoi rianimare Kroshius, ti servirà del Vilfuoco. Io so fare il Vilfuoco, ma mi servono alcuni componenti.\n\nDevi portarmi delle vilessenze pure da tre diverse regioni del mondo.\n\nI satiri Legashi di Azshara avranno il primo tipo di essenza, i legionari di Jaedenar il secondo e le sentinelle vilguardia delle ⟦Blasted Lands=Terre Devastate⟧ il terzo.\n\nPortami un'essenza di ciascun tipo e creerò il Vilfuoco, che ti permetterà di rianimare Kroshius.", "Non dirlo a nessuno, ma Niby è suonato.", "Dammi un minuto e unirò le essenze per creare il Vilfuoco.", 0x624eeeec, 0xbe474b63, 0x2e3d35df, 0x48088787, 0x56418681, "....." },
  [7603] = { "⟦Kroshius' Infernal Core=Nucleo Infernale di Kroshius⟧", "Cerca i resti di Kroshius nella ⟦Shatter Scar Vale=Valle dei Crateri Infernali⟧, a ⟦Felwood=Vilbosco⟧. Quando li avrai trovati, usa il ⟦Fel Fire=Vilfuoco⟧ vicino ai resti e attendi il ritorno di Kroshius. Quando l'infernale si sarà risvegliato, uccidilo e prendi dal suo cadavere il ⟦Kroshius' Infernal Core=Nucleo Infernale di Kroshius⟧.\n\nRiporta il ⟦Kroshius' Infernal Core=Nucleo Infernale di Kroshius⟧ a ⟦Niby the Almighty=Niby il Poderoso⟧, a ⟦Felwood=Vilbosco⟧.", "Kroshius giace in un mucchio a nord-est, nella ⟦Shatter Scar Vale=Valle dei Crateri Infernali⟧. Prendi questo Vilfuoco e usalo sui suoi resti. Il fuoco dovrebbe rianimare l'infernale caduto.\n\nA quel punto mi aspetto proprio che uccida te e tutti gli amici che avrai con te... e credimi, vorrai avere qualche amico con te.\n\nSe per miracolo riuscirai a uccidere Kroshius, prendi il suo nucleo infernale e riportalo a Niby.", "Ti sei <perso/persa>?", "Un patto è un patto! Presto, prendi questo e scrivilo. Non ho tempo! La mia più grande evocazione è imminente!", 0x9fcd3fbe, 0x5b568bf2, 0x429fc5de, 0x3f3b06cd, 0x61c43582, "....." },
  [7604] = { "Un contratto vincolante", "Consegna il ⟦Thorium Brotherhood Contract=Contratto con la Fratellanza del Torio⟧ a ⟦Lokhtos Darkbargainer=Lokhtos Pattoscuro⟧ se vuoi ricevere il progetto di Sulfuron.", "Il sottoscritto dichiara con la presente che il lingotto di Sulfuron consegnato alla ⟦Thorium Brotherhood=Fratellanza del Torio⟧ (TB Ltd.) è autentico e non una sua imitazione. Il sottoscritto riconosce inoltre che qualsiasi danno <gli/le> derivi dal tentativo di costruire, forgiare, trovare, creare, vendere o mangiare Sulfuras non è responsabilità né colpa di TB Ltd.\n\nFirmando questo contratto, accetti tutti i termini qui elencati.\n\n_________________\n\nFirma", "Abbiamo un accordo?", "È stato un piacere fare affari con te, {name}!\n\nA nome di TB Ltd., ti auguro buona fortuna nella tua ricerca di Sulfuras!", 0xb3e013a8, 0xb4f357b1, 0x9f3945b5, 0xf707cff6, 0xa3184ea3, ".....", nil, nil, 0xc22a16e9, nil, nil },
  [7621] = { "Un avvertimento", nil, nil, nil, "<Sacerdote/Sacerdotessa>, stai per affrontare una dura serie di prove che metteranno alla prova tutte le tue abilità.\n\nTi suggerisco di ascoltare la storia che ho da raccontare.\n\nAttenzione: devi completare questo compito da <solo/sola>. È consigliabile che i tuoi alleati restino a distanza. L'intervento di agenti esterni comporterà una punizione severissima.\n\nIl destino ha condotto qui te, e te soltanto. Combatti con onore. Imbriglia la Luce.", 0x68902ac5, nil, nil, nil, 0x08834217, ".mmm.", nil, nil, nil, nil, 0x742079ec },
  [7622] = { "⟦Balance of Light and Shadow=Equilibrio di Luce e Ombra⟧", "Salva 50 popolani prima che ne vengano uccisi 15. Se ci riesci, parla con ⟦Eris Havenfire=Eris Sacrofuoco⟧.\n\nPuoi consultare il Death Post per vedere quanti popolani sono stati uccisi.", "Devi fare ciò che io non sono riuscita a fare: salvare i popolani che furono abbattuti mentre fuggivano da Stratholme.\n\nCammineranno verso la luce, e tu devi garantire la loro sopravvivenza. Se ne cadranno troppi, la nostra esistenza maledetta continuerà, e tu avrai fallito.\n\nOgni abilità, preghiera e incantesimo che hai imparato sarà messo alla prova. Che la Luce ti protegga, {name}.", nil, "La tua tenacia e il tuo coraggio sono sbalorditivi, <sacerdote/sacerdotessa>. Ti sei <guadagnato/guadagnata> il diritto di possedere la ⟦Splinter of Nordrassil=Scheggia di Nordrassil⟧. Resta un solo compito: bisogna recuperare l'⟦The Eye of Shadow=Occhio dell'Ombra⟧. Setaccia il mondo.", 0xf2986d90, 0x3be6a8e8, 0x5abd49cb, nil, 0x5e59767f, "...m.", nil, nil, nil, nil, 0x9fefa0b4 },
  [7623] = { nil, "Compra delle Pozioni dell'Ombra da Gorzeeki nelle ⟦Burning Steppes=Steppe Ardenti⟧.\n\nUsa le pozioni per attraversare Jaedenar e parla con sire Sacramorte.", "Mor'zul dice che vuoi aprire un portale verso Xoroth. Per farlo ti servirà della Polvere Stellare Xorotiana. Non è facile da trovare su Azeroth!\n\nC'è un essere che potrebbe averne: sire Sacramorte, a Jaedenar, la sede del ⟦Shadow Council=Concilio dell'Ombra⟧! Parla con lui e forse ti cederà la polvere stellare.\n\nMa se vai a Jaedenar, dovrai avvolgerti nella malvagità tipica del ⟦Shadow Council=Concilio dell'Ombra⟧. Per questo ti serviranno alcune delle mie Pozioni dell'Ombra, e ti costeranno...", nil, "La mia pazienza abbraccia i millenni, {class}. Ma non credere che ti conceda più di un istante del mio tempo...", 0xe235f822, 0xa034cca0, 0x1e3a4885, nil, 0xc224e623, "e..m." },
  [7624] = { "Ulathek il Traditore", "Affronta Ulathek, poi porta il ⟦The Traitor's Heart=Cuore del Traditore⟧ a sire Sacramorte, a Jaedenar.", "Vuoi entrare nelle mie grazie? Allora uccidi per me.\n\nIl mio servitore, Ulathek, striscia davanti a me in modo patetico, e intanto complotta con sire Hel'nurath su Xoroth. Hel'nurath intende usurpare il mio potere qui, e Ulathek è la sua spia...\n\nDimostra di servire me e non i miei rivali. Affronta Ulathek nei suoi alloggi, nell'⟦Shadow Hold=Eremo delle Ombre⟧ a ovest. Digli che conosco il suo segreto e guarda la paura impadronirsi di lui. Poi portami il cuore del traditore!", "Sento già il sapore del cuore di Ulathek sulle labbra. Com'è dolce la carne di un traditore...", "Ah, splendido! Dopo una settimana a marcire, questo cuore sarà una prelibatezza succulenta! Forse manderò a prendere la testa di Ulathek e la metterò davanti a me mentre mangio...\n\nMi hai reso un servizio, {class}, e così la mia pazienza nei tuoi confronti è cresciuta. Di poco.", 0x4b8d3a3d, 0xd5b88347, 0xe4198aaa, 0x01497fb4, 0x88afdb8f, "....." },
  [7625] = { "⟦Xorothian Stardust=Polvere Stellare Xorotiana⟧", "Compra la ⟦Xorothian Stardust=Polvere Stellare Xorotiana⟧ da Ur'dan. Portala a ⟦Gorzeeki Wildeyes=Gorzeeki Malalente⟧, nelle ⟦Burning Steppes=Steppe Ardenti⟧.", "Così vieni da me in cerca di polvere stellare xorotiana? Vuoi aprire un portale verso Xoroth, il dominio del mio rivale Hel'nurath? Forse intendi rubargli uno dei suoi preziosi maldestrieri?\n\nSia pure. Il mio servitore Ur'dan ha una scorta di polvere stellare xorotiana. Puoi ottenerla da lui... se sei in grado di pagarne il prezzo.", "Sei <stato/stata> a Jaedenar, {name}? Hai avuto la polvere stellare da sire Sacramorte?", "Eccola! Quasi non ci credo che tu ce l'abbia fatta! Devi aver concluso un grosso affare con quel signore del terrore, o pagato una bella somma, o tutte e due le cose!\n\nMor'zul avrà presto il suo inchiostro e potrà finalmente preparare la pergamena dei glifi, così potrai aprire un portale verso Xoroth e tirarne fuori uno dei famosi maldestrieri!", 0x545c6ef8, 0x4baa8da0, 0xfa59e779, 0x95c60713, 0x7a7c7622, "....." },
  [7626] = { nil, "Porta 10 Elisir del ⟦Shadow Power=Potere dell'Ombra⟧ a ⟦Gorzeeki Wildeyes=Gorzeeki Malalente⟧, nelle ⟦Burning Steppes=Steppe Ardenti⟧.", "Una Bell of Dethmoora, che prende il nome dal defunto stregone Dethmoora Darkeyes, è uno dei tre strumenti necessari per creare un Circle of Greater Summoning. Se accordati a dovere con la Wheel e la Candle, questi oggetti convogliano immense riserve di potere arcano.\n\nIl mio servitore Gorzeeki può costruire una campana simile, ma per farlo gli servirà una grande scorta di elisir del potere dell'ombra. Procurati gli elisir da un alchimista e portali a Gorzeeki.", "Hai quegli elisir, {name}? Mor'zul mi ha detto che ti serve una Bell of Dethmoora, e per farne una ci vuole un sacco di potere dell'ombra!", "Molto bene! Spero che questi elisir non siano stati troppo difficili da trovare. A volte gli alchimisti sanno essere così avari con le loro creazioni...\n\nPreparerò la campana e la terrò io finché non sarai <pronto/pronta> per il tuo rituale.", 0x8f2b3d75, 0x37da1da0, 0x4fb5aaf1, 0x3c4ced13, 0x93c74315, "e...." },
  [7627] = { nil, "Porta 6 Frammento Splendente Grande e 25 ⟦Dark Iron Ore=Minerale di Ferroscuro⟧ a Gorzeeki, nelle ⟦Burning Steppes=Steppe Ardenti⟧.", "Una Wheel of the Black March contiene e dirige le energie violente necessarie per il Circle of Greater Summoning. Perché Gozeeki possa costruire una ruota, gli serviranno sia frammenti splendenti grandi da un incantatore, sia minerale di ferroscuro da un maestro minatore.\n\nProcurateli e portali al mio servitore.", "La Wheel of the Black March non è facile da fare, e richiede un sacco di materiali. Li hai già raccolti?", "Eccoli! Ho sentito che il minerale di ferroscuro si trova solo nelle profondità di ⟦Blackrock=Roccianera⟧, e sono sicuro che nemmeno questi frammenti siano stati facili da trovare. Spesso resto a bocca aperta davanti alla dedizione di voi stregoni. Se invece metteste tutta quell'energia nell'arte di catturare insetti, oh... che banchetti vi godreste!\n\nScusa, una piccola divagazione. Creerò la ruota e la terrò per te finché non sarai <pronto/pronta> per il tuo rituale.", 0x1b0d9a93, 0x3e273a7a, 0xd77dc84e, 0xf3d47d02, 0xf3df9f45, "e...." },
  [7628] = { nil, "Porta 35 Scaglie di Drago Nero a ⟦Gorzeeki Wildeyes=Gorzeeki Malalente⟧, nelle ⟦Burning Steppes=Steppe Ardenti⟧.", "Una Doomsday Candle accumula il fuoco e lo dirige contro chi volesse disturbare il tuo rituale. Quando creerai il tuo Circle of Greater Summoning, se la candela sarà accesa, ogni demone ribelle verrà bruciato dalle sue fiamme!\n\nContenere quel fuoco non è facile: richiede l'essenza racchiusa nelle scaglie di un drago nero. Procurati quelle scaglie da un conciatore e portale a ⟦Gorzeeki Wildeyes=Gorzeeki Malalente⟧.", "Hai portato le scaglie di drago, {name}? Non voglio cominciare la candela finché non le ho... o potrei far saltare in aria l'intero accampamento!", "Ah, molto bene. Mi servono per contenere le fiamme della candela. Ora che ho le scaglie, preparerò la candela e la terrò io finché non sarai <pronto/pronta> a cominciare il rituale per il Circle of Greater Summoning.", 0x365c7d38, 0x95f646d3, 0xb19711bd, 0x45a89c38, 0x940d3218, "e...." },
  [7629] = { "Consegna di un imp", "Porta l'⟦Imp in a Jar=Imp in un Vaso⟧ al laboratorio alchemico di Scholomance. Dopo che la pergamena sarà stata creata, riporta il vaso a ⟦Gorzeeki Wildeyes=Gorzeeki Malalente⟧.", "La pergamena di Mor'zul richiede un'ultima lavorazione: mi serve della carta impregnata di polvere stellare xorotiana. E... temo di non poterlo fare qui. Non ho l'attrezzatura!\n\nC'è però un laboratorio alchemico con tutto il necessario. Si trova a Scholomance, sull'isola di Caer Darrow, nelle ⟦Plaguelands=Terre Infette⟧.\n\nIo non posso fare il viaggio, ma ecco, prendi questo vaso. Dentro c'è un imp molto abile. Fallo uscire nel laboratorio alchemico e impregnerà lui la pergamena.", "Sei <stato/stata> a Scholomance, {name}? L'imp ha già impregnato la pergamena con la polvere stellare?", "Ah, bene. J'eevee ha creato la pergamena. Com'era Scholomance? Incantevole, non trovi? E gli insetti laggiù... dicono che siano deliziosi!\n\nBen fatto, {name}, e grazie per avermi riportato il vaso. Ce l'ho da tanto tempo... e non è in vendita!", 0x671d5339, 0x29da576a, 0xcfb8f80b, 0x60220738, 0xf1d0309a, "....." },
  [7630] = { nil, "Porta 3 Lingotto d'Arcanite a Gorzeeki, nelle ⟦Burning Steppes=Steppe Ardenti⟧.", "Ora che Bell, Wheel e Candle sono pronte, dovrei preparare una magnetite nera. Durante il rituale ti servirà per sostenere gli altri oggetti rituali, se dovessero cedere.\n\nPer fare la magnetite mi serve dell'arcanite. Ne hai? Se no... dovrai procurartela da un alchimista.\n\nTorna da me quando avrai l'arcanite, e allora preparerò la magnetite nera.", "Hai l'arcanite, {name}? Quando ce l'avrò potrò prepararti la magnetite nera.", "Ce l'hai fatta! Ottimo lavoro! Ora posso creare la magnetite. Quando finalmente sarai <pronto/pronta> per il rituale per creare il Circle of Greater Summoning, vorrai avere una magnetite per essere sicur<o/a> che il rituale non vada in fumo!", 0xc51a3c6d, 0xe8bccc58, 0xbe1126f3, 0xe4b09957, 0x52e54ca1, "e...." },
  [7631] = { "Il maldestriero di Xoroth", "Leggi le ⟦Mor'zul's Instructions=Istruzioni di Mor'zul⟧. Evoca uno ⟦Xorothian Dreadsteed=Maldestriero Xorotiano⟧, sconfiggilo e poi lega a te il suo spirito.", "Tutti i preparativi sono fatti. Ora devi eseguire il rituale per creare un Circle of Greater Summoning, poi usare la pergamena impregnata di polvere stellare xorotiana... per aprire un portale verso Xoroth.\n\nHo scritto le istruzioni del rituale su una pergamena. Studiale con attenzione, perché dovrai eseguire ogni passo alla perfezione se vuoi riuscire.\n\nBuona fortuna, {name}. E possano le anime dei tuoi nemici finire presto nella tua borsa dei frammenti.", nil, "Lo spirito dello Xorothian Dreadsteed è sconfitto. Anche se la rabbia pulsa nei suoi fianchi spettrali, sai che l'anima della bestia è tua...\n\nTi sussurra magie oscure nella mente e infonde in te la conoscenza per evocare un maldestriero.", 0x006280f0, 0xe613427f, 0xe954e091, nil, 0xc275b0a3, "...m." },
  [7632] = { "L'antica foglia", "Trova il proprietario dell'⟦Ancient Petrified Leaf=Antica Foglia Pietrificata⟧. Buona fortuna, {name}: il mondo è grande.", "L'epidermide della foglia brilla di un verde intenso. La superficie è estremamente rugosa e lascia vedere diverse venature e grinze.\n\nSe dovessi tirare a indovinare, diresti che questa foglia proviene da qualcosa di antico e potente.\n\nForse dovresti cercare il proprietario originale di questa foglia?", "<Vartrus geme.>", "Certo che riconosco le mie foglie. Guarda! È in condizioni perfette.\n\nChe gentilezza da parte tua riportarla, {class}.\n\nForse potresti esserci utile, e noi a te.", 0x6c703ca7, 0x22a42d5f, 0xa0504cee, 0x8301899b, 0x54240120, "....." },
  [7633] = { "Una presentazione", nil, nil, nil, "La tua diligenza e la tua integrità non sono passate inosservate, {class}.\n\nSiamo Antichi: protettori di questa foresta un tempo grandiosa. Le nostre forme fisiche furono distrutte 10.000 anni fa, quando Archimonde e la Legione Infuocata marciarono su Hyjal. I nostri spiriti, però, restano intatti.\n\nAbbiamo dei compiti da offrirti. Compiti che, se portati a termine, ti sveleranno i segreti degli Antichi.\n\nSappi questo: se completerai questi compiti, ti basterà tornare a questa roccia e risponderemo al richiamo.", 0xcffb713f, nil, nil, nil, 0xfe0d07f1, ".mmm." },
  [7634] = { "⟦Ancient Sinew Wrapped Lamina=Faretra di Tendini Antichi⟧", "⟦Hastat the Ancient=Hastat l'Antico⟧ ti ha chiesto di portargli un ⟦Mature Blue Dragon Sinew=Tendine di Drago Blu Adulto⟧. Se lo trovi, riportalo a Hastat, nel ⟦Felwood=Vilbosco⟧.", "Salute, {class}. Sono Hastat, ⟦Ancient of Lore=Antico del Sapere⟧. Custodisco una conoscenza perduta da eoni.\n\nCon la giusta legatura, una delle mie foglie può diventare una faretra come non se ne vedono da 10.000 anni. Una faretra che, accompagnata da un arco degli Antichi, potrebbe conferire poteri inauditi.\n\nTorna qui con un tendine di drago blu adulto e questa faretra sarà tua.", "Bentornat<o/a>, giovane {class}.", "Possano le mie foglie proteggere le tue frecce da ogni danno. Possano le tue frecce colpire nel segno. Possano i nemici del nostro mondo essere annientati.", 0xf7d950a8, 0x21868862, 0x35ec2c30, 0x2ec24b6d, 0xaf5c947d, "....." },
  [7635] = { "Una corda adatta", "⟦Stoma the Ancient=Stoma l'Antico⟧ ti ha chiesto di portargli un ⟦Mature Black Dragon Sinew=Tendine di Drago Nero Adulto⟧. Se lo trovi, riportalo a Stoma, nel ⟦Felwood=Vilbosco⟧.", "Vartrus potrà offrirti il bastone per creare un arco degli Antichi, ma solo io posso incantare la corda necessaria a completarlo.\n\nÈ un compito semplice, piccoletto. Uccidi un drago nero adulto e strappagli il tendine dalle ossa. Riporta a me quel tendine e io lo incanterò fino a farne una corda d'arco quasi indistruttibile.", "Sono certo che non avrai difficoltà a trovare e uccidere un drago nero, {name}. Non sprecare il mio tempo in chiacchiere oziose.", "Questo era un drago davvero immondo. Il tendine puzza di malvagità.\n\nDammi un momento per purificare questa carne dalla sua lordura e applicare gli incantamenti adeguati.", 0x82676768, 0x3a73fecf, 0xff405978, 0x54b8d902, 0x7943c248, "....." },
  [7636] = { "Il bastone degli Antichi", "Devi trovare e distruggere questi quattro corruttori demoniaci:\n\nSimone the Seductress.\n\nKlinfran the Crazed.\n\nSolenor the Slayer.\n\nArtorius the Doombringer.\n\nDistruggi queste creature e torna con le loro teste da ⟦Vartrus the Ancient=Vartrus l'Antico⟧, nel ⟦Felwood=Vilbosco⟧.\n\nConsulta la ⟦Petrified Bark=Corteccia Pietrificata⟧ nel tuo inventario per avere indizi su dove si trovano.\n\nDEVI portare a termine questo compito da <solo/sola>.", "Gli agenti della Legione Infuocata sono ancora attivi nel nostro mondo, {class}. Questi agenti corrompono tutto ciò che toccano. La natura avvizzisce e piange in loro presenza.\n\nDevi rintracciare questi corruttori demoniaci e distruggerli, {name}. Attenzione: devi affrontarli da <solo/sola>, o fuggiranno. Finché sarai <solo/sola>, cercheranno di distruggerti. Devi colpirli e trasformare la loro arroganza in miseria.\n\nTi concedo un pezzo della mia corteccia: le sue iscrizioni ti guideranno ai tuoi bersagli. Riporta le loro teste.", "Non lasciarti ingannare dai loro travestimenti!", "Ci hai servito bene, {name}! Prendi questo bastone e uniscilo alla corda d'arco che Stoma sa creare. Insieme formano un'arma davvero formidabile.", 0xe66e38c8, 0x260f60be, 0x3e1d6949, 0xf436c2b1, 0x30e4645c, "....." },
  [7637] = { "L'importanza del sacrificio", "Recati a ⟦Ironforge=Forgiardente⟧ e ottieni l'⟦Rohan's Exorcism Censer=Incensiere per Esorcismo di Rohan⟧ dal sommo sacerdote Rohan. Per assicurartelo dovrai fare una donazione di 150 monete d'oro.", "Per prepararti a questo compito, devi prima dar prova del giusto sacrificio e del giusto giudizio... con particolare importanza al sacrificio.\n\nPer il tuo compito devi procurarti l'incensiere per esorcismo del sommo sacerdote Rohan. Anche se lo userai per motivi buoni e giusti, bisogna dare un adeguato compenso in cambio.\n\nRecati a ⟦Ironforge=Forgiardente⟧ e parla con il sommo sacerdote. Se porterai con te denaro a sufficienza per compensare la perdita del suo incensiere, darai prova del tuo giusto sacrificio.\n\nVa' ora, {name}, il tempo stringe.", "Salute, nobile <Paladino/Paladina>! Ho preparato il mio fidato incensiere con l'incenso più fresco e l'ho benedetto tre volte per te. La tua donazione aiuterà noi di ⟦Ironforge=Forgiardente⟧ non solo a creare un nuovo incensiere, ma anche a rimpinguare le scarse scorte di cibo per i nostri bisognosi.", "Che tu sia <benedetto/benedetta>, amico {class}! La tua donazione va ben oltre il necessario. Il tuo sacrificio non solo ci aiuterà a recuperare ciò che abbiamo perso, ma ci aiuterà anche ad aiutare i più bisognosi qui a ⟦Ironforge=Forgiardente⟧.\n\nOra lascia che mi assicuri di aver preparato a dovere questo incensiere per le tue necessità future...", 0xe1e9601f, 0x7e3b4971, 0xc697a1be, 0x6c931247, 0x92282285, "....." },
  [7638] = { nil, "Parla con ser Grayson Spezzaombra nel Cathedral District di Roccavento.", "È giunto il momento, {name}, di scoprire cosa ti servirà per ottenere qualcosa che senza dubbio aspetti da tempo... il tuo gran destriero.\n\nParla con ser Grayson Spezzaombra, qui nel Cathedral District di Roccavento. Sarà lui a guidarti, non solo nei misteri della cavalcatura più fidata di un Paladino, ma anche nei compiti che ti attendono per ottenerne una tua.\n\nTi auguro il meglio in questa prova. Per la Luce, nobile <fratello/sorella>!", nil, "Sono lieto di vederti, {name}. So che aspettavi di sapere come ottenere il tuo gran destriero, e ora quel momento è arrivato.\n\nSarai senz'altro mess<o/a> alla prova in molti modi, ma soprattutto nella tua volontà di superare i numerosi ostacoli che ti verranno posti davanti. Non si tratta di un esercizio di apprendimento: la tua levatura va oltre le semplici prove didattiche. Dovrai salvare il tuo futuro compagno dalle grinfie del male che hai combattuto per tutta la vita.\n\nPresta attenzione, il tuo momento è giunto!", 0x74c8e64a, 0x3b1a14c9, 0x73691ab8, nil, 0xa28a3953, "e..m.", nil, nil, 0x2123d8f1, nil, nil },
  [7639] = { "Dar prova di giusto giudizio", "Riporta l'⟦Exorcism Censer=Incensiere per Esorcismo⟧ a ser Grayson Spezzaombra, nel Cathedral District di ⟦Stormwind=Roccavento⟧.", "Prendi l'incensiere, con la mia benedizione. L'ho usato io stesso in diversi esorcismi, e dovrebbe esserti utile nelle ardue imprese che ti attendono.\n\nOra torna da ser Grayson Spezzaombra a ⟦Stormwind=Roccavento⟧, {name}. La tua missione continua con lui.", "Bentornat<o/a>, {name}. Hai ottenuto l'incensiere per esorcismo?", "Sì, questo andrà bene. Durante questo percorso ti verrà chiesto più di una volta di compiere atti di sacrificio; sono lieto di vedere che sei <disposto/disposta> a farlo. Il sacrificio è una componente chiave di ciò che serve per adempiere ai doveri di un Paladino... ma non devo certo farti la predica su questo.\n\nOra, {name}, dovrai mostrare giusto giudizio nelle tue azioni. A tal fine, questo incensiere sarà il tuo strumento per amministrare tale giudizio agli spiriti tormentati delle terre che abbiamo perduto.", 0xf5657bcb, 0x9f1f1c9b, 0x9b13b868, 0xcfa1dede, 0x2f09636b, "....." },
  [7640] = { "Esorcizzare ⟦Terrordale=Valterrore⟧", "Usa l'⟦Exorcism Censer=Incensiere per Esorcismo⟧ per scacciare gli spiriti che tormentano ⟦Terrordale=Valterrore⟧. Quando avrai ucciso 25 Terrordale Spirit, torna da ser Grayson Spezzaombra, nel Cathedral District di ⟦Stormwind=Roccavento⟧.", "Ho aggiunto all'incensiere un pizzico di terra presa dal suolo corrotto di ⟦Terrordale=Valterrore⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧. Ora userai questo incensiere per trovare là i luoghi che mostrano segni di tormento e inquietudine spirituale. Cerca le aure verdi che impregnano il terreno, dove il mondo fisico cede sotto il tormento del regno degli spiriti, e usa l'incensiere per scacciare gli spiriti malvagi.\n\nQuando avrai giudicato a sufficienza gli spiriti di quel luogo, sarai <pronto/pronta> a proseguire.", "È bello rivederti, {name}. Hai finito il tuo lavoro a ⟦Terrordale=Valterrore⟧?", "Ben fatto, {name}. Portare il giudizio della Luce su coloro che dimorano nelle tenebre è un compito da affrontare con vigore e zelo; ed è proprio ciò che hai fatto con il tuo sacrificio a ⟦Ironforge=Forgiardente⟧ e con i tuoi giudizi sugli spiriti di ⟦Terrordale=Valterrore⟧.\n\nI tuoi prossimi passi richiederanno di nuovo sacrificio e giudizio, mentre cercherai di reclamare lo spirito di un gran destriero caduto che ora serve un cavaliere della morte chiamato Razziabuio.", 0xb8674f67, 0x9033a6c2, 0x6654c6fe, 0x902cbc7e, 0xe4e8aafe, "....." },
  [7641] = { "L'opera di Grimand Elmore", "Parla con Grimand Elmore nel Distretto dei Nani di Roccavento.", "Il gran destriero di un paladino non è altro che una bestia da soma senza una bardatura adeguata. La bardatura del tuo gran destriero non solo deve essere fatta dei migliori materiali possibili, ma, viste le circostanze, deve anche essere sufficientemente in sintonia con il regno degli spiriti.\n\nPrima le cose importanti, {name}: facciamo preparare la tua bardatura. Nel Distretto dei Nani di Roccavento vive uno dei migliori artigiani dei nostri giorni, Grimand Elmore. Il suo lavoro non sarà economico, ma è proprio la sua qualità che cerchiamo. Parla con lui.", nil, "Salve! Lord Shadowbreaker mi ha avvisato in anticipo che saresti passat<o/a> da queste parti per vedermi. Sono disposto a fare la bardatura che ti serve, ma non sarà né economica né facile; mettiamolo in chiaro prima di tutto.\n\nDirò solo questo, e Grayson mi darà ragione quando lo affermo... non troverai una bardatura migliore in tutta Azeroth di quella che si fa proprio qui.", 0xaab3e85c, 0x315dc67f, 0x1c01eb68, nil, 0x4be6617c, "...m." },
  [7642] = { "La raccolta dei materiali", "Porta 40 Runecloth, 6 Lingotto d'Arcanite, 10 ⟦Arthas' Tears=Lacrima di Arthas⟧, 5 fiale di ⟦Stratholme Holy Water=Acqua Santa di Stratholme⟧ e 150 monete d'oro a Grimand Elmore, nel Distretto dei Nani di ⟦Stormwind=Roccavento⟧.", "Per la bardatura ti serviranno quattro cose: telarunica per la fodera, lingotti d'arcanite per le piastre, ⟦Arthas' Tears=Lacrima di Arthas⟧ per la sintonia spirituale e acqua santa di Stratholme per l'infusione spirituale. Anzi, te ne servono cinque... l'oro per il mio compenso. Il compenso comprende tutta la manodopera, oltre a una sella e a delle staffe fatte a mano.\n\nQuando avrai tutto, potrò finire la tua bardatura. Nel frattempo, posso cominciare a lavorare su alcune cose mentre tu raccogli i materiali.", "Ah, {class}. Non potrò finire la tua bardatura senza le cose che ti ho detto. Hai messo insieme tutto?", "Questo... be', è esattamente ciò che mi serviva. Sei <un/una> {class} piuttosto pien<o/a> di risorse, eh?\n\nBene, allora, finiamo questa bardatura per te!", 0x85fed7c1, 0x0cb21e13, 0x5cd28c73, 0xd90f59be, 0x77fdc05e, "....." },
  [7643] = { nil, "Procurati la biada speciale con cui si nutre un cavallo spirituale. A quanto pare è Merideth Carlson, a ⟦Southshore=Riva del Sud⟧, a fornire questo cibo.\n\nRecati nella spedizione di ⟦Dire Maul=Maglio Infausto⟧, nel Feralas, e uccidi ⟦Tendris Warpwood=Tendris Legnotorto⟧. Così libererai l'⟦Ancient Equine Spirit=Spirito Equino Antico⟧. Dagli da mangiare la biada speciale per placare lo spirito. Infine, dagli la ⟦Arcanite Barding=Bardatura d'Arcanite⟧ perché possa benedirla.", "La tua bardatura ha bisogno di una benedizione speciale, quella di uno spirito adatto. A ⟦Dire Maul=Maglio Infausto⟧ c'è proprio uno spirito del genere, l'⟦Ancient Equine Spirit=Spirito Equino Antico⟧. Al momento è prigioniero di un treant corrotto, ⟦Tendris Warpwood=Tendris Legnotorto⟧. Fai giustizia di questa bestia immonda, {name}.\n\nSappi questo: la libertà da sola non basta. Devi placare lo spirito prima di ricevere la sua benedizione. Per questo serve una biada speciale. Prima recati a ⟦Southshore=Riva del Sud⟧ e parla con Merideth Carlson... e preparati a nuovi sacrifici.", "L'⟦Ancient Equine Spirit=Spirito Equino Antico⟧ ti guarda in attesa, come se volesse qualcosa da te.", "L'⟦Ancient Equine Spirit=Spirito Equino Antico⟧ accetta l'offerta della ⟦Manna-Enriched Horse Feed=Biada Ricostituente Arricchita⟧ e strofina il muso contro il contenitore mentre si serve dell'avena e dei cereali speciali. Dopo aver mangiato un po', guarda la bardatura che porti con te e si mette in posizione, come se volesse che gliela posassi sul dorso...", 0xf903562c, 0x1c7e0042, 0x6827a6fe, 0x0088376a, 0x73dc7526, "e...." },
  [7644] = { "⟦Blessed Arcanite Barding=Bardatura d'Arcanite Benedetta⟧", "Torna con la ⟦Blessed Arcanite Barding=Bardatura d'Arcanite Benedetta⟧ da ser Grayson Spezzaombra, nel Cathedral District di ⟦Stormwind=Roccavento⟧.", "Appena posi la bardatura sul dorso dell'⟦Ancient Equine Spirit=Spirito Equino Antico⟧, questa si illumina appena. Per un breve istante l'aria si fa densa di potere, poi la bardatura scompare dal dorso del cavallo e ora è al sicuro nel tuo zaino.\n\nSembra che la bardatura sia stata benedetta. Secondo le istruzioni di lord Shadowbreaker, ora dovresti riportargliela a ⟦Stormwind=Roccavento⟧.", "{name}, sei tornat<o/a>! Sei riuscit<o/a> a cavartela con Merideth Carlson e con ⟦Tendris Warpwood=Tendris Legnotorto⟧? Sinceramente, a volte non so quale dei due sia la minaccia peggiore...", "Hai fatto molta strada, amico mio. La tua bardatura ora è pronta a dovere per l'ultimo compito.\n\nUserai questa bardatura per bardare il tuo gran destriero una volta completata la redenzione. Prima, però, dovrai affrontare una lotta immane. Il tuo momento si avvicina, evviva!\n\nC'è un ultimo oggetto da preparare prima di cominciare, {name}. Spero che la tua intraprendenza non ti abbia abbandonato da quando hai fatto preparare la bardatura...", 0xcd7cadda, 0xe2bdf073, 0x47656e16, 0x3b0ca232, 0x5f823dd1, "....." },
  [7645] = { "⟦Manna-Enriched Horse Feed=Biada Ricostituente Arricchita⟧", "Procura 20 Biscotto Ricostituente Arricchito, l'ingrediente chiave della ⟦Manna-Enriched Horse Feed=Biada Ricostituente Arricchita⟧, per Merideth Carlson a ⟦Southshore=Riva del Sud⟧, nelle ⟦Hillsbrad Foothills=Alture di Colletorto⟧. Si sa che l'⟦Argent Dawn=Alba d'Argento⟧ è l'unica a vendere questi biscotti.\n\nDevi anche darle 50 monete d'oro per placare il suo animo ferito.", "La ⟦Silver Hand=Mano d'Argento⟧ mi ha preso per PAZZA quando ho detto che sapevo preparare una biada speciale capace di nutrire i cavalli spirituali. TUTTI pensavano che fossi pazza! Be', ora è il momento della rivincita!\n\nTi preparerò quello che ti serve, PALADINO... cosiddetto CAMPIONE... ma ti costerà. Per questa miscela mi servono biscotti speciali, i Biscotti Ricostituenti Arricchiti venduti solo dall'⟦Argent Dawn=Alba d'Argento⟧. Pretendo anche, sì, PRETENDO dell'oro come risarcimento per tutte le miserie che ho sopportato!\n\nMostrami il sacrificio di cui ti vanti tanto, PALADINO.", "Sì, ora ti ho dimostrato che ti sbagliavi, vero? Ho dimostrato che si sbagliavano tutti! AVEVO RAGIONE FIN DALL'INIZIO!!!", "SÌ, E ADESSO CHI... aspetta... mi dai anche l'oro? Non sei tu quell<o/a> che mi ha dato della pazza (anzi, mi hanno dato della svitata da manicomio)... eppure sei <disposto/disposta> a sacrificarti persino per torti che non hai commesso?\n\nIo... ti ho giudicat<o/a> male, {name}. Se ti servirà altra biada, vieni da me. Te la darò gratis. Grazie... nobile {class}.\n\nPerò i soldi me li tengo: non sono così svitata da rinunciare a una fortuna.", 0x1f21fe01, 0x5da63733, 0x9d18fe77, 0x76c3ccbb, 0xb4ce0e54, "....." },
  [7646] = { "Il ⟦Divination Scryer=Veggente della Divinazione⟧", "Porta un ⟦Azerothian Diamond=Diamante Azerotiano⟧ e un ⟦Pristine Black Diamond=Diamante Nero Intatto⟧ a ser Grayson Spezzaombra, nel Cathedral District di ⟦Stormwind=Roccavento⟧.", "Ora dobbiamo assemblare un ⟦Divination Scryer=Veggente della Divinazione⟧: darà inizio alla prova che ti permetterà di redimere il gran destriero caduto. Il tuo veggente, in realtà, è quasi pronto. L'incensiere per esorcismo usato a ⟦Terrordale=Valterrore⟧ ne è il catalizzatore, e io realizzerò un alloggiamento adatto per il congegno.\n\nGli ultimi componenti necessari, però, sono due diamanti. Devono essere opposti nello splendore quanto nello scopo: un Diamante Azerotiano e un Diamante Nero Intatto. Questi due saranno il faro con cui il veggente squarcerà le ombre!", "Hai fatto tanta strada, {name}. Il tuo ultimo sacrificio di beni terreni sarà l'origine di una delle tue più grandi imprese. Lo sento in ogni fibra del mio essere!", "Sono esemplari splendidi, {name}: ora gli ultimi pezzi sono al loro posto. Finalmente, il tuo momento è giunto!\n\nNelle profondità del Great Ossuary di Scholomance giacciono i resti scheletrici di molte creature. Tra questi c'è un gran destriero un tempo nobile. L'anima svuotata di questo destriero ora fa da cavalcatura al cavaliere della morte Razziabuio. È lui che dovrai affrontare, ed è su questo destriero che dovrai esprimere il tuo giudizio. Solo tu, {name}, puoi redimere la sua anima e salvarla dal tormento della sua schiavitù.", 0x97882862, 0x21b1c1d8, 0xa1bffac1, 0x377927dd, 0x1b514838, "....." },
  [7647] = { "Giudizio e redenzione", "Usa il ⟦Divination Scryer=Veggente della Divinazione⟧ nel cuore del sotterraneo del Great Ossuary, a Scholomance. Così farai apparire gli spiriti che dovrai giudicare. Sconfiggere questi spiriti evocherà il cavaliere della morte Darkreaver. Sconfiggilo e reclama l'anima perduta del gran destriero caduto.\n\nConsegna l'⟦Charger's Redeemed Soul=Anima Redenta del Gran Destriero⟧ e la Blessed Enchanted Barding a ⟦Darkreaver's Fallen Charger=Destriero Caduto del Razziabuio⟧.", "Prendi questa sacca: dentro ci sono gli oggetti che ti serviranno per il tuo compito.\n\nUsa il veggente della divinazione nel cuore del sotterraneo del Great Ossuary per far apparire gli spiriti maledetti che devono essere giudicati. Usa con saggezza i tuoi Giudizi durante questa prova: si riveleranno più potenti di quanto immagini. Dopo gli spiriti apparirà il cavaliere della morte: sconfiggilo e reclama l'anima perduta del gran destriero. Solo allora, {name}, potrai redimerlo e porre la tua bardatura sulla tua nuova cavalcatura!\n\nBuona fortuna!", "Lo spirito del gran destriero caduto ti fissa con sguardo afflitto. Occhi tristi, quasi vuoti, ti guardano come se per lui ogni speranza fosse perduta.", "Un barlume di vita, assente da tempo nella povera bestia, gli brilla negli occhi mentre gli restituisci l'anima giudicata. Senti un'ondata di potere sacro avvolgerti mentre gli posi la bardatura sul dorso, dopo aver giudicato redento il gran destriero. Il gran destriero ti strofina il muso sulla mano mentre i fardelli del passato si sollevano dalla bestia. Ora senti di poter chiamare questa bestia a servirti come cavalcatura, se ce ne fosse bisogno.\n\nHai ottenuto il tuo gran destriero epico, {class}! Congratulazioni!", 0x46dcb4ff, 0x720120e9, 0x050b5849, 0x6ef6d085, 0x1d80ecd4, "....." },
  [7648] = { "Il capolavoro di Grimand", "Porta la ⟦Arcanite Barding=Bardatura d'Arcanite⟧ a ser Grayson Spezzaombra, nel Cathedral District di Roccavento, perché la esamini.", "<Grimand si asciuga il sudore dalla fronte, raggiante d'orgoglio.>\n\nEccola qua, amico mio. È uno dei miei lavori migliori, all'altezza della bardatura che feci con le mie mani per lord Shadowbreaker quando andò a prendersi il suo gran destriero. Ti ringrazio per esserti <affidato/affidata> a me per avere il meglio.\n\nDi certo anche Grayson vorrà vedere il lavoro con i suoi occhi. Portagli la bardatura, e ringrazialo da parte mia per l'onorevole affare.", "Stai procedendo bene, {name}. Una volta pronta la tua bardatura, sarai a buon punto verso il prossimo compito.", "È un lavoro davvero notevole. Pare che, invecchiando, Grimand continui a migliorare la sua maestria. È un'impresa non da poco, visto che il suo lavoro era già tra i migliori che si potessero trovare quando fece la mia bardatura, ai tempi.\n\nQuesta bardatura sarebbe un'ottima aggiunta per qualsiasi cavalcatura normale, ma qui non abbiamo a che fare con una bestia tanto comune. Dovrai far benedire questa bardatura da una fonte adatta perché sia degna di posarsi sul gran destriero di <un/una> {class}. Fino ad allora la terrò io per te.", 0xc224bd2c, 0x080a2e44, 0xe90e8178, 0x7eeec2ce, 0xe0f17de5, "....." },
  [7649] = { nil, "Restituisci il libro ai legittimi proprietari.", "Il tomo porta il marchio dell'Athenaeum.", "Hai recuperato un tomo!", "Ben fatto, ragazzo mio.\n\n<Lo storico Lydros strappa una pagina dal libro.>\n\nSono sicuro che questa ricetta ti tornerà utile.", 0x3ac91124, 0xdeb95520, 0x10e08c8e, 0xd98d4887, 0x381b7184, "e...." },
  [7650] = { nil, "Restituisci il libro ai legittimi proprietari.", "Il tomo porta il marchio dell'Athenaeum.", "Hai recuperato un tomo!", "Ben fatto, ragazzo mio.\n\n<Lo storico Lydros strappa una pagina dal libro.>\n\nSono sicuro che questa ricetta ti tornerà utile.", 0x14e3c64b, 0xdeb95520, 0x10e08c8e, 0xd98d4887, 0x381b7184, "e...." },
  [7651] = { nil, "Restituisci il libro ai legittimi proprietari.", "Il tomo porta il marchio dell'Athenaeum.", "Hai recuperato un tomo!", "Ben fatto, ragazzo mio.\n\n<Lo storico Lydros strappa una pagina dal libro.>\n\nSono sicuro che questa ricetta ti tornerà utile.", 0xb08e78dc, 0xdeb95520, 0x10e08c8e, 0xd98d4887, 0x381b7184, "e...." },
  [7652] = { "Un affare a luce blu", nil, nil, nil, "Allora, signore, ho un affare d'oro per te.\n\nVoglio sbarazzarmi di un po' di questi progetti di armature a piastre imperiali e mi serve qualcuno disposto a prendersi il disturbo. In cambio voglio solo qualche lingotto di torio. Che ne dici?", 0x2ebc19cb, nil, nil, nil, 0xb746ed6b, ".mmm." },
  [7653] = { "⟦Imperial Plate Belt=Cintura a Piastre Imperiale⟧", nil, nil, "Per il progetto della cintura mi servono 20 lingotti di torio.", "È un piacere fare affari con te.\n\nE {name}, togliti quell'espressione disgustata dalla faccia.", 0xc0c8edee, nil, nil, 0x32c34c39, 0xdea64556, ".mm.." },
  [7654] = { "⟦Imperial Plate Boots=Stivali a Piastre Imperiali⟧", nil, nil, "Per il progetto degli stivali mi servono 40 lingotti di torio. Già, 40. Che fai, piangi? Vuoi un fazzoletto?\n\n<Derotain ride.>", "È un piacere fare affari con te.\n\nE {name}, togliti quell'espressione disgustata dalla faccia.", 0xa8299450, nil, nil, 0x8040fdb8, 0xdea64556, ".mm.." },
  [7655] = { "Bracciali a Piastre Imperiali", nil, nil, "Per il progetto dei bracciali mi serviranno 20 lingotti di torio.\n\nTutto a posto, ragazzo? Stai diventando tutto rosso.", "È un piacere fare affari con te.\n\nE {name}, togliti quell'espressione disgustata dalla faccia.", 0x400b50c6, nil, nil, 0xd88eb51a, 0xdea64556, ".mm.." },
  [7656] = { "⟦Imperial Plate Chest=Corazza a Piastre Imperiale⟧", nil, nil, "Per il progetto della corazza mi serviranno 60 lingotti di torio.\n\nOh, ci risiamo. Adesso corri dai tuoi dèi blu a chiedergli perché ti hanno abbandonato?!? Fatti forza, femminuccia! Nessuno ha mai detto che la vita è giusta.", "È un piacere fare affari con te.\n\nE {name}, togliti quell'espressione disgustata dalla faccia.", 0xb8c48c88, nil, nil, 0xeb58fce6, 0xdea64556, ".mm.." },
  [7657] = { "⟦Imperial Plate Helm=Elmo a Piastre Imperiale⟧", nil, nil, "Dammi 50 lingotti di torio e il progetto dell'elmo è tuo.", "È un piacere fare affari con te.\n\nE {name}, togliti quell'espressione disgustata dalla faccia.", 0xc196bf89, nil, nil, 0xcb20090a, 0xdea64556, ".mm.." },
  [7658] = { "⟦Imperial Plate Leggings=Gambiere a Piastre Imperiali⟧", nil, nil, "Dammi 60 lingotti di torio e il progetto delle gambiere è tuo.\n\nLo so, ti sto mandando in rovina! Le ho già sentite tutte, quindi risparmiami la tua storia strappalacrime, smidollato.", "È un piacere fare affari con te.\n\nE {name}, togliti quell'espressione disgustata dalla faccia.", 0xdfbf0203, nil, nil, 0xbb263d48, 0xdea64556, ".mm.." },
  [7659] = { "⟦Imperial Plate Shoulders=Spallacci a Piastre Imperiali⟧", nil, nil, "Per il progetto degli spallacci mi serviranno 20 lingotti di torio.", "È un piacere fare affari con te.\n\nE {name}, togliti quell'espressione disgustata dalla faccia.", 0x58cf3eb5, nil, nil, 0x48278a6f, 0xdea64556, ".mm.." },
  [7667] = { "Aiuto materiale", "Se vuoi aiutare Sagorne Crestrider nella Valle della Saggezza di Orgrimmar, portagli un ⟦Azerothian Diamond=Diamante Azerotiano⟧ e un ⟦Pristine Black Diamond=Diamante Nero Intatto⟧.", "{name}, c'è una questione urgente in cui spero tu possa aiutarmi... sia materialmente sia spiritualmente. Lascia che ti spieghi.\n\nNelle profondità di Scholomance, a Lordaeron, c'è una sala chiamata Great Ossuary. Devo completare un congegno capace di penetrare le ombre di quell'orribile stanza. Per finire ciò che ho iniziato mi servono due diamanti: un Diamante Azerotiano e un Diamante Nero Intatto. Non sono cose da poco, lo so, ma io non ho i mezzi per procurarmeli.\n\nPotresti portarmene uno per tipo?", "Mi mette a disagio chiedere un aiuto materiale, ma il mio veggente della divinazione, il congegno che spero di finire, richiede un diamante per tipo. Se non puoi aiutarmi, capirò di certo.", "La tua generosità non ha eguali, {name}. Ti ringrazio per la tua gentilezza.\n\nOra potrò finire il mio veggente della divinazione, e dovrei riuscire a fabbricarne altri senza bisogno di altri diamanti... forse ti interesserebbe aiutarmi a usarlo? È per un compito importantissimo, te lo assicuro... uno che, se trascurato, potrebbe significare un disastro totale per il regno degli spiriti!", 0x2664d220, 0x5802fb11, 0xd94f2e58, 0x7d7fce4f, 0xdff68b8a, "....." },
  [7668] = { "La minaccia del Razziabuio", "Usa il ⟦Divination Scryer=Veggente della Divinazione⟧ nel cuore del sotterraneo del Great Ossuary, a Scholomance. Così facendo evocherai degli spiriti che dovrai combattere. Sconfitti gli spiriti, comparirà ⟦Death Knight Darkreaver=Cavaliere della Morte Razziabuio⟧: sconfiggilo.\n\nPorta la ⟦Darkreaver's Head=Testa del Razziabuio⟧ a ⟦Sagorne Creststrider=Cardoza Marcia Creste⟧ nella Valle della Saggezza, a Orgrimmar.", "Il cavaliere della morte Razziabuio domina il Great Ossuary di Scholomance. Minaccia di piegare il regno degli spiriti al proprio volere, e va fermato! Ed è qui che entra in gioco il veggente che mi hai aiutato a costruire.\n\nUsa il Veggente della Divinazione nel cuore del sotterraneo del Great Ossuary per evocare gli spiriti servitori del Razziabuio. Sconfiggi gli spiriti e il cavaliere della morte in persona apparirà. {name}, portami la sua testa! Solo la sua fine potrà riparare il danno inflitto al regno degli spiriti!", "Il tempo stringe, {name}: sei riuscit<o/a> a fermare la minaccia del cavaliere della morte Razziabuio?", "Questa è una vittoria da assaporare, {name}! La fine del Razziabuio dovrebbe ripristinare i fragili vincoli che tengono ancorato il regno degli spiriti.\n\nHai fatto molto più di quanto ti fosse stato chiesto, anche quando non avevi idea di ricompense o compensi. Sei davvero <un/una> {class} di valore, amico mio.\n\nSo che agire per preservare il regno degli spiriti dovrebbe essere già un ringraziamento sufficiente, ma ti prego: accetta questo semplice dono con la mia gratitudine.", 0xf4f3bcea, 0x03ae7ce9, 0x5b13350d, 0xc513241d, 0x44e1ce14, "....." },
  [7670] = { nil, "Parla con ser Grayson Spezzaombra nel Cathedral District di Roccavento.", "È giunto il momento, {name}, che tu scopra cosa ti servirà per ottenere qualcosa che senza dubbio aspetti da tempo... il tuo gran destriero.\n\nParla con ser Grayson Spezzaombra nel Cathedral District di Roccavento. Sarà lui a guidarti non solo nei misteri della cavalcatura più fidata di un paladino, ma anche nelle prove che dovrai affrontare per averne una tua.\n\nTi auguro il meglio in questa prova. Per la Luce, nobile <fratello/sorella>!", nil, "Sono lieto di vederti, {name}. So che aspettavi di sapere come ottenere il tuo gran destriero, e ora quel momento è arrivato.\n\nSarai senz'altro mess<o/a> alla prova in molti modi, ma soprattutto nella tua volontà di superare i numerosi ostacoli che ti verranno posti davanti. Non si tratta di un esercizio di apprendimento: la tua levatura va oltre le semplici prove didattiche. Dovrai salvare il tuo futuro compagno dalle grinfie del male che hai combattuto per tutta la vita.\n\nPresta attenzione, il tuo momento è giunto!", 0x74c8e64a, 0x3b1a14c9, 0x31869d0c, nil, 0xa28a3953, "e..m.", nil, nil, 0x4f89b0e5, nil, nil },
  [7681] = { "Missione di prova del Cacciatore", "Nutri il tuo animale, poi parla con chi ti ha affidato la missione.", "Lancia Feed Pet sul tuo animale.", nil, nil, 0x746b49f4, 0x2f058422, 0x34b38a3e, nil, nil, "...mm" },
  [7682] = { "Missione di prova del Cacciatore2", "Nutri il tuo animale, poi parla con chi ti ha affidato la missione.", "Lancia Feed Pet sul tuo animale.", nil, nil, 0x92e6d935, 0x2f058422, 0x34b38a3e, nil, nil, "...mm" },
  [7701] = { "RICERCATO: il sovrintendente Maltorius", "Nelle profondità della Fossa delle Scorie della Caldera Magmatica, nella ⟦Searing Gorge=Gorgia Rovente⟧, troverai il nano ⟦Dark Iron=Ferroscuro⟧ traditore, il sovrintendente Maltorius.\n\nUccidi il sovrintendente Maltorius e prendi la sua testa. Riporta la testa al capitano di vedetta Lolo Colpolungo, nella ⟦Searing Gorge=Gorgia Rovente⟧, per avere la ricompensa.", "Per ordine de sua eminenza, er sovrintendente Pugnograsso: l'agente rinnegato della ⟦Thorium Brotherhood=Fratellanza del Torio⟧ e nuovo comandante della squadra ⟦Dark Iron=Ferroscuro⟧ della Fossa delle Scorie della Caldera Magmatica, er sovrintendente Maltorius, dev'esse' ammazzato e la sua testa riportata come prova der fatto.\n\nPe' la ricompensa de 'sta taglia, rivolgersi ar capitano di vedetta Lolo Colpolungo.", "Non lo vedi che shono occupato? Cosha *hic* vuoi? *hic*", "Non penshavo che avrei rivishto 'shto brutto muso!\n\nShta perfino meglio shenza il reshto di lui attaccato.\n\nEcco la tua ricompensha *hic*, {race}.", 0x03010d28, 0x0202bf14, 0xa7a8fb6a, 0xf201932b, 0x5c34de3e, "....." },
  [7703] = { "Affari Gordok in sospeso", "Trova il ⟦Gauntlet of Gordok Might=Guanto della Forza Gordok⟧ e riportalo al capitano Kromcrush a ⟦Dire Maul=Maglio Infausto⟧.\n\nSecondo Kromcrush, la \"storia dei vecchi tempi\" dice che Tortheldrin, un elfo \"inquietante\" che si faceva chiamare principe, lo rubò a uno dei re Gordok.", "Ora tu re, quindi forse tu riprendi prezioso cimelio Gordok da elfo inquietante che si fa chiamare Principe! Re prima di te ha fallito, come tutti altri re da quando Tortheldrin, elfo inquietante, l'ha rubato a vecchio re Gordok dei vecchi tempi!\n\nCimelio si chiama ⟦Gauntlet of Gordok Might=Guanto della Forza Gordok⟧. Storie dei vecchi tempi dicono che solo unico vero re dei Gordok può riprenderlo. Storia dei vecchi tempi dice anche che elfo inquietante è ancora qui intorno: tu lo trovi e diventa guanto possente che tu porti per sempre! Yar, io ti faccio vedere!", "Ah, tu non trovato, vero capo? Forse storia dei vecchi tempi è storia brutta... difficile credere che elfo inquietante può rubare a re Gordok!", "Wow... tu SEI ver<o/a> <re/regina>! Io mai pensato di vedere questo guanto in mia vita! Sembra che non ha più mojo... forse elfo inquietante ha provato a rovinare guanto. Be', io dico HAR HAR a lui!\n\nGuarda: questo segno su guanto è segno magico dei vecchi vecchi VECCHI tempi, più vecchio dei Gordok, dicono. Be', come Capitano dei Gordok, noi tutti impariamo una cosa più e più volte: come far tornare in vita segno e ridare potere a guanto!\n\nIo lo faccio per te, <re/regina>! Ecco, prendi guanto e regna PER SEMPRE!", 0xd84c3631, 0xbc347604, 0x302edb3f, 0x238a10a1, 0x67a5cc2d, ".....", nil, nil, nil, nil, 0x01f9cd5f },
  [7704] = { "Guarda che dimensioni!", "Porta Chambermaid Pillaclencher's Pillow a ⟦Evonice Sootsmoker=Evonice Fumacenere⟧, nella ⟦Searing Gorge=Gorgia Rovente⟧.", "Bene, bene, bene... Che sorpresa. La cameriera aveva un cuscino gigantesco e tutto decorato, e ora è tuo. ⟦Evonice Sootsmoker=Evonice Fumacenere⟧ vorrà di sicuro metterci sopra le sue manine sudicie. Portaglielo e vedi se ti offre qualche regalino per il disturbo.", nil, nil, 0x446e8ded, 0xd6d832a4, 0xe1b953bc, nil, nil, "...mm" },
  [7721] = { "Carburante per il raggio", "Raccogli 10 Nucleo dell'⟦Water Elemental=Elementale dell'Acqua⟧ dai Sea Elemental e dai Sea Spray lungo la Costa dell'Oblio, a Feralas, e riportali a ⟦Zorbin Fandazzle=Zorbin Saldaleva⟧, vicino al molo.", "Se scommetto contro il mio stesso buon senso e resto ad aprire una bottega di ingegneria lungo la Costa dell'Oblio, dovrò occuparmi di questi elementali molesti. Maledetti i poteri elementali senza freno, dico io!\n\nPer mia fortuna, e ora anche per la tua, mi<o/a> speranzos<o/a> agente provocat<ore/rice>, gli elementali sono una fonte ideale di energia grezza per il perfezionamento del mio Ultra Riduttore: dagli una bella lezione, dico io! Mentre lo fai, però, assicurati di conservarmi i nuclei degli elementali dell'acqua!", "Potrei annoiarti con i dettagli tecnici sull'utilità dei nuclei elementali, ma preferisco invogliarti a portare a termine questo importante compito offrendoti monete e premi di valore. Orsù, in verità, hai finito?", "Strabiliantastico! Questi nuclei mi terranno al lavoro per un bel po'. Aggiungi il vantaggio che ora ci sono meno elementali lungo la costa, e forse non piangerò più fino ad addormentarmi al pensiero di aver aperto bottega nel posto forse peggiore che si possa immaginare!\n\nGrazie, {name}, per l'impegno che ci hai messo per me. Anche se finanziariamente mi mette alle strette, lascia che ti mostri un po' di gratitudine in una forma che capirai e apprezzerai... bottino!", 0x809826c8, 0x3172fbce, 0x2e6a8654, 0x00a49bad, 0x0d4b34c8, "....." },
  [7722] = { "Ma che flussante?", "Da qualche parte nella Fossa delle Scorie della Caldera Magmatica troverai il ⟦Secret Plans: Fiery Flux=Progetto Segreto: Flussante Infuocato⟧ che il sovrintendente Maltorius ha rubato. Trova il progetto e riportalo al maestro fabbro Ardirabbia, nella ⟦Searing Gorge=Gorgia Rovente⟧.", "Quando quel bastardo di Maltorius ha lasciato il nostro clan, se n'è andato con qualcosa di più prezioso di un cristallo arcano intatto: la nostra ricetta del flussante infuocato! Ci scommetterei qualsiasi cosa che la ricetta faceva parte dell'accordo per la sua nuova promozione tra i Ferroscuro.\n\nVoglio che tu recuperi i nostri piani segreti, {name}. Sono sicuro che si trovano da qualche parte vicino a Maltorius, nelle profondità della Fossa delle Scorie.", "Hai trovato i piani?", "Spero che gli abbia anche spaccato i denti, {name}. Ragnaros sa che se lo meritava.\n\nOra possiamo passare agli affari.", 0xc07aa3bb, 0x8f132878, 0x336636d3, 0x85bbae45, 0x27d3986a, "....." },
  [7723] = { "Maledette dita gonfie", "⟦Hansel Heavyhands=Hansel Maniforti⟧ vuole che tu uccida 20 Heavy War Golem.\n\nGli Heavy War Golem si aggirano nelle zone attorno alla Caldera Magmatica, nella ⟦Searing Gorge=Gorgia Rovente⟧. Quando ne avrai uccisi abbastanza, torna da Hansel nella ⟦Searing Gorge=Gorgia Rovente⟧.", "Purtroppo non posso più menar le mani come una volta, per via di 'sto problema delle dita gonfie. Vedi, il clima di quaggiù, insieme alla mancanza di pressione dell'aria, mi fa gonfiare le dita. Sono come giganteschi sanguinacci di Thelsamar, eccome...\n\nTi toccherà sbrigare i miei affari e compagnia bella.\n\nPrimo punto della mia lista: pestare a sangue i golem da guerra pesanti della Gorgia. Datti da fare.", "Li hai pestati?", "Sei <un/una> <bravo/brava> <ragazzo/ragazza>, eccome se lo sei. Ti ho preso un regalino per il disturbo.", 0x1866df92, 0x2dfa4f25, 0xe5c62f10, 0xcbb0cf9d, 0xcf9f67a7, ".....", nil, nil, nil, nil, 0x53921380 },
  [7724] = { "Minaccia infuocata!", "⟦Hansel Heavyhands=Hansel Maniforti⟧ vuole che tu uccida 20 Greater Lava Spider nella ⟦Searing Gorge=Gorgia Rovente⟧. Trovi i Greater Lava Spider sugli altipiani e nelle pozze di lava della ⟦Searing Gorge=Gorgia Rovente⟧.\n\nTorna da ⟦Hansel Heavyhands=Hansel Maniforti⟧ nella ⟦Searing Gorge=Gorgia Rovente⟧ quando avrai ucciso abbastanza Greater Lava Spider.", "Guarda un po', ogni volta che il vecchio Hansel vuole prendersi un momento per rilassarsi e riflettere sulla sua vita, i pezzi grossi gli rifilano un altro lavoro.\n\nMi tocca pensare, ma dai! Capisci cosa voglio dire? Ma. Dai.\n\nDunque, 'sti grandi ragni di lava stanno facendo una specie di baccano. Oilfist dice che sparano fuoco dal loro... ehm, sì, be', comunque, cose del genere spaventano i bambini.\n\nMi sa che dobbiamo ammazzarli. Anzi, sei tu che devi ammazzarli.", "Aveva ragione? Gli esce dal sedere?", "<Hansel starnutisce.>\n\nMi sa che mi sto prendendo un raffreddore. Maledetto questo clima gelido!", 0xe1aa77fc, 0xf5e8572b, 0x14a3807c, 0x57ac94ac, 0x18ad5817, "....." },
  [7727] = { "Incendiosauri? Chissàchesauri, piuttosto", "⟦Hansel Heavyhands=Hansel Maniforti⟧ vuole che tu uccida 20 Incendosaur.\n\nTroverai gli Incendosaur nelle pozze di lava all'interno della ⟦The Slag Pit=Fossa delle Scorie⟧. La ⟦The Slag Pit=Fossa delle Scorie⟧ si trova nella Caldera Magmatica della ⟦Searing Gorge=Gorgia Rovente⟧.\n\nTorna da ⟦Hansel Heavyhands=Hansel Maniforti⟧ nella ⟦Searing Gorge=Gorgia Rovente⟧ quando avrai ucciso abbastanza Incendosaur.", "Calli, <ragazzo/ragazza>. I miei calli hanno i calli. Come faccio ad ammazzare qualcosa con i piedi conciati così? Ecco perché mi aiuterai tu.\n\nScrange e Burninate mi hanno incaricato di uccidere quelle bestie, così potranno mandare qualche squadra di spedizione giù nelle pozze di lava della Fossa delle Scorie a esplorare un po'. Pare che laggiù ci siano degli incendiosauri o qualche altra sciocchezza del genere che creano problemi di ogni sorta. Ora muoviti, e non tornare finché gli incendiosauri non saranno estinti.", "<Hansel si massaggia i calli con grande impegno.>\n\nNon startene lì impalat<o/a>, prendi un po' d'olio e una spugna di luffa e mettiti a strofinare 'sti calli.\n\nNon hai una spugna di luffa? Be', allora! Forse è ora che ti mandi a cercarne una?\n\nEhi, dove vai?", "Oh, i miei poveri piedi.\n\nHo pensato che, visto che non avevi una spugna di luffa...", 0xd4823678, 0x244f3d0d, 0xe0116ef8, 0xc2bee4d5, 0x071dfa2a, ".....", nil, nil, 0x64ef711a, nil, nil },
  [7728] = { "RUBATI: ⟦Smithing Tuyere=Tubo per Fucine⟧ e ⟦Lookout's Spyglass=Cannocchiale della Vedetta⟧", "Trova e riporta il ⟦Smithing Tuyere=Tubo per Fucine⟧ e il ⟦Lookout's Spyglass=Cannocchiale della Vedetta⟧ al coordinatore Scrange, nella ⟦Searing Gorge=Gorgia Rovente⟧.\n\nLe uniche informazioni che hai su questi oggetti sono le seguenti: sono stati di sicuro rubati dai nani ⟦Dark Iron=Ferroscuro⟧. Il ⟦Smithing Tuyere=Tubo per Fucine⟧ è un attrezzo usato dai fabbri, e il ⟦Lookout's Spyglass=Cannocchiale della Vedetta⟧ è uno strumento di sorveglianza prezioso per le vedette.", "Sono stati rubati i seguenti oggetti:\n\n*Un tubo per fucine ⟦Dark Iron=Ferroscuro⟧.\n\n*Un ⟦Lookout's Spyglass=Cannocchiale della Vedetta⟧.\n\nViene offerta una ricompensa a chi troverà e restituirà questi oggetti trafugati.\n\nLa ⟦Thorium Brotherhood=Fratellanza del Torio⟧ è certa che questi oggetti siano stati rubati dai nani ⟦Dark Iron=Ferroscuro⟧, invidiosi e senza scrupoli, che abitano la ⟦Searing Gorge=Gorgia Rovente⟧.\n\nIl cannocchiale in questione era un ottimo strumento per le vedette, e il tubo era un attrezzo da fabbro insostituibile.\n\nSe trovi gli oggetti scomparsi, riportali a Scrange.", "Se sei qui per la ricompensa, dovrai darmi la refurtiva.", "Lavoro fantastico! Ora, la tua ricompensa.", 0x64a25f02, 0xa792a255, 0xd964ba68, 0x75ecaf91, 0x700453bf, "....." },
  [7729] = { "OFFERTA DI LAVORO: sfoltire la concorrenza", "Uccidi 15 Dark Iron Taskmaster e 15 Dark Iron Slaver. Quando hai finito, torna dal coordinatore Scrange nella ⟦Searing Gorge=Gorgia Rovente⟧.", "Il coordinatore Scrange cerca qualche brav'uomo e qualche brava donna che aiuti a \"sfoltire la concorrenza\" nella ⟦Searing Gorge=Gorgia Rovente⟧.\n\nSe ti interessa questo incarico, avventurati nella ⟦Searing Gorge=Gorgia Rovente⟧ e massacra ogni ⟦Dark Iron Taskmaster=Coordinatore Ferroscuro⟧ e ogni ⟦Dark Iron Slaver=Schiavista Ferroscuro⟧ che vedi.\n\nTorna dal coordinatore Scrange quando i tuoi vestiti saranno abbastanza insanguinati.\n\nSaprai tu quando lo saranno, quindi non chiedere.", "Dovremo pesarti con e senza vestiti, per esserne sicuri.", "15.9 libbre! Potrebbe essere un nuovo record di peso di sangue e budella sui vestiti! Congratulazioni, {class}!", 0x27d0f06d, 0x743a8c0d, 0x9394b676, 0x765dfe1d, 0xd80310ca, "....." },
  [7730] = { "Infestazione di Zukk'ash", "Porta 20 Carapace di Zukk'ash a ⟦Hadoken Swiftstrider=Hadoken Passo Lesto⟧ all'⟦Camp Mojache=Accampamento Mojache⟧, a Feralas.", "Da quel poco che siamo riusciti a scoprire in ricognizione, crediamo che il nemico a sud degli gnoll sia una razza simile agli insetti. Francamente, che siano senzienti o no è irrilevante. Se sono loro a spingere gli gnoll alla furia contro di noi, allora sono una minaccia grande quanto gli gnoll, se non di più.\n\nSpingiti in profondità dove vivono questi insetti Zukk'ash, un luogo noto come la Fossa Fremente. Riducine il numero e riferiscimi cosa trovi, portando i loro carapaci come prova del tuo lavoro.", "Come va la caccia, {name}? Sei qui per riferirmi il tuo successo?", "Ben fatto, {class}. Anche se la presenza così estesa degli Zukk'ash non sarà fermata con niente di meno di un'invasione su vasta scala, ci hai fatto guadagnare un po' di tempo per mettere a punto una strategia adeguata.\n\nMi assicurerò di far analizzare questi carapaci; dovremo sapere tutto di loro prima di affrontare quello che, purtroppo, si è rivelato un problema molto più grande di quanto avessimo previsto.", 0x932e3026, 0xb72ef59a, 0x883ce546, 0xc0557a8f, 0x83d0e4be, "....." },
  [7731] = { "⟦Stinglasher=Sferzaculei⟧", "Sconfiggi ⟦Stinglasher=Sferzaculei⟧ nella Fossa Fremente e porta le sue ghiandole a ⟦Hadoken Swiftstrider=Hadoken Passo Lesto⟧, all'⟦Camp Mojache=Accampamento Mojache⟧, a Feralas.", "Durante il sopralluogo nella Fossa Fremente, uno dei nostri esploratori ha riferito di aver visto un insetto gigantesco, molto più grande degli altri avvistati, aggirarsi per quel terreno contorto. Non solo è più grande, ma sembra anche emanare una specie di aura che gli altri insetti non hanno. Gli abbiamo dato un nome: ⟦Stinglasher=Sferzaculei⟧.\n\nLe interiora di questa bestia sarebbero preziosissime da studiare, mentre cerchiamo il modo migliore di affrontare questa nuova minaccia. Asportagli le ghiandole secretorie e portamele immediatamente!", "Sei riuscit<o/a> ad abbattere ⟦Stinglasher=Sferzaculei⟧?", "Notevole, {class}... davvero notevole! Se ⟦Stinglasher=Sferzaculei⟧ è davvero una delle loro creature più forti, lo studio di questa bestia si rivelerà assai prezioso col tempo. Ora il mio compito è assicurarmi che ci difendiamo abbastanza a lungo da poterne approfittare.\n\nTi prego, accetta questa taglia come segno di gratitudine da parte di tutto l'accampamento, {name}. Ben fatto.", 0x77138744, 0x4fd44652, 0x73c277a8, 0xb18b3f63, 0xe87d41a1, "....." },
  [7732] = { "Rapporto sugli Zukk'ash", "Consegna il ⟦Camp Mojache Zukk'ash Report=Rapporto di Zukk'ash sull'Accampamento Mojache⟧ a ⟦Zilzibin Drumlore=Zilzibin Suonapelli⟧. Risiede al Varcolargo, a Orgrimmar.", "Hai fatto doppiamente bene ad affrontare la minaccia che gli insetti Zukk'ash rappresentano per l'⟦Camp Mojache=Accampamento Mojache⟧. Il pericolo che costituiscono è tutt'altro che finito, e vorrei chiederti un ultimo compito per conto dell'⟦Horde=Orda⟧.\n\nQuesto documento riporta tutte le informazioni che abbiamo raccolto su questi insetti Zukk'ash. Voglio che tu lo consegni a ⟦Zilzibin Drumlore=Zilzibin Suonapelli⟧, al Varcolargo, a Orgrimmar. È un esperto di creature aliene come queste; spero che possa fare qualcosa con il sapere che abbiamo raccolto.", "Salute, amico... sembri avere una faccenda urgente. Posso aiutarti in qualche modo?", "Ah, me lo aspettavo. Queste creature che hai affrontato... sono un'antica minaccia che l'⟦Horde=Orda⟧ continua a scegliere di ignorare. Hadoken è stato saggio a portare questo, e te, da me.\n\nGli Zukk'ash non sono altro che creature chiamate silitidi. Alcuni penserebbero che siano solo un fastidio senza cervello, ma lascia che te lo assicuri: sono una minaccia molto, molto peggiore di qualsiasi cosa l'⟦Alliance=Alleanza⟧ possa mettere in campo.\n\nSe hai la volontà e la forza, il tuo aiuto mi farebbe comodo per portare alla luce questa minaccia.", 0x5199ec19, 0xdeed09ff, 0x58b47835, 0x78492e92, 0x2c9e366b, "....." },
  [7733] = { "Qualità superiore", "Porta 10 Rage Scar Yeti Hide a Pratt McGrubben alla Roccaforte di Piumaluna, a Feralas.", "Ho una pista per una fonte di pelli ancora MIGLIORE, se mai è possibile crederci! Nella parte settentrionale di Feralas, nel cuore della ⟦Rage Scar Hold=Tana degli Artiglio Selvaggio⟧, c'è un'altra orda di yeti. Sono molto più duri di quelli che hai affrontato prima, quindi se te la senti di affrontare una sfida più grande, faresti meglio a stare all'erta!\n\nTi ricompenserei generosamente per una pila di dieci delle loro pelli; portamele qui e concluderemo il nostro affare.", "Se queste pelli di yeti Artiglio Selvaggio sono anche solo della qualità di quelle dei loro simili di Valsfregiata, potrebbero essere resistenti quanto il torio!\n\nTi rendi conto?", "Ottimo, ottimo! Queste funzioneranno benissimo: già capisco che saranno molto più dure una volta conciate a dovere.\n\nGrazie ancora per il tuo aiuto, {name}. Ecco, prendi una delle mie ultime creazioni.", 0xa8bb365e, 0x57e69c4f, 0x69ee584c, 0xc4178ba9, 0xc3980197, "....." },
  [7734] = { "Qualità superiore", "Porta 10 Rage Scar Yeti Hide a ⟦Jangdor Swiftstrider=Jangdor Passo Lesto⟧ all'⟦Camp Mojache=Accampamento Mojache⟧, a Feralas.", "Ho una pista per una fonte di pelli ancora MIGLIORE, se mai è possibile crederci! Nella parte settentrionale di Feralas, nel cuore della ⟦Rage Scar Hold=Tana degli Artiglio Selvaggio⟧, c'è un'altra orda di yeti. Sono molto più duri di quelli che hai affrontato prima, quindi se te la senti di affrontare una sfida più grande, faresti meglio a stare all'erta!\n\nTi ricompenserei generosamente per una pila di dieci delle loro pelli; portamele qui e concluderemo il nostro affare.", "Se queste pelli di yeti Artiglio Selvaggio sono anche solo della qualità di quelle dei loro simili di Valsfregiata, potrebbero essere resistenti quanto il torio!\n\nTi rendi conto?", "Ottimo, ottimo! Queste funzioneranno benissimo: già capisco che saranno molto più dure una volta conciate a dovere.\n\nGrazie ancora per il tuo aiuto, {name}. Ecco, prendi una delle mie ultime creazioni.", 0xa8bb365e, 0x8a00501d, 0x69ee584c, 0xc4178ba9, 0xe3079241, "....." },
  [7761] = { "⟦Blackhand's Command=Lettera di Manonera⟧", "Che orco stupido. A quanto pare devi trovare questo marchio e ottenere il marchio di Drakkisath per poter accedere all'Orb of Command.\n\nLa lettera indica che è il generale Drakkisath a custodire il marchio. Forse dovresti indagare.", "Imbecille,\n\nho pochissima fiducia nella tua capacità di impedire agli estranei di accedere al covo del padrone. Nel caso, molto probabile, della tua morte, questo globo ha una sua protezione interna che impedisce agli estranei di teletrasportarsi direttamente nella Fortezza dell'⟦Blackwing=Ala Nera⟧.\n\nSolo chi porta il marchio di Drakkisath impresso a fuoco sulla mano può usare questo globo. Per fortuna Drakkisath non è neanche lontanamente incompetente quanto te, quartiermastro. È lui stesso a custodire il marchio!\n\n-Capoguerra Rend Manonera\n\nP.S. Distruggi questa lettera, idiota.", nil, "Non batti ciglio mentre il marchio rovente ti viene impresso nella carne. Sei proprio <un/una> dur<o/a>!\n\nOra porti il marchio di Drakkisath. Buon divertimento con l'assalto al castello.", 0xcc57347c, 0xe176a851, 0xb08323d4, nil, 0x4ec9e05c, "...m." },
  [7781] = { "Il signore di ⟦Blackrock=Roccianera⟧", "Porta la ⟦Head of Nefarian=Testa di Nefarian⟧ al gran signore Bolvar Domadraghi, a ⟦Stormwind=Roccavento⟧.", "La vecchia sensazione ritorna. Le gradite fitte della vittoria risuonano in tutto il tuo essere. Davanti a te giace la testa monolitica e segnata dalle battaglie di Nefarian. Portala al tuo gran signore, campione.", "Inconcepibile!", "Non c'è bisogno che ti si spieghi il significato di ciò che hai fatto, {name}. Questo giorno sarà ricordato negli annali della storia. Una vittoria come l'⟦Alliance=Alleanza⟧ non ne conosceva da anni, se mai ne ha conosciute!", 0xe644b2ee, 0x4e6be388, 0x5f4dbb3a, 0xfa030e66, 0xaa731d81, "....." },
  [7782] = { "Il signore di ⟦Blackrock=Roccianera⟧", "Raggiungi la ⟦Valley of Heroes=Valle degli Eroi⟧ a ⟦Stormwind City=Roccavento⟧ e parla con il primo maresciallo Stonebridge.", "Va' nella ⟦Valley of Heroes=Valle degli Eroi⟧ e parla con il primo maresciallo Stonebridge.", nil, "<Il primo maresciallo Afrasiabi si inchina.>\n\nScegli la tua ricompensa, e che la festa abbia inizio!", 0xe644b2ee, 0xf1b8542f, 0xc0f0a1f4, nil, 0x59a2c0b6, "...m." },
  [7783] = { "Il signore di ⟦Blackrock=Roccianera⟧", "Porta la ⟦Head of Nefarian=Testa di Nefarian⟧ a Thrall, a Orgrimmar.", "La vecchia sensazione ritorna. Le gradite fitte della vittoria risuonano in tutto il tuo essere. Davanti a te giace la testa monolitica e segnata dalle battaglie di Nefarian. Portala al tuo Capoguerra, campione.", "Vorrei esserci stato per vedere la faccia della bestia quando le hai inferto il colpo mortale, {name}.", "Hai onorato l'⟦Horde=Orda⟧ ancora una volta, {name}. Il figlio di Alamorte giace morto. Di certo il maligno si agita.", 0xe644b2ee, 0x9a97e711, 0x5f012492, 0x32e43d2d, 0xfadf38e5, "....." },
  [7784] = { "Il signore di ⟦Blackrock=Roccianera⟧", "Parla con il gran supremo Faucisaure a Orgrimmar. Ti aspetta nella ⟦Valley of Strength=Valle della Forza⟧.", "Cerca il gran supremo Faucisaure nella ⟦Valley of Strength=Valle della Forza⟧.", nil, "Scegli la tua ricompensa, così che io possa esporre la testa della bestia perché tutti la vedano.", 0xe644b2ee, 0x49c92018, 0x3e5a2c72, nil, 0x5ae91ac1, "...m." },
  [7785] = { "Esaminare il contenitore", "Esamina il ⟦Vessel of Rebirth=Contenitore della Rinascita⟧ e riportalo al gran signore Demitrian.", "Esamina il contenitore della sua rinascita, mortale. È da esso che il Ventoeterno rinascerà!", "Lo libererai dalla sua prigione eterna?", "Che tu sia protett<o/a> nella tua crociata. Che il Padrone benedica i tuoi sforzi.", 0x4d00c480, 0xa77a8d6f, 0xc797dde0, 0xd12827fa, 0x3e738341, "....." },
  [7786] = { "Thunderaan il Ventoeterno", "Per liberare Thunderaan il Ventoeterno dalla sua prigione, devi presentare al gran signore Demitrian, a ⟦Silithus=Silitus⟧, la metà destra e quella sinistra delle ⟦Bindings of the Windseeker=Manette del Ventoeterno⟧, 10 Elementium Bar e l'⟦Essence of the Firelord=Essenza del Signore del Fuoco⟧.", "Ti ho detto tutto ciò che so, {name}. Sei tu che devi trovare l'elementio. Sei tu che devi distruggere la forma corporea del Signore del Fuoco.\n\nFallo e otterrai la benedizione di Thunderaan.", "Metti in ginocchio il mondo, se devi!", "Neppure nei sogni osavo prevedere questo giorno.\n\nAmmira, mortale.\n\nAMMIRA COLUI CHE È PIÙ ANTICO DELL'ESISTENZA!\n\nAMMIRA COLUI CHE HA AFFRONTATO TITANI E DÈI!\n\nRISORGI, MIO PADRONE! SPEZZA LE TUE CATENE!", 0x30d08f81, 0x68665a74, 0xaaceb8e0, 0xb1d1afb9, 0x6900d53f, "....." },
  [7787] = { "Risorgi, Furiatonante!", "Presenta la ⟦Dormant Wind Kissed Blade=Lama Dormiente Benedetta dal Vento⟧ al gran signore Demitrian.", "Hai sconfitto il Ventoeterno. Prendi la lama dormiente e costringi quel miserabile bugiardo di Demitrian a usare i materiali che gli hai fornito per il suo tradimento per risvegliare Furiatonante.", "<Demitrian si rannicchia impaurito davanti a te.>", "Ti prego, non farmi del male! Prendila! Prendi la lama! Lascia che Demitrian ricostruisca la sua patetica vita!", 0xecb94e11, 0xe22ca07c, 0x3bc99176, 0x092cd967, 0xece60a9a, "....." },
  [7788] = { "Sconfiggi gli invasori!", "Entra nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e sconfiggi l'⟦Horde=Orda⟧, ottieni un ⟦Warsong Gulch Mark of Honor=Contrassegno d'Onore della Forra dei Cantaguerra⟧ e torna dalla sentinella Cantolungo al ⟦Silverwing Grove=Boschetto degli Alargentea⟧.", "Oltre questa galleria troverai un campo di lotta e tumulto, giovane {class}. L'⟦Horde=Orda⟧ continua a devastare la nostra foresta sacra, abbattendo i sempreverdi per alimentare le sue macchine da guerra.\n\nEntra nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e difendi la ⟦Silverwing Hold=Rocca di Alargentea⟧. Respingi le forze d'invasione dell'⟦Horde=Orda⟧!\n\nFallo, e otterrai un talismano al merito. Portami un tale talismano, {name}, e ti ricompenserò.", "Hai combattuto nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e difeso la ⟦Silverwing Hold=Rocca di Alargentea⟧?", "Hai dimostrato il tuo valore nei nostri sforzi nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧. Continua a sostenere la causa e portami altri contrassegni d'onore. Fallo, e ti guadagnerai ancora di più la nostra fiducia.", 0x55520e44, 0xfeb46d9a, 0xd5134582, 0x71ff749c, 0xf9915c4e, "....." },
  [7789] = { "Domare gli usurpatori Alargentea", "Entra nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e sconfiggi l'⟦Alliance=Alleanza⟧, ottieni un ⟦Warsong Gulch Mark of Honor=Contrassegno d'Onore della Forra dei Cantaguerra⟧ e portalo al capitano Spaccateschi all'⟦Mor'shan Base Camp=Accampamento Mor'shan⟧.", "Le terre selvagge della foresta di ⟦Ashenvale=Valtetra⟧ cederanno alla potenza dell'⟦Horde=Orda⟧, {race}. Nulla di ciò che gli Alargentea dicono o fanno può fermare il nostro imperativo sovrano. Kalimdor appartiene all'⟦Horde=Orda⟧. Come osano cercare di impedirci di raccogliere ciò che è nostro di diritto!\n\nLascia che l'orgoglio ti gonfi il petto mentre stronchi i loro deboli tentativi di rallentare la nostra avanzata. Distruggi le ⟦Silverwing Sentinels=Sentinelle Alargentea⟧ e ottieni un contrassegno d'onore dei ⟦Warsong=Cantaguerra⟧. Torna da me con un tale contrassegno, {name}, e sarai ricompensat<o/a>.", "Il sangue dei nostri nemici è un contrassegno d'onore. Ce l'hai un contrassegno del genere?", "<Il capitano Spaccateschi ruggisce in trionfo.>\n\nQuanto ancora possono resistere? Quanta altra feccia dell'⟦Alliance=Alleanza⟧ deve perire per mano dell'⟦Horde=Orda⟧ prima che si ritirino? Solo il tempo lo dirà, {race}...", 0x636625b4, 0xc94c2293, 0x2eb6ef0c, 0xd1cff4b7, 0x160777a5, "....." },
  [7791] = { "Una donazione di lana", nil, nil, "Al momento accettiamo donazioni di tessuto di lana. Una donazione di sessanta pezzi di tessuto di lana ti varrà la piena riconoscenza di ⟦Stormwind=Roccavento⟧ per il tuo gesto generoso. Le nostre scorte di lana sono tali che da te ci serviranno solo sessanta pezzi in tutto; dovremmo riuscire a procurarcene abbastanza da altri nel regno per sostenere la nostra raccolta.\n\nSe hai con te i sessanta pezzi di tessuto di lana e sei pront<o/a> a donarli, posso prenderli subito.", "Meraviglioso! Ti ringraziamo per la tua generosa donazione, {name}!", 0xaad71c6f, nil, nil, 0xbfdb39e9, 0xde0116d9, ".mm.." },
  [7792] = { "Una donazione di lana", nil, nil, "Al momento accettiamo donazioni di tessuto di lana. Una donazione di sessanta pezzi di tessuto di lana ti varrà la piena riconoscenza di Darnassus per il tuo gesto generoso. Le nostre scorte di lana sono tali che da te ci serviranno solo sessanta pezzi in tutto; dovremmo riuscire a procurarcene abbastanza da altri nel regno per sostenere la nostra raccolta.\n\nSe hai con te i sessanta pezzi di tessuto di lana e sei pront<o/a> a donarli, posso prenderli subito.", "Meraviglioso! Ti ringraziamo per la tua generosa donazione, {name}!", 0xaad71c6f, nil, nil, 0x30fa2bb9, 0xde0116d9, ".mm.." },
  [7793] = { "Una donazione di seta", nil, nil, "Come per la maggior parte degli altri tessuti, le nostre scorte di seta sono ai minimi storici. Le nostre riserve sono tali che da te ci servirebbero in tutto solo sessanta pezze di seta; dovremmo riuscire a raggiungere il nostro obiettivo con il sostegno degli altri.\n\nUn dono generoso come la seta, mi permetto di aggiungere, aumenterebbe di certo la tua reputazione nella comunità! Se hai con te le sessanta pezze di seta e sei <pronto/pronta> a donarle, posso prenderle subito.", "Meraviglioso! Ti ringraziamo per la tua generosa donazione, {name}!", 0xaa4c5243, nil, nil, 0x12099df5, 0xde0116d9, ".mm.." },
  [7794] = { "Una donazione di tessuto magico", nil, nil, "Il tessuto magico scarseggia, e il tuo aiuto ci farebbe comodo per rifornire le scorte! Contando sull'intera comunità, da te ci servirebbe solo una donazione di 60 pezze di tessuto magico per raggiungere il nostro obiettivo. Una simile generosità non passerebbe inosservata a ⟦Stormwind=Roccavento⟧, te lo assicuro!\n\nSe hai con te le sessanta pezze di tessuto magico e sei <pronto/pronta> a donarle, posso prenderle subito.", "Meraviglioso! Ti ringraziamo per la tua generosa donazione, {name}!", 0x2c4ad0c3, nil, nil, 0x1ff8b690, 0xde0116d9, ".mm.." },
  [7795] = { "Una donazione di telarunica", nil, nil, "{name}, hai contribuito moltissimo alla nostra raccolta di stoffa. Mentre lavoriamo sodo per ricostituire le nostre riserve, un tipo di stoffa resta scarsissimo: la telarunica. Ne abbiamo un bisogno disperato e speriamo che tu possa aiutarci come hai fatto in passato!\n\nSe sei dispost<o/a>, portami tutta la telarunica di cui puoi fare a meno. Per cominciare accetteremo una singola donazione di sessanta pezze, poi vedremo.", "Fantastico: le useremo subito, te lo assicuro. Grazie ancora per il tuo aiuto! Senza di te saremmo davvero perduti.\n\nCon tutte le donazioni che hai fatto, accetterò senz'altro qualsiasi altra donazione di telarunica vorrai fare in futuro. Passa pure da me, e mi assicurerò personalmente che le tue buone azioni non passino inosservate!", 0xaf5b02b1, nil, nil, 0x56be67b9, 0x690ecdf1, ".mm.." },
  [7798] = { "Una donazione di seta", nil, nil, "Come per la maggior parte degli altri tessuti, le nostre scorte di seta sono ai minimi storici. Le nostre riserve sono tali che da te ci servirebbero in tutto solo sessanta pezze di seta; dovremmo riuscire a raggiungere il nostro obiettivo con il sostegno degli altri.\n\nUn dono generoso come la seta, mi permetto di aggiungere, aumenterebbe di certo la tua reputazione nella comunità! Se hai con te le sessanta pezze di seta e sei <pronto/pronta> a donarle, posso prenderle subito.", "Meraviglioso! Ti ringraziamo per la tua generosa donazione, {name}!", 0xaa4c5243, nil, nil, 0x12099df5, 0xde0116d9, ".mm.." },
  [7799] = { "Una donazione di tessuto magico", nil, nil, "Il tessuto magico scarseggia, e il tuo aiuto ci farebbe comodo per rifornire le scorte! Contando sull'intera comunità, da te ci servirebbe solo una donazione di 60 pezze di tessuto magico per raggiungere il nostro obiettivo. Una simile generosità non passerebbe inosservata a Darnassus, te lo assicuro!\n\nSe hai con te le sessanta pezze di tessuto magico e sei <pronto/pronta> a donarle, posso prenderle subito.", "Meraviglioso! Ti ringraziamo per la tua generosa donazione, {name}!", 0x2c4ad0c3, nil, nil, 0x4ff1246f, 0xde0116d9, ".mm.." },
  [7800] = { "Una donazione di telarunica", nil, nil, "{name}, hai contribuito moltissimo alla nostra raccolta di stoffa. Mentre lavoriamo sodo per ricostituire le nostre riserve, un tipo di stoffa resta scarsissimo: la telarunica. Ne abbiamo un bisogno disperato e speriamo che tu possa aiutarci come hai fatto in passato!\n\nSe sei dispost<o/a>, portami tutta la telarunica di cui puoi fare a meno. Per cominciare accetteremo una singola donazione di sessanta pezze, poi vedremo.", "Fantastico: le useremo subito, te lo assicuro. Grazie ancora per il tuo aiuto! Senza di te saremmo davvero perduti.\n\nCon tutte le donazioni che hai fatto, accetterò senz'altro qualsiasi altra donazione di telarunica vorrai fare in futuro. Passa pure da me, e mi assicurerò personalmente che le tue buone azioni non passino inosservate!", 0xaf5b02b1, nil, nil, 0x56be67b9, 0x690ecdf1, ".mm.." },
  [7802] = { "Una donazione di lana", nil, nil, "Al momento accettiamo donazioni di lana. Una donazione di sessanta pezze di lana ti varrà il pieno riconoscimento di ⟦Ironforge=Forgiardente⟧ per la tua generosità. Le nostre riserve di lana sono tali che da te ci servirebbero in tutto solo sessanta pezze; dovremmo riuscire a procurarcene abbastanza dagli altri del reame per sostenere la nostra raccolta.\n\nSe hai con te le sessanta pezze di lana e sei <pronto/pronta> a donarle, posso prenderle subito.", "Meraviglioso! Ti ringraziamo per la tua generosa donazione, {name}!", 0xaad71c6f, nil, nil, 0x545b4699, 0xde0116d9, ".mm.." },
