  [7809] = { "Una donazione di tessuto magico", nil, nil, "Il tessuto magico scarseggia, e il tuo aiuto ci farebbe comodo per rifornire le scorte! Contando sull'intera comunità, da te ci servirebbe solo una donazione di 60 pezze di tessuto magico per raggiungere il nostro obiettivo. Una simile generosità non passerebbe inosservata agli gnomi di Gnomeregan, te lo assicuro!\n\nSe hai con te le sessanta pezze di tessuto magico e sei <pronto/pronta> a donarle, posso prenderle subito.", "Meraviglioso! Ti ringraziamo per la tua generosa donazione, {name}!", 0x2c4ad0c3, nil, nil, 0xede73412, 0xde0116d9, ".mm.." },
  [7810] = { "⟦Arena Master=Maestro delle Arene⟧", "Parla con Short John Mithril all'arena di Rovotorto.", "Per essere maestro dell'arena ci dev'essere qualcosa di più! Forse il pirata che organizza l'evento a Gurubashi lo saprà!", nil, "Arr, compare! Guadagnare un solo ninnolo non basta a fare di te un maestro dell'Arena! Ora è il momento di dimostrare davvero quanto vali.", 0x11d885c3, 0x6414b72c, 0x84414394, nil, 0x05fdd5a7, "...m." },
  [7811] = { "Una donazione di telarunica", nil, nil, "{name}, hai contribuito moltissimo alla nostra raccolta di stoffa. Mentre lavoriamo sodo per ricostituire le nostre riserve, un tipo di stoffa resta scarsissimo: la telarunica. Ne abbiamo un bisogno disperato e speriamo che tu possa aiutarci come hai fatto in passato!\n\nSe sei dispost<o/a>, portami tutta la telarunica di cui puoi fare a meno. Per cominciare accetteremo una singola donazione di sessanta pezze, poi vedremo.", "Fantastico: le useremo subito, te lo assicuro. Grazie ancora per il tuo aiuto! Senza di te saremmo davvero perduti.\n\nCon tutte le donazioni che hai fatto, accetterò senz'altro qualsiasi altra donazione di telarunica vorrai fare in futuro. Passa pure da me, e mi assicurerò personalmente che le tue buone azioni non passino inosservate!", 0xaf5b02b1, nil, nil, 0x56be67b9, 0x690ecdf1, ".mm.." },
  [7813] = { "Una donazione di lana", nil, nil, "Al momento accettiamo donazioni di tessuto di lana. Una donazione di sessanta pezzi di tessuto di lana ti varrà la piena riconoscenza di ⟦Undercity=Sepulcra⟧ per il tuo gesto generoso. Le nostre scorte di lana sono tali che da te ci serviranno solo sessanta pezzi in tutto; dovremmo riuscire a procurarcene abbastanza da altri nel regno per sostenere la nostra raccolta.\n\nSe hai con te i sessanta pezzi di tessuto di lana e sei pront<o/a> a donarli, posso prenderli subito.", "Meraviglioso! Ti ringraziamo per la tua generosa donazione, {name}!", 0xaad71c6f, nil, nil, 0xe379f051, 0xde0116d9, ".mm.." },
  [7814] = { "Una donazione di seta", nil, nil, "Come per la maggior parte degli altri tessuti, le nostre scorte di seta sono ai minimi storici. Le nostre riserve sono tali che da te ci servirebbero in tutto solo sessanta pezze di seta; dovremmo riuscire a raggiungere il nostro obiettivo con il sostegno degli altri.\n\nUn dono generoso come la seta, mi permetto di aggiungere, aumenterebbe di certo la tua reputazione nella comunità! Se hai con te le sessanta pezze di seta e sei <pronto/pronta> a donarle, posso prenderle subito.", "Meraviglioso! Ti ringraziamo per la tua generosa donazione, {name}!", 0xaa4c5243, nil, nil, 0x12099df5, 0xde0116d9, ".mm.." },
  [7815] = { "Snapjaw, amico!", "⟦Katoom the Angler=Katoom il Pescatore⟧, al ⟦Revantusk Village=Villaggio degli Zannatorta⟧ nelle Entroterre, vuole che tu uccida 15 tartarughe ⟦Saltwater Snapjaw=Tartarabbia d'Acqua Salata⟧. Torna da lui quando avrai finito.", "Non farti ingannare da quei loro occhioni, amico! Quelle saltwater snapjaw sono una piaga. Non riesco a pescare per cinque minuti senza che una di quelle aspirapesci troppo cresciute mi rompa la lenza per rubarmi l'esca.\n\nFa' un favore a me e alla gente del ⟦Revantusk Village=Villaggio degli Zannatorta⟧ e uccidile, amico.\n\nUccidile tutte quante!", "Come va la caccia?", "Oh, amico! Non so come ringraziarti! Spero che questa canna da pesca sia una ricompensa sufficiente per il lavoro.", 0x72ef90bb, 0xc3d80d58, 0x23ca4b5f, 0xe02b27bb, 0xeb85de83, "....." },
  [7816] = { "Gammerita, fratello!", "⟦Katoom the Angler=Katoom il Pescatore⟧, al ⟦Revantusk Village=Villaggio degli Zannatorta⟧ nelle Entroterre, vuole che tu uccida Gammerita e recuperi l'⟦Katoom's Best Lure=Esca Migliore di Katoom⟧ dal suo cadavere.\n\nKatoom ha detto che Gammerita se ne sta sulla costa con le altre tartarughe.", "Ehi! Là fuori c'è una tartaruga non come le altre. È la Gammerita, la capa delle tartarabbie d'acqua salata: un rettile sporco e ladro fino al midollo.\n\nFratello, mi ha rubato l'esca migliore. Me l'ha strappata dalla lenza con un morso! Da allora i pesci non abboccano più come prima.\n\nTrova Gammerita e tirale fuori dalla pancia la mia esca.", "L'hai già presa?", "FRATELLO! È fantastico! Con la mia esca migliore e meno tartarabbie in giro, i pesci si ammucchieranno.", 0x9c277548, 0x252df688, 0x06cdd3ff, 0xc71c2f35, 0xa433f742, "....." },
  [7817] = { "Una donazione di tessuto magico", nil, nil, "Il tessuto magico scarseggia, e il tuo aiuto ci farebbe comodo per rifornire le scorte! Contando sull'intera comunità, da te ci servirebbe solo una donazione di 60 pezze di tessuto magico per raggiungere il nostro obiettivo. Una simile generosità non passerebbe inosservata a ⟦Undercity=Sepulcra⟧, te lo assicuro!\n\nSe hai con te le sessanta pezze di tessuto magico e sei <pronto/pronta> a donarle, posso prenderle subito.", "Meraviglioso! Ti ringraziamo per la tua generosa donazione, {name}!", 0x2c4ad0c3, nil, nil, 0x2ef75b92, 0xde0116d9, ".mm.." },
  [7818] = { "Una donazione di telarunica", nil, nil, "{name}, hai contribuito moltissimo alla nostra raccolta di stoffa. Mentre lavoriamo sodo per ricostituire le nostre riserve, un tipo di stoffa resta scarsissimo: la telarunica. Ne abbiamo un bisogno disperato e speriamo che tu possa aiutarci come hai fatto in passato!\n\nSe sei dispost<o/a>, portami tutta la telarunica di cui puoi fare a meno. Per cominciare accetteremo una singola donazione di sessanta pezze, poi vedremo.", "Fantastico: le useremo subito, te lo assicuro. Grazie ancora per il tuo aiuto! Senza di te saremmo davvero perduti.\n\nCon tutte le donazioni che hai fatto, accetterò senz'altro qualsiasi altra donazione di telarunica vorrai fare in futuro. Passa pure da me, e mi assicurerò personalmente che le tue buone azioni non passino inosservate!", 0xaf5b02b1, nil, nil, 0x56be67b9, 0x690ecdf1, ".mm.." },
  [7820] = { "Una donazione di lana", nil, nil, "Al momento accettiamo donazioni di tessuto di lana. Una donazione di sessanta pezzi di tessuto di lana ti varrà la piena riconoscenza di ⟦Thunder Bluff=Picco del Tuono⟧ per il tuo gesto generoso. Le nostre scorte di lana sono tali che da te ci serviranno solo sessanta pezzi in tutto; dovremmo riuscire a procurarcene abbastanza da altri nel regno per sostenere la nostra raccolta.\n\nSe hai con te i sessanta pezzi di tessuto di lana e sei pront<o/a> a donarli, posso prenderli subito.", "Meraviglioso! Ti ringraziamo per la tua generosa donazione, {name}!", 0xaad71c6f, nil, nil, 0x353f309a, 0xde0116d9, ".mm.." },
  [7821] = { "Una donazione di seta", nil, nil, "Come per la maggior parte degli altri tessuti, le nostre scorte di seta sono ai minimi storici. Le nostre riserve sono tali che da te ci servirebbero in tutto solo sessanta pezze di seta; dovremmo riuscire a raggiungere il nostro obiettivo con il sostegno degli altri.\n\nUn dono generoso come la seta, mi permetto di aggiungere, aumenterebbe di certo la tua reputazione nella comunità! Se hai con te le sessanta pezze di seta e sei <pronto/pronta> a donarle, posso prenderle subito.", "Meraviglioso! Ti ringraziamo per la tua generosa donazione, {name}!", 0xaa4c5243, nil, nil, 0x12099df5, 0xde0116d9, ".mm.." },
  [7822] = { "Una donazione di tessuto magico", nil, nil, "Il tessuto magico scarseggia, e il tuo aiuto ci farebbe comodo per rifornire le scorte! Contando sull'intera comunità, da te ci servirebbe solo una donazione di 60 pezze di tessuto magico per raggiungere il nostro obiettivo. Una simile generosità non passerebbe inosservata a ⟦Thunder Bluff=Picco del Tuono⟧, te lo assicuro!\n\nSe hai con te le sessanta pezze di tessuto magico e sei <pronto/pronta> a donarle, posso prenderle subito.", "Meraviglioso! Ti ringraziamo per la tua generosa donazione, {name}!", 0x2c4ad0c3, nil, nil, 0x666fdc38, 0xde0116d9, ".mm.." },
  [7823] = { "Una donazione di telarunica", nil, nil, "{name}, hai contribuito moltissimo alla nostra raccolta di stoffa. Mentre lavoriamo sodo per ricostituire le nostre riserve, un tipo di stoffa resta scarsissimo: la telarunica. Ne abbiamo un bisogno disperato e speriamo che tu possa aiutarci come hai fatto in passato!\n\nSe sei dispost<o/a>, portami tutta la telarunica di cui puoi fare a meno. Per cominciare accetteremo una singola donazione di sessanta pezze, poi vedremo.", "Fantastico: le useremo subito, te lo assicuro. Grazie ancora per il tuo aiuto! Senza di te saremmo davvero perduti.\n\nCon tutte le donazioni che hai fatto, accetterò senz'altro qualsiasi altra donazione di telarunica vorrai fare in futuro. Passa pure da me, e mi assicurerò personalmente che le tue buone azioni non passino inosservate!", 0xaf5b02b1, nil, nil, 0x56be67b9, 0x690ecdf1, ".mm.." },
  [7824] = { "Una donazione di telarunica", nil, nil, "{name}, hai contribuito moltissimo alla nostra raccolta di stoffa. Mentre lavoriamo sodo per ricostituire le nostre riserve, un tipo di stoffa resta scarsissimo: la telarunica. Ne abbiamo un bisogno disperato e speriamo che tu possa aiutarci come hai fatto in passato!\n\nSe sei dispost<o/a>, portami tutta la telarunica di cui puoi fare a meno. Per cominciare accetteremo una singola donazione di sessanta pezze, poi vedremo.", "Fantastico: le useremo subito, te lo assicuro. Grazie ancora per il tuo aiuto! Senza di te saremmo davvero perduti.\n\nCon tutte le donazioni che hai fatto, accetterò senz'altro qualsiasi altra donazione di telarunica vorrai fare in futuro. Passa pure da me, e mi assicurerò personalmente che le tue buone azioni non passino inosservate!", 0xaf5b02b1, nil, nil, 0x56be67b9, 0x690ecdf1, ".mm.." },
  [7826] = { "Una donazione di lana", nil, nil, "Al momento accettiamo donazioni di tessuto di lana. Una donazione di sessanta pezzi di tessuto di lana ti varrà la piena riconoscenza di Orgrimmar per il tuo gesto generoso. Le nostre scorte di lana sono tali che da te ci serviranno solo sessanta pezzi in tutto; dovremmo riuscire a procurarcene abbastanza da altri nel regno per sostenere la nostra raccolta.\n\nSe hai con te i sessanta pezzi di tessuto di lana e sei pront<o/a> a donarli, posso prenderli subito.", "Meraviglioso! Ti ringraziamo per la tua generosa donazione, {name}!", 0xaad71c6f, nil, nil, 0x41064cf9, 0xde0116d9, ".mm.." },
  [7827] = { "Una donazione di seta", nil, nil, "Come per la maggior parte degli altri tessuti, le nostre scorte di seta sono ai minimi storici. Le nostre riserve sono tali che da te ci servirebbero in tutto solo sessanta pezze di seta; dovremmo riuscire a raggiungere il nostro obiettivo con il sostegno degli altri.\n\nUn dono generoso come la seta, mi permetto di aggiungere, aumenterebbe di certo la tua reputazione nella comunità! Se hai con te le sessanta pezze di seta e sei <pronto/pronta> a donarle, posso prenderle subito.", "Meraviglioso! Ti ringraziamo per la tua generosa donazione, {name}!", 0xaa4c5243, nil, nil, 0x12099df5, 0xde0116d9, ".mm.." },
  [7828] = { "Braccare chi bracca", "Il predatore Markhor, al ⟦Revantusk Village=Villaggio degli Zannatorta⟧ nelle Entroterre, vuole che tu uccida 15 Silvermane Stalker e 15 Silvermane Howler. Torna da lui quando avrai finito.\n\nMarkhor ha detto che i lupi si nascondono nelle terre selvagge delle Entroterre.", "Molti troll coraggiosi sono caduti nelle aspre terre selvagge delle Entroterre, {race}. I lupi Peloargento sono una delle minacce più grandi per i nostri cacciatori. Stanno in agguato, nascosti tra i cespugli e le asperità del terreno, poi colpiscono quando si presenta l'occasione.\n\nUna simile ferocia non resterà impunita!\n\nDevi pensare come i Peloargento. Bracca chi bracca! Uccidili tutti!", "Mostra loro la potenza degli Zannatorta!", "Ottimo lavoro, {race}. Gli Zannatorta ti ringraziano per il tuo contributo.", 0x063c937f, 0xb11333a2, 0x051d8cfb, 0x986ad0fe, 0xbc3130c6, "....." },
  [7829] = { "Caccia ai selvaggi", "Il predatore Markhor, al ⟦Revantusk Village=Villaggio degli Zannatorta⟧ nelle Entroterre, vuole che tu uccida 20 Savage Owlbeast. Torna da lui quando avrai finito.\n\nMarkhor ha detto che i Savage Owlbeast popolano le terre selvagge delle Entroterre.", "Tra le creature più rabbiose delle Entroterre ci sono i silvagufi selvaggi. Molti valorosi guerrieri Zannatorta sono caduti sotto gli artigli e il becco feroci di queste bestie.\n\nUccidi ogni silvagufo selvaggio che vedi, {race}. Torna da me quando non sopporterai più il sangue versato. Il tuo contributo sarà allora pesato, misurato e giudicato.", "Libera la mente dai pensieri impuri, {race}. Diventa tutt'uno con le terre selvagge!", "Hai dato prova di grande valore come <alleato/alleata> degli Zannatorta, {name}. Ben fatto.", 0xca9f3990, 0x39958eb7, 0x747f80cd, 0x80ded397, 0x9aec2025, "....." },
  [7830] = { "Vendicare i caduti", "Il predatore Markhor, al ⟦Revantusk Village=Villaggio degli Zannatorta⟧ nelle Entroterre, vuole che tu uccida un ⟦Razorbeak Skylord=Signore dei Cieli Beccolesto⟧ e ne recuperi la ⟦Skylord Plume=Piuma del Signore dei Cieli⟧. Torna da lui quando avrai finito.\n\nMarkhor ha detto che i ⟦Razorbeak Skylord=Signore dei Cieli Beccolesto⟧ sono una razza rara che tende a popolare le terre selvagge delle Entroterre.", "La feccia che si fa chiamare Granmartello addestra grifoni per uccidere troll. Orribile, lo so, ma non temere: presto sarà fatta giustizia.\n\nPer ora voglio che ti concentri sullo sterminio dei grifoni anziani della regione. Sono noti come Signori dei Cieli.\n\nUccidine uno e torna da me con la sua piuma.", "Il ⟦Razorbeak Skylord=Signore dei Cieli Beccolesto⟧ è una razza di grifone molto più rara: è quella che si accoppia e genera una prole assassina.", "<Markhor esamina la piuma.>\n\nMi chiedo quanti dei nostri cacciatori abbia divorato questa bestia prima che tu le facessi giustizia.", 0x5ef1ecc1, 0x5ca1b7a7, 0x788c3b3f, 0xd99d6388, 0xdbdd207c, "....." },
  [7831] = { "Una donazione di tessuto magico", nil, nil, "Il tessuto magico scarseggia, e il tuo aiuto ci farebbe comodo per rifornire le scorte! Contando sull'intera comunità, da te ci servirebbe solo una donazione di 60 pezze di tessuto magico per raggiungere il nostro obiettivo. Una simile generosità non passerebbe inosservata a Orgrimmar, te lo assicuro!\n\nSe hai con te le sessanta pezze di tessuto magico e sei <pronto/pronta> a donarle, posso prenderle subito.", "Meraviglioso! Ti ringraziamo per la tua generosa donazione, {name}!", 0x2c4ad0c3, nil, nil, 0x5a58b6f5, 0xde0116d9, ".mm.." },
  [7833] = { "Una donazione di lana", nil, nil, "Al momento accettiamo donazioni di tessuto di lana. Una donazione di sessanta pezzi di tessuto di lana ti varrà la piena riconoscenza dei ⟦Darkspear Trolls=Troll Lanciascura⟧ per il tuo gesto generoso. Le nostre scorte di lana sono tali che da te ci serviranno solo sessanta pezzi in tutto; dovremmo riuscire a procurarcene abbastanza da altri nel regno per sostenere la nostra raccolta.\n\nSe hai con te i sessanta pezzi di tessuto di lana e sei pront<o/a> a donarli, posso prenderli subito.", "Meraviglioso! Ti ringraziamo per la tua generosa donazione, {name}!", 0xaad71c6f, nil, nil, 0x9710ca9f, 0xde0116d9, ".mm.." },
  [7834] = { "Una donazione di seta", nil, nil, "Come per la maggior parte degli altri tessuti, le nostre scorte di seta sono ai minimi storici. Le nostre riserve sono tali che da te ci servirebbero in tutto solo sessanta pezze di seta; dovremmo riuscire a raggiungere il nostro obiettivo con il sostegno degli altri.\n\nUn dono generoso come la seta, mi permetto di aggiungere, aumenterebbe di certo la tua reputazione nella comunità! Se hai con te le sessanta pezze di seta e sei <pronto/pronta> a donarle, posso prenderle subito.", "Meraviglioso! Ti ringraziamo per la tua generosa donazione, {name}!", 0xaa4c5243, nil, nil, 0x12099df5, 0xde0116d9, ".mm.." },
  [7835] = { "Una donazione di tessuto magico", nil, nil, "Il tessuto magico scarseggia, e il tuo aiuto ci farebbe comodo per rifornire le scorte! Contando sull'intera comunità, da te ci servirebbe solo una donazione di 60 pezze di tessuto magico per raggiungere il nostro obiettivo. Una simile generosità non passerebbe inosservata ai ⟦Darkspear Trolls=Troll Lanciascura⟧, te lo assicuro!\n\nSe hai con te le sessanta pezze di tessuto magico e sei <pronto/pronta> a donarle, posso prenderle subito.", "Meraviglioso! Ti ringraziamo per la tua generosa donazione, {name}!", 0x2c4ad0c3, nil, nil, 0x6456e4ce, 0xde0116d9, ".mm.." },
  [7836] = { "Una donazione di telarunica", nil, nil, "{name}, hai contribuito moltissimo alla nostra raccolta di stoffa. Mentre lavoriamo sodo per ricostituire le nostre riserve, un tipo di stoffa resta scarsissimo: la telarunica. Ne abbiamo un bisogno disperato e speriamo che tu possa aiutarci come hai fatto in passato!\n\nSe sei dispost<o/a>, portami tutta la telarunica di cui puoi fare a meno. Per cominciare accetteremo una singola donazione di sessanta pezze, poi vedremo.", "Fantastico: le useremo subito, te lo assicuro. Grazie ancora per il tuo aiuto! Senza di te saremmo davvero perduti.\n\nCon tutte le donazioni che hai fatto, accetterò senz'altro qualsiasi altra donazione di telarunica vorrai fare in futuro. Passa pure da me, e mi assicurerò personalmente che le tue buone azioni non passino inosservate!", 0xaf5b02b1, nil, nil, 0x56be67b9, 0x690ecdf1, ".mm.." },
  [7838] = { "Gran Maestro delle Arene", nil, nil, "Ehi, marinaio d'acqua dolce! Portami 12 ninnoli del ⟦Arena Master=Maestro delle Arene⟧ e sarai Gran Maestro dell'⟦Gurubashi Arena=Arena dei Gurubashi⟧! Arrrr!", "Molto sangue hai versato sul suolo dell'Arena e sono lieto di nominarti Gran Maestro dell'Arena!", 0x4f711b14, nil, nil, 0x6158db91, 0x3d41dfd2, ".mm.." },
  [7839] = { "Teppisti Ramovile", "Il fabbro Slagtree, al ⟦Revantusk Village=Villaggio degli Zannatorta⟧ nelle Entroterre, vuole che tu trovi gli ⟦Slagtree's Lost Tools=Utensili Dispersi di Selvarotta⟧. Torna da lui quando avrai finito.\n\nTi ricordi che il fabbro Slagtree ha detto che gli utensili potrebbero trovarsi in uno dei templi dei Ramovile, nella parte nordorientale delle Entroterre. Dovresti controllare anche il ⟦Skulk Rock=Tumulo Strisciante⟧.", "La feccia Ramovile ha invaso il nostro villaggio e mi ha rubato gli utensili! Ne ho di riserva, ma quelli che hanno rubato erano un regalo di uno gnomo di buon cuore che mi salvò la vita quando ero un giovane orco.\n\nRivoglio quegli utensili, {name}: per me valgono più di ogni cosa.\n\nMarkhor ha riferito che gli utensili sono stati avvistati vicino ai templi di Agol'watha e Shaol'watha.\n\nQuei templi si trovano nella parte nordorientale delle Entroterre.\n\nRecupera i miei utensili!", "Fai attenzione ai troll Ramovile della regione, {name}. Sono feccia spietata e assassina.", "I miei utensili! Li hai trovati! Oh, giorno glorioso! Grazie, {name}.", 0x5825c8b8, 0x2b4fd09d, 0xe8e1d7b7, 0x6a874ab3, 0x0a05d5c7, "....." },
  [7840] = { "Lard ha perso il pranzo", "Lard, al ⟦Revantusk Village=Villaggio degli Zannatorta⟧ nelle Entroterre, vuole che tu trovi il ⟦Lard's Lunch=Pranzo di Lard⟧. Torna da lui quando avrai finito.\n\nLard ha detto di averlo lasciato sull'isola a nord. Fai attenzione ai troll Ramovile.", "Lard era in posto speciale segreto a fare picnic quando brutto cattivo Ramovile colpire Lard con grosso bastone. Lard scappare a Zannatorta ma dimenticare pranzo di Lard. Lard affamato. Forse tu tornare a posto speciale segreto e prendere pranzo di Lard? Lard avere paura. Andare a nord! Isola là a nord essere posto speciale segreto.", "<Lard si strofina l'enorme pancia.>\n\nLard tanto affamato.", "<Lard ti prende l'enorme cosciotto di carne e se lo ficca in bocca.>\n\nQuesto proprio ci voleva! Grazie, piccol<o/a>.\n\nLard fare per te cestino da picnic speciale perché tu aiutare Lard.", 0x256cde3b, 0x5b3b92b6, 0xaa8d0d9c, 0x4a1e7aea, 0x00b5e11f, "....." },
  [7841] = { "Messaggio per i Granmartello", "Otho Moji'ko, al ⟦Revantusk Village=Villaggio degli Zannatorta⟧ nelle Entroterre, vuole che tu massacri 15 Highvale Outrunner, 15 Highvale Scout, 15 ⟦Highvale Marksman=Tiratore degli Altavalle⟧ e 15 Highvale Ranger. Torna da lui quando avrai finito.\n\nTroverai gli alti elfi Highvale al ⟦Quel'Danil Lodge=Padiglione Quel'Danil⟧, nella parte nordoccidentale delle Entroterre.", "I Granmartello stanno facendo patti con i nostri nemici, stringendo nuove alleanze. Stavolta lavorano con gli alti elfi, amico.\n\n<Otho sputa.>\n\nDobbiamo mandare un messaggio a quei nani Granmartello: un messaggio scritto col sangue dei nostri nemici. Massacra ogni alto elfo Highvale che incontri, lascia i loro corpi come avvertimento.\n\nMai mettersi contro i troll!", "Sei troppo pulit<o/a>, amico. Devi buttarti nella mischia, sporcarti le mani col nemico.", "Pare che anche gli Zannatorta stiano stringendo nuove alleanze, amico! Hai fatto un buon lavoro.", 0x3400f01f, 0x9d1d6ff9, 0xfd82aa73, 0x483e5cc9, 0xa37f5eca, "....." },
  [7842] = { "Un altro messaggio per i Granmartello", "Otho Moji'ko, al ⟦Revantusk Village=Villaggio degli Zannatorta⟧ nelle Entroterre, vuole che tu gli porti 10 Piuma Lunga Elegante dei grifoni che abitano le Entroterre. Torna da lui quando avrai finito.\n\nI grifoni abitano ogni regione delle Entroterre.", "Dicono che i Granmartello e i grifoni siano legati come un troll e la sua compagna. Disgustoso, ma possiamo sfruttarlo a nostro vantaggio, amico. Gli mandiamo un altro messaggio.\n\nUccidi tutti i grifoni che vedi nelle Entroterre, raccogli le loro piume. Con quelle faremo il messaggio finale.", "L'ultimo messaggio li spaventerà di sicuro. O così, o li farà arrabbiare tanto, ma tanto.", "Oh, amico, questo sarà bello. Manca solo un passo, e i Granmartello capiranno che con i troll non si scherza!", 0xe4c3c6c1, 0xf001e473, 0x9f7d757e, 0x018beef7, 0x2ca2a2eb, "....." },
  [7843] = { "L'⟦Final Message to the Wildhammer=Ultimo Messaggio per i Granmartello⟧", "Otho Moji'ko, al ⟦Revantusk Village=Villaggio degli Zannatorta⟧ nelle Entroterre, vuole che tu vada al ⟦Aerie Peak=Picco dell'Aquila⟧, nella regione occidentale delle Entroterre, e lasci l'⟦Final Message to the Wildhammer=Ultimo Messaggio per i Granmartello⟧ vicino al pozzo al centro del paese. Torna da lui quando avrai finito.\n\nFai attenzione ai nani Granmartello infuriati e ai membri turbolenti dell'⟦Alliance=Alleanza⟧.", "<Otho ti porge una lunga lancia intrisa di sangue, avvolta in diverse piume di grifone.>\n\nPrendi questa, amico. Portala al ⟦Aerie Peak=Picco dell'Aquila⟧, proprio al centro del paese, vicino al pozzo. Piantala! Conficcala dritta nel terreno! Fai vedere a quei nani che i troll fanno sul serio! Torna quando hai fatto. Speriamo che torni con la pelle ancora addosso.", "Che aspetti, amico?", "Avrei voluto esserci per vedere le loro facce, amico. Stanno facendo i bagagli? Se ne vanno dal paese?\n\nHai fatto un buon lavoro, {name}. Davvero buono. Otho ti ricompensa con il grande mojo.", 0x01e2c01f, 0xba87e29b, 0x1a5a1d70, 0x99108aa7, 0xf1c2400a, "....." },
  [7844] = { "Cugini cannibali", "La mistica Yayo'jin, al ⟦Revantusk Village=Villaggio degli Zannatorta⟧ nelle Entroterre, vuole che tu uccida 30 Vilebranch Scalper e 15 Vilebranch Soothsayer. Torna da lei quando avrai finito.\n\nYayo'jin ha indicato che questi troll si trovano vicino ai templi di Shaol'watha e Agol'watha, nella parte nord-nordest delle Entroterre.", "Nelle Entroterre vivono tre diverse tribù di troll, {name}. Le somiglianze tra queste tribù si fermano più o meno qui: siamo tutti troll e viviamo nelle Entroterre.\n\nI Ramovile, che portano un nome quanto mai azzeccato, sono un branco di depravati: si nutrono di altri troll e di umanoidi.\n\nSe Zul'jin fosse qui, li avrebbe distrutti tutti con un colpo di polso. Ahimè, Zul'jin non è ancora tornato e dobbiamo cavarcela da soli.\n\nSta a te distruggere la feccia della regione!", "Gli indovini e gli scotennatori Ramovile popolano la parte nord-nordest delle Entroterre.", "Ben fatto, {class}. Neanche Zul'jin in persona avrebbe potuto fare di meglio!", 0x5088e132, 0x124998ac, 0x301da138, 0x17524ece, 0x215168e0, "....." },
  [7845] = { "L'anziano Zannaculea rapito!", "La primalista Zannaculea, al Villaggio degli Zannatorta nelle Entroterre, vuole che tu salvi il suo compagno, l'anziano Zannaculea, da Jintha'alor.\n\nTi hanno detto che è tenuto prigioniero in cima a Jintha'alor, la capitale dei Ramovile, nella parte meridionale delle Entroterre.", "Il mio compagno è stato rapito dai selvaggi Ramovile durante un'audace incursione notturna nel nostro villaggio. Le nostre spie mi hanno riferito che è ancora vivo, tenuto prigioniero in cima a Jintha'alor. Si dice che la sacerdotessa immonda Hexx lo stia preparando per sacrificarlo al Dio del Sangue senza volto, Hakkar.\n\nDevi salvarlo, {name}! Il nostro villaggio non potrebbe sopportare una perdita così grande.", nil, "Devi agire in fretta, {name}. Di sicuro le guardie sono state avvertite della tua presenza.", 0x944b13ad, 0x89e032b7, 0x585bc8ce, nil, 0xf4c9a135, "...m." },
  [7846] = { "Recupera la chiave!", "L'anziano Zannaculea, a Jintha'alor, vuole che tu uccida ⟦Hitah'ya the Keeper=Hitah'ya la Custode⟧ per avere la ⟦Shackle Key=Chiave delle Catene⟧ che lo tiene legato. Torna dall'anziano Zannaculea quando avrai recuperato la chiave.", "La chiave delle mie catene è in mano a ⟦Hitah'ya the Keeper=Hitah'ya la Custode⟧. Si trova nella grotta qui vicino. Fa' attenzione, {class}, perché è ben sorvegliata.\n\nUccidila e riporta qui la chiave per liberarmi dai ceppi. Solo allora sarò libero di tornare a casa.", "Devi sbrigarti!", "Finalmente libero! Grazie, {name}. Gli Zannatorta conosceranno le tue gesta!", 0x0d8b10ea, 0x9eecf974, 0x12d1758d, 0x01c595fd, 0xaf45680a, "....." },
  [7847] = { "Ritorno dalla primalista Zannaculea", "L'anziano Zannaculea, a Jintha'alor, vuole che tu torni dalla primalista Zannaculea al ⟦Revantusk Village=Villaggio degli Zannatorta⟧ con la notizia della sua liberazione.", "Torna dalla mia compagna, la primalista Zannaculea, al ⟦Revantusk Village=Villaggio degli Zannatorta⟧. Dille che sto tornando a casa! Di sicuro ti ricompenserà.", nil, "Hai reso un grande servizio agli Zannatorta, {name}! Abbiamo con te un grande debito di gratitudine.", 0x0f27bdd9, 0x81fcedc7, 0x10db24ef, nil, 0xd56fd9e5, "...m." },
  [7848] = { "⟦Attunement to the Core=Sintonia con il Nucleo⟧", "Raggiungi il portale d'ingresso del ⟦Molten Core=Nucleo Ardente⟧ nei ⟦Blackrock Depths=Sotterranei di Roccianera⟧ e recupera un ⟦Core Fragment=Frammento di Nucleo⟧. Quando avrai recuperato il ⟦Core Fragment=Frammento di Nucleo⟧, torna da ⟦Lothos Riftwaker=Lothos Destavarco⟧, al ⟦Blackrock Mountain=Massiccio Roccianera⟧.", "Intorno a noi i varchi si agitano, si squarciano e crollano, {race}. A meno di due passi da dove mi trovo c'è uno squarcio che attraversa le profondità del ⟦Blackrock Mountain=Massiccio Roccianera⟧ e conduce nelle fauci del Signore del Fuoco.\n\nSorpres<o/a>? Peccato... Le razze mortali non sanno comprendere ciò che non possono vedere, toccare o sentire.\n\nTi assicuro che il portale è lì e che è possibile accedervi.\n\nHo stuzzicato il tuo interesse? La sintonia è semplice. Inoltrati nei ⟦Blackrock Depths=Sotterranei di Roccianera⟧ e recupera un frammento del nucleo. Riportamelo e sintonizzerò la tua essenza con il portale.", "Devi sintonizzare la tua anima con il ⟦Molten Core=Nucleo Ardente⟧ prima di potervi accedere.", "Ora posso trasportarti al ⟦Molten Core=Nucleo Ardente⟧. Chiedi e sarà fatto.", 0x9b377bde, 0x3bb79f5f, 0x5c97dddf, 0xe85c13f9, 0xf3fa9e93, "....." },
  [7849] = { "Ansia da separazione", "Il predatore Markhor, al ⟦Revantusk Village=Villaggio degli Zannatorta⟧ nelle Entroterre, vuole che tu recuperi i resti del suo fratello gemello. Trova il ⟦Huntsman Malkhor's Skull=Teschio del Predatore Malkhor⟧ e le ⟦Huntsman Malkhor's Bones=Ossa del Predatore Malkhor⟧ e riportali al predatore Markhor.\n\nMarkhor ha detto che i resti di suo fratello sono stati dati in pasto alle melme e ai lupi dei Ramovile. Ha detto anche che a Jintha'alor c'è una fossa dei rifiuti piena di melme, oltre a una tana di lupi. Entrambi i luoghi sono vicino alla cima del tempio.", "Come molti nel nostro villaggio, anch'io ho perso una persona cara nelle terre selvagge. Ahimè, era mio fratello gemello Malkhor, catturato dai Ramovile nella stessa incursione in cui fu presa la compagna di Torntusk.\n\nPurtroppo il destino non gli concesse di vivere: fu giustiziato in modo rapido e brutale, e i suoi resti furono dati in pasto alle melme e ai lupi dei Ramovile.\n\nÈ troppo tardi per salvargli la vita, ma non per salvargli l'anima. Recupera i suoi resti, {name}.", "Quando avrò i suoi resti, li porterò a Yayo'jin perché li prepari per una degna sepoltura.", "Mio carissimo fratello, quanto mi mancherai...\n\nGrazie per il tuo aiuto, {name}. Ai miei occhi sei un vero esempio di eroismo.", 0x990c852a, 0x3d7f6d31, 0xa0d1b8af, 0x96f591c4, 0x1f647522, "....." },
  [7850] = { "Recipienti oscuri", "La primalista Zannaculea, al ⟦Revantusk Village=Villaggio degli Zannatorta⟧ nelle Entroterre, vuole che tu recuperi 10 Recipiente di Sangue Corrotto da Jintha'alor. Torna dalla primalista Zannaculea quando avrai finito.", "I Ramovile combattono con una ferocia soprannaturale. È opera dei turpi intrecci magici della sacerdotessa immonda Hexx.\n\nIn tutta Jintha'alor troverai recipienti oscuri di sangue corrotto. I recipienti irradiano la turpe magia del Dio del Sangue senza volto, che rafforza i Ramovile e al tempo stesso li spinge alla follia.\n\nRuba quei recipienti e riportameli, così che io possa rimuovere la corruzione e allentare infine la presa del Dio del Sangue.", "Sii prudente quando combatti i Ramovile, {name}. Hanno la mente annebbiata: combattono fino alla morte.", "L'energia oscura che domina i Ramovile si è dissolta, per ora. Dobbiamo restare sempre vigili nella nostra battaglia contro il male: anche se la sacerdotessa immonda viene distrutta, un'altra prende presto il suo posto.", 0x15285bf1, 0xe8b9f035, 0xdbb1499f, 0x1e204046, 0xa0892e1a, "....." },
  [7861] = { "Ricercati: la sacerdotessa vile Hexx e i suoi servitori", "Ti è stato ordinato di uccidere ⟦Vile Priestess Hexx=Sacerdotessa Vile Hexx⟧ e 20 Vilebranch Aman'zasi Guard. Quando avrai finito, va' dalla primalista Zannaculea al ⟦Revantusk Village=Villaggio degli Zannatorta⟧, nelle Entroterre.\n\n⟦Vile Priestess Hexx=Sacerdotessa Vile Hexx⟧ e gli Aman'zasi Guard si trovano in cima a Jintha'alor, nelle Entroterre.", "Per ordine della primalista Zannaculea, la sacerdotessa vile Hexx e i suoi servitori devono essere consegnati alla giustizia!\n\nUna grande ricompensa è offerta a chiunque uccida la sacerdotessa vile Hexx e tutta la sua guardia scelta Aman'zasi.", "Porti notizie da Jintha'alor?", "Un colpo durissimo per i Ramovile, davvero. Sarai riccamente ricompensat<o/a>, {name}.", 0x3ae78e9b, 0xc3384839, 0x6d86f4f5, 0x9faa7167, 0x9c42955f, "....." },
  [7862] = { "Posto vacante: capitano della guardia del ⟦Revantusk Village=Villaggio degli Zannatorta⟧", "Il tuo compito è decimare 20 Vilebranch Berserker, 20 Vilebranch Shadow Hunter, 20 Vilebranch Blood Drinker e 20 Vilebranch Soul Eater.\n\nSe porterai a termine il compito, torna dalla primalista Zannaculea al ⟦Revantusk Village=Villaggio degli Zannatorta⟧, nelle Entroterre.", "Con la perdita del capitano della guardia Malkhor, il posto di capitano della guardia degli Zannatorta è di nuovo vacante. Se ti interessa diventare capitano della guardia degli Zannatorta, porta a termine i seguenti compiti e presenta la tua candidatura alla primalista Zannaculea:\n\nStermina i Vilebranch Berserker.\n\nStermina i Vilebranch Shadow Hunter.\n\nStermina i Vilebranch Blood Drinker.\n\nStermina i Vilebranch Soul Eater.", "Sei qui per il posto vacante?", "Sei davvero <un/una> candidat<o/a> degn<o/a> del nuovo incarico, {name}. Accetta questo ninnolo come segno del nostro apprezzamento per il tuo duro lavoro. Esaminerò tutte le candidature l'anno prossimo.", 0x0c6ec972, 0x7810ea79, 0x68e9c82a, 0x1555b6b2, 0x3bf60d07, "....." },
  [7863] = { "⟦Sentinel Basic Care Package=Kit Curativo di Base delle Sentinelle⟧", nil, nil, nil, "Hai certamente cominciato a dimostrarci il tuo valore, {name}. Come ricompensa, prendi questo kit curativo! Dentro troverai razioni e bende utilizzabili solo nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧.\n\nContinuando a dimostrare il tuo valore nella Forra, scoprirai che potrai acquistare questi oggetti. Le razioni diventano disponibili quando sei Amichevole con noi, e le bende quando sei Onorato.", 0x74e23f32, nil, nil, nil, 0x4d9a1c18, ".mmm." },
  [7864] = { "⟦Sentinel Standard Care Package=Kit Curativo Standard delle Sentinelle⟧", nil, nil, nil, "Hai certamente cominciato a dimostrarci il tuo valore, {name}. Come ricompensa, prendi questo kit curativo! Dentro troverai razioni e bende utilizzabili solo nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧.\n\nContinuando a dimostrare il tuo valore nella Forra, scoprirai che potrai acquistare questi oggetti. Le razioni diventano disponibili quando sei Amichevole con noi, e le bende quando sei Onorato.", 0x643d9bc7, nil, nil, nil, 0x4d9a1c18, ".mmm." },
