  [7869] = { "Missione di prova - non usare", nil, nil, nil, nil, 0x22601199, nil, nil, nil, nil, ".mmmm" },
  [7870] = { "Missione di prova2 - non usare", nil, nil, nil, nil, 0x486cc81a, nil, nil, nil, nil, ".mmmm" },
  [7871] = { "Sconfiggi gli invasori!", "Entra nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e sconfiggi l'⟦Horde=Orda⟧, ottieni un ⟦Warsong Gulch Mark of Honor=Contrassegno d'Onore della Forra dei Cantaguerra⟧ e torna dalla sentinella Cantolungo al ⟦Silverwing Grove=Boschetto degli Alargentea⟧.", "Oltre questa galleria troverai un campo di lotta e tumulto, giovane {class}. L'⟦Horde=Orda⟧ continua a devastare la nostra foresta sacra, abbattendo i sempreverdi per alimentare le sue macchine da guerra.\n\nEntra nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e difendi la ⟦Silverwing Hold=Rocca di Alargentea⟧. Respingi le forze d'invasione dell'⟦Horde=Orda⟧!\n\nFallo, e otterrai un talismano al merito. Portami un tale talismano, {name}, e ti ricompenserò.", "Hai combattuto nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e difeso la ⟦Silverwing Hold=Rocca di Alargentea⟧?", "Hai dimostrato il tuo valore nei nostri sforzi nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧. Continua a sostenere la causa e portami altri contrassegni d'onore. Fallo, e ti guadagnerai ancora di più la nostra fiducia.", 0x55520e44, 0xfeb46d9a, 0xd5134582, 0x71ff749c, 0xf9915c4e, "....." },
  [7872] = { "Sconfiggi gli invasori!", "Entra nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e sconfiggi l'⟦Horde=Orda⟧, ottieni un ⟦Warsong Gulch Mark of Honor=Contrassegno d'Onore della Forra dei Cantaguerra⟧ e torna dalla sentinella Cantolungo al ⟦Silverwing Grove=Boschetto degli Alargentea⟧.", "Oltre questa galleria troverai un campo di lotta e tumulto, giovane {class}. L'⟦Horde=Orda⟧ continua a devastare la nostra foresta sacra, abbattendo i sempreverdi per alimentare le sue macchine da guerra.\n\nEntra nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e difendi la ⟦Silverwing Hold=Rocca di Alargentea⟧. Respingi le forze d'invasione dell'⟦Horde=Orda⟧!\n\nFallo, e otterrai un contrassegno d'onore. Portamelo, {name}, e ti ricompenserò.", "Hai combattuto nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e difeso la ⟦Silverwing Hold=Rocca di Alargentea⟧?", "Hai dimostrato il tuo valore nei nostri sforzi nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧. Continua a sostenere la causa e portami altri contrassegni d'onore. Fallo, e ti guadagnerai ancora di più la nostra fiducia.", 0x55520e44, 0xfeb46d9a, 0x682b535e, 0x71ff749c, 0xf9915c4e, "....." },
  [7873] = { "Sconfiggi gli invasori!", "Entra nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e sconfiggi l'⟦Horde=Orda⟧, ottieni un ⟦Warsong Gulch Mark of Honor=Contrassegno d'Onore della Forra dei Cantaguerra⟧ e torna dalla sentinella Cantolungo al ⟦Silverwing Grove=Boschetto degli Alargentea⟧.", "Oltre questa galleria troverai un campo di lotta e tumulto, giovane {class}. L'⟦Horde=Orda⟧ continua a devastare la nostra foresta sacra, abbattendo i sempreverdi per alimentare le sue macchine da guerra.\n\nEntra nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e difendi la ⟦Silverwing Hold=Rocca di Alargentea⟧. Respingi le forze d'invasione dell'⟦Horde=Orda⟧!\n\nFallo, e otterrai un contrassegno d'onore. Portamelo, {name}, e ti ricompenserò.", "Hai combattuto nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e difeso la ⟦Silverwing Hold=Rocca di Alargentea⟧?", "Hai dimostrato il tuo valore nei nostri sforzi nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧. Continua a sostenere la causa e portami altri contrassegni d'onore. Fallo, e ti guadagnerai ancora di più la nostra fiducia.", 0x55520e44, 0xfeb46d9a, 0x682b535e, 0x71ff749c, 0xf9915c4e, "....." },
  [7874] = { "Domare gli usurpatori Alargentea", "Entra nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e sconfiggi l'⟦Alliance=Alleanza⟧, ottieni un ⟦Warsong Gulch Mark of Honor=Contrassegno d'Onore della Forra dei Cantaguerra⟧ e portalo al capitano Spaccateschi all'⟦Mor'shan Base Camp=Accampamento Mor'shan⟧.", "Le terre selvagge della foresta di ⟦Ashenvale=Valtetra⟧ cederanno alla potenza dell'⟦Horde=Orda⟧, {race}. Nulla di ciò che gli Alargentea dicono o fanno può fermare il nostro imperativo sovrano. Kalimdor appartiene all'⟦Horde=Orda⟧. Come osano cercare di impedirci di raccogliere ciò che è nostro di diritto!\n\nLascia che l'orgoglio ti gonfi il petto mentre stronchi i loro deboli tentativi di rallentare la nostra avanzata. Distruggi le ⟦Silverwing Sentinels=Sentinelle Alargentea⟧ e ottieni un contrassegno d'onore dei ⟦Warsong=Cantaguerra⟧. Torna da me con un tale contrassegno, {name}, e sarai ricompensat<o/a>.", "Il sangue dei nostri nemici è un contrassegno d'onore. Ce l'hai un contrassegno del genere?", "<Il capitano Spaccateschi ruggisce in trionfo.>\n\nQuanto ancora possono resistere? Quanta altra feccia dell'⟦Alliance=Alleanza⟧ deve perire per mano dell'⟦Horde=Orda⟧ prima che si ritirino? Solo il tempo lo dirà, {race}...", 0x636625b4, 0xc94c2293, 0x2eb6ef0c, 0xd1cff4b7, 0x160777a5, "....." },
  [7875] = { "Domare gli usurpatori Alargentea", "Entra nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e sconfiggi l'⟦Alliance=Alleanza⟧, ottieni un Contrassegno d'Onore dei ⟦Warsong=Cantaguerra⟧ e portalo al capitano Spaccateschi all'⟦Mor'shan Base Camp=Accampamento Mor'shan⟧.", "Le terre selvagge della foresta di ⟦Ashenvale=Valtetra⟧ cederanno alla potenza dell'⟦Horde=Orda⟧, {race}. Nulla di ciò che gli Alargentea dicono o fanno può fermare il nostro imperativo sovrano. Kalimdor appartiene all'⟦Horde=Orda⟧. Come osano cercare di impedirci di raccogliere ciò che è nostro di diritto!\n\nLascia che l'orgoglio ti gonfi il petto mentre stronchi i loro deboli tentativi di rallentare la nostra avanzata. Distruggi le ⟦Silverwing Sentinels=Sentinelle Alargentea⟧ e ottieni un contrassegno d'onore dei ⟦Warsong=Cantaguerra⟧. Torna da me con un tale contrassegno, {name}, e sarai ricompensat<o/a>.", "Il sangue dei nostri nemici è un contrassegno d'onore. Ce l'hai un contrassegno del genere?", "<Il capitano Spaccateschi ruggisce in trionfo.>\n\nQuanto ancora possono resistere? Quanta altra feccia dell'⟦Alliance=Alleanza⟧ deve perire per mano dell'⟦Horde=Orda⟧ prima che si ritirino? Solo il tempo lo dirà, {race}...", 0x636625b4, 0x3df29510, 0x2eb6ef0c, 0xd1cff4b7, 0x160777a5, "....." },
  [7876] = { "Domare gli usurpatori Alargentea", "Entra nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e sconfiggi l'⟦Alliance=Alleanza⟧, ottieni un ⟦Warsong Gulch Mark of Honor=Contrassegno d'Onore della Forra dei Cantaguerra⟧ e portalo al capitano Spaccateschi all'⟦Mor'shan Base Camp=Accampamento Mor'shan⟧.", "Le terre selvagge della foresta di ⟦Ashenvale=Valtetra⟧ cederanno alla potenza dell'⟦Horde=Orda⟧, {race}. Nulla di ciò che gli Alargentea dicono o fanno può fermare il nostro imperativo sovrano. Kalimdor appartiene all'⟦Horde=Orda⟧. Come osano cercare di impedirci di raccogliere ciò che è nostro di diritto!\n\nLascia che l'orgoglio ti gonfi il petto mentre stronchi i loro deboli tentativi di rallentare la nostra avanzata. Distruggi le ⟦Silverwing Sentinels=Sentinelle Alargentea⟧ e ottieni un contrassegno d'onore. Torna da me con un tale contrassegno, {name}, e sarai ricompensat<o/a>.", "Il sangue dei nostri nemici è un contrassegno d'onore. Ce l'hai un contrassegno del genere?", "<Il capitano Spaccateschi ruggisce in trionfo.>\n\nQuanto ancora possono resistere? Quanta altra feccia dell'⟦Alliance=Alleanza⟧ deve perire per mano dell'⟦Horde=Orda⟧ prima che si ritirino? Solo il tempo lo dirà, {race}...", 0x636625b4, 0xc94c2293, 0x2eb6b1fd, 0xd1cff4b7, 0x160777a5, "....." },
  [7877] = { "Il tesoro degli Shen'dralar", "Torna nell'Athenaeum e trova il tesoro degli Shen'dralar. Reclama la tua ricompensa!", "Nella biblioteca, l'Athenaeum, troverai un antico forziere nascosto sotto la scalinata. Prendi ciò che desideri.", nil, "Apri il forziere e trovi...", 0xe29bd883, 0x031a4aa1, 0x4ca8e2d2, nil, 0x549f5efb, "...m." },
  [7883] = { "Lo gnomo più grande del mondo!", nil, nil, "Yebb Nebblegear vuole aggiungere nuovi talenti al suo spettacolo e sta cercando in lungo e in largo lo gnomo più grande del mondo. Conosci qualche gnomo di dimensioni considerevoli?\n\nBe', ancora prima di trovare lo gnomo, vuole che il suo costume sia pronto. Credo che un'Imbracatura della Barbarie sarebbe un'ottima base per il costume: puoi fabbricare qualche imbracatura e portarmela? Fallo, e avrò una pila di biglietti della ⟦Darkmoon Faire=Fiera di Lunacupa⟧ per te...", "Oh cielo, sono proprio grandi!! Non riesco a immaginare uno gnomo che ci stia dentro a pennello, ma niente paura: se lo gnomo che troveremo non sarà abbastanza grande, posso fare delle modifiche al suo costume.\n\nMille grazie, {name}. Ecco i biglietti che ti avevo promesso.", 0xe283eba9, nil, nil, 0x4319c62d, 0x66786e48, ".mm.." },
  [7891] = { "⟦Green Iron Bracers=Bracciali di Ferro Verdi⟧", nil, nil, "Sto preparando un nuovo costume, per quando avrò il mio stand come donna più forte del mondo! Ora sto cercando dei bracciali da indossare. Non possono coprire molto, perché la gente vuole vedere i miei muscoli, ma voglio comunque sfoggiare un po' di colore, capisci?\n\nChe ne dici dei Bracciali di Ferro Verdi, {name}? Puoi fabbricarmi dei Bracciali di Ferro Verdi? Se ci riesci, ho un bel mucchio di biglietti della ⟦Darkmoon Faire=Fiera di Lunacupa⟧ per te.", "Sì! Sono proprio quello che mi serve! Che bel colore, e mi lasciano le braccia scoperte così si vede quanto sono forti! Perfetti!\n\nEcco a te, {name}. Ecco i tuoi biglietti: divertiti!", 0x57e23ec9, nil, nil, 0xb617dfba, 0x2bc703fc, ".mm.." },
  [7896] = { "Fuochi d'artificio verdi", nil, nil, "Quando finalmente avrò messo in piedi questo stand, vorrò fare pubblicità! E quale modo migliore per farsi pubblicità dei fuochi d'artificio?\n\nBe', qualcuno penserebbe che l'odore di un calderone in cui ribollono le teste dei nemici attiri di più la folla, ma... siamo in compagnia mista. Quindi dovranno essere fuochi d'artificio!\n\nPortami dei Fuochi d'Artificio Verdi, {name}, e avrò una bella manciata di biglietti della ⟦Darkmoon Faire=Fiera di Lunacupa⟧ per te.", "Hai portato i fuochi d'artificio. Ottimo lavoro, {name}! Non vedo l'ora di accenderli e annunciare al mondo che il mio stand è pronto! Devo ancora aspettare, parecchio temo, ma... sarò pronto quando sarò pronto, no?\n\nEcco i biglietti, {name}. Divertiti!", 0x0e1078f3, nil, nil, 0xd0b2c4bd, 0x79ddc45f, ".mm.." },
  [7905] = { "La ⟦Darkmoon Faire=Fiera di Lunacupa⟧", "Consegna il ⟦Free Ticket Voucher=Buono per Biglietti Gratis⟧ a Gelvas Grimgate, all'interno della ⟦Darkmoon Faire=Fiera di Lunacupa⟧.", "Arriva la ⟦Darkmoon Faire=Fiera di Lunacupa⟧! Non perderti tutte le sue meraviglie e le sue emozioni quando arriverà in città!\n\nSe ti sbrighi, puoi riscattare questo buono in cambio di biglietti premio gratis! Basta consegnare il buono a Gelvas Grimgate, all'interno della fiera.\n\nIn questo momento la fiera si trova fuori ⟦Goldshire=Borgodoro⟧, nella ⟦Elwynn Forest=Foresta di Elwynn⟧. Non perdertela! Vacci oggi stesso!", "Sì, amico, posso aiutarti? Hai un buono da riscattare?", "Benvenut<o/a> alla ⟦Darkmoon Faire=Fiera di Lunacupa⟧! Questo buono vale CINQUE, sì, CINQUE biglietti premio!\n\nQuando avrai accumulato dei biglietti premio, vieni a parlare con me per riscattarli in cambio di premi preziosi. Più biglietti ottieni, più premi puoi vincere. Evviva!", 0x81e45326, 0x59d160bd, 0xb2786af9, 0x08ce32b9, 0xf62b21ee, "....." },
  [7906] = { "Carte di Lunacupa - Bestie", nil, nil, nil, nil, 0x73dd5b02, nil, nil, nil, nil, ".mmmm" },
  [7907] = { "Mazzo delle Bestie di Lunacupa", "Riporta il Mazzo delle Bestie alla ⟦Darkmoon Faire=Fiera di Lunacupa⟧ quando arriverà in città.", "Ora che hai riunito in un mazzo tutte le carte delle Bestie, compare misteriosamente una nona carta con lo stesso dorso delle prime otto. Sulla carta è scritto: «Riporta queste carte alla ⟦Darkmoon Faire=Fiera di Lunacupa⟧ e sarai <ricompensato/ricompensata>.» Hai sentito dire che la fiera fa tappa alternativamente a Mulgore e a ⟦Goldshire=Borgodoro⟧ ogni pochi mesi, quindi dovrai aspettare che torni da queste parti.", "Oh, cielo.", "Dunque hai messo insieme un mazzo delle Bestie. Il tuo gesto di restituircelo creerà tra te e la Fiera di Lunacupa un legame che non sarà presto dimenticato. Permettimi di offrirti una delle carte di Lunacupa maggiori come piccolo segno della nostra gratitudine.", 0x63de7a0d, 0x62dda1b1, 0x405afcfa, 0x9e26ead5, 0x5dda3bb5, "....." },
  [7908] = { "⟦Arena Master=Maestro delle Arene⟧", "Parla con Short John Mithril all'arena di Rovotorto.", "Per essere maestro dell'arena ci dev'essere qualcosa di più! Forse il pirata che organizza l'evento a Gurubashi lo saprà!", nil, nil, 0x11d885c3, 0x6414b72c, 0x84414394, nil, nil, "...mm" },
  [7926] = { "La ⟦Darkmoon Faire=Fiera di Lunacupa⟧", "Consegna il ⟦Free Ticket Voucher=Buono per Biglietti Gratis⟧ a Gelvas Grimgate, all'interno della ⟦Darkmoon Faire=Fiera di Lunacupa⟧.", "Arriva la ⟦Darkmoon Faire=Fiera di Lunacupa⟧! Non perderti tutte le sue meraviglie e le sue emozioni quando arriverà in città!\n\nSe ti sbrighi, puoi riscattare questo buono in cambio di biglietti premio gratis! Basta consegnare il buono a Gelvas Grimgate, all'interno della fiera.\n\nIn questo momento la fiera si trova appena fuori ⟦Thunder Bluff=Picco del Tuono⟧, a Mulgore. Non perdertela! Vacci oggi stesso!", "Sì, amico, posso aiutarti? Hai un buono da riscattare?", "Benvenut<o/a> alla ⟦Darkmoon Faire=Fiera di Lunacupa⟧! Questo buono vale CINQUE, sì, CINQUE biglietti premio!\n\nQuando avrai accumulato dei biglietti premio, vieni a parlare con me per riscattarli in cambio di premi preziosi. Più biglietti ottieni, più premi puoi vincere. Evviva!", 0x81e45326, 0x59d160bd, 0x3d4daeaf, 0x08ce32b9, 0xf62b21ee, "....." },
  [7927] = { "⟦Portals Deck=Mazzo dei Portali⟧ di Lunacupa", "Riporta il ⟦Portals Deck=Mazzo dei Portali⟧ alla ⟦Darkmoon Faire=Fiera di Lunacupa⟧ quando arriverà in città.", "Ora che hai riunito in un mazzo tutte le carte dei Portali, compare misteriosamente una nona carta con lo stesso dorso delle prime otto. Sulla carta è scritto: «Riporta queste carte alla ⟦Darkmoon Faire=Fiera di Lunacupa⟧ e sarai <ricompensato/ricompensata>.» Hai sentito dire che la fiera fa tappa alternativamente a Mulgore e a ⟦Goldshire=Borgodoro⟧ ogni pochi mesi, quindi dovrai aspettare che torni da queste parti.", "Vedo che sei <riuscito/riuscita> a completare un mazzo dei Portali! Congratulazioni!", "Dunque hai messo insieme un mazzo dei Portali. Il tuo gesto di restituircelo creerà tra te e la Fiera di Lunacupa un legame che non sarà presto dimenticato. Permettimi di offrirti una delle carte di Lunacupa maggiori come piccolo segno della nostra gratitudine.", 0xa0956489, 0xff866ea6, 0x114b9c81, 0x38992949, 0x45adf59a, "....." },
  [7928] = { "⟦Warlords Deck=Mazzo dei Signori della Guerra⟧ di Lunacupa", "Riporta il ⟦Warlords Deck=Mazzo dei Signori della Guerra⟧ alla ⟦Darkmoon Faire=Fiera di Lunacupa⟧ quando arriverà in città.", "Ora che hai riunito in un mazzo tutte le carte dei Signori della Guerra, compare misteriosamente una nona carta con lo stesso dorso delle prime otto. Sulla carta è scritto: «Riporta queste carte alla ⟦Darkmoon Faire=Fiera di Lunacupa⟧ e sarai <ricompensato/ricompensata>.» Hai sentito dire che la fiera fa tappa alternativamente a Mulgore e a ⟦Goldshire=Borgodoro⟧ ogni pochi mesi, quindi dovrai aspettare che torni da queste parti.", "Vedo che sei <riuscito/riuscita> a completare un mazzo dei Signori della Guerra! Congratulazioni!", "Dunque hai messo insieme un mazzo dei Signori della Guerra. Il tuo gesto di restituircelo creerà tra te e la Fiera di Lunacupa un legame che non sarà presto dimenticato. Permettimi di offrirti una delle carte di Lunacupa maggiori come piccolo segno della nostra gratitudine.", 0xe25ce5cf, 0xb6535fe4, 0x79c29624, 0x04e4adf5, 0x9d09863b, "....." },
  [7929] = { "⟦Elementals Deck=Mazzo degli Elementali⟧ di Lunacupa", "Riporta il ⟦Elementals Deck=Mazzo degli Elementali⟧ alla ⟦Darkmoon Faire=Fiera di Lunacupa⟧ quando arriverà in città.", "Ora che hai riunito in un mazzo tutte le carte degli Elementali, compare misteriosamente una nona carta con lo stesso dorso delle prime otto. Sulla carta è scritto: «Riporta queste carte alla ⟦Darkmoon Faire=Fiera di Lunacupa⟧ e sarai <ricompensato/ricompensata>.» Hai sentito dire che la fiera fa tappa alternativamente a Mulgore e a ⟦Goldshire=Borgodoro⟧ ogni pochi mesi, quindi dovrai aspettare che torni da queste parti.", "Vedo che sei <riuscito/riuscita> a completare un mazzo degli Elementali! Congratulazioni!", "Dunque hai messo insieme un mazzo degli Elementali. Il tuo gesto di restituircelo creerà tra te e la Fiera di Lunacupa un legame che non sarà presto dimenticato. Permettimi di offrirti una delle carte di Lunacupa maggiori come piccolo segno della nostra gratitudine.", 0x31989af8, 0xfea6f677, 0x6e234ab1, 0xc43ece46, 0xdac1d961, "....." },
  [7937] = { "La tua fortuna ti attende...", "Raggiungi il ⟦Eastvale Logging Camp=Campo di Taglio di Vallevante⟧ nella ⟦Elwynn Forest=Foresta di Elwynn⟧ e cerca la tua fortuna.", "«La tua fortuna ti attende a Vallevante.»\n\nIl biglietto della fortuna che Sayge ti ha dato è leggermente caldo al tatto. Stringendolo forte, vedi un'immagine del ⟦Eastvale Logging Camp=Campo di Taglio di Vallevante⟧ nella ⟦Elwynn Forest=Foresta di Elwynn⟧. Concentrandoti meglio sull'immagine, vedi un pagliaio accanto a una stalla.", "Questo pagliaio sembra quello della tua visione.", "Frugando rapidamente nel pagliaio trovi uno scrigno! A quanto pare hai trovato la tua fortuna!", 0xd4d31135, 0xc82083e8, 0x33dafe1f, 0xdd20eaed, 0x5a894296, "....." },
  [7938] = { "La tua fortuna ti attende...", "Raggiungi le ⟦Deadmines=Miniere della Morte⟧ nelle ⟦Westfall=Marche Occidentali⟧ e cerca la tua fortuna.", "«La tua fortuna ti attende nelle ⟦Deadmines=Miniere della Morte⟧.»\n\nIl biglietto della fortuna che Sayge ti ha dato è leggermente caldo al tatto. Stringendolo forte, vedi un'immagine delle ⟦Deadmines=Miniere della Morte⟧, sotto il villaggio in rovina di ⟦Moonbrook=Rivoluna⟧, nelle Marche Occidentali. Concentrandoti meglio sull'immagine, percorri cunicoli tortuosi fino a raggiungere un portale scintillante... che conduce nel cuore stesso delle miniere. Quando lo attraversi, uno strano forziere compare dal nulla.", "Questo forziere sembra quello della tua visione...", "Frugando rapidamente nel forziere trovi uno scrigno! A quanto pare hai trovato la tua fortuna!", 0xd4d31135, 0x0a114641, 0xb9905b2d, 0x0f89f811, 0x4ff8a559, "....." },
  [7944] = { "La tua fortuna ti attende...", "Raggiungi la ⟦Wailing Caverns=Caverna dei Lamenti⟧ nelle ⟦Barrens=Savane⟧ e cerca la tua fortuna.", "«La tua fortuna ti attende nella ⟦Wailing Caverns=Caverna dei Lamenti⟧.»\n\nIl biglietto della fortuna che Sayge ti ha dato è leggermente caldo al tatto. Stringendolo forte, vedi un'immagine di una grotta a sud-ovest del ⟦Crossroads=Crocevia⟧, nelle ⟦Barrens=Savane⟧. Concentrandoti meglio sull'immagine, percorri cunicoli tortuosi fino a raggiungere un portale scintillante... che conduce nel cuore stesso delle caverne. Quando lo attraversi, uno strano forziere compare dal nulla.", "Questo forziere sembra quello della tua visione...", "Frugando rapidamente nel forziere trovi uno scrigno! A quanto pare hai trovato la tua fortuna!", 0xd4d31135, 0x0ecaa544, 0x3a54e251, 0x0f89f811, 0x4ff8a559, "....." },
  [7945] = { "La tua fortuna ti attende...", "Raggiungi la ⟦Palemane Rock=Roccia dei Mantopallido⟧ a Mulgore e cerca la tua fortuna.", "«La tua fortuna ti attende fuori dalla ⟦Palemane Rock=Roccia dei Mantopallido⟧.»\n\nIl biglietto della fortuna che Sayge ti ha dato è leggermente caldo al tatto. Stringendolo forte, vedi un'immagine della ⟦Palemane Rock=Roccia dei Mantopallido⟧, a Mulgore. Concentrandoti meglio sull'immagine, vedi un ceppo d'albero vicino all'ingresso della grotta.", "Questo ceppo d'albero sembra quello della tua visione.", "Frugando rapidamente nel ceppo d'albero trovi uno scrigno! A quanto pare hai trovato la tua fortuna!", 0xd4d31135, 0xa30f2210, 0x4e3efd8a, 0xaa2aadef, 0xc9c08867, "....." },
  [7946] = { "La progenie di ⟦Jubjub=Pincopalla⟧", nil, nil, "Sono così felice che ⟦Jubjub=Pincopalla⟧ non sia più persa. Adora talmente la birra dei ⟦Dark Iron=Ferroscuro⟧ che quando l'ho finita... è scappata per trovarne altra!\n\nOra che ⟦Jubjub=Pincopalla⟧ è tornata, voglio tutta la birra che riesco a procurarmi! Non voglio che scappi di nuovo!\n\nHai della birra dei ⟦Dark Iron=Ferroscuro⟧? Se ce l'hai, ti darò una delle uova di rana di ⟦Jubjub=Pincopalla⟧ in cambio di un boccale...", "Grazie, {name}. Ecco il tuo uovo! Ci vorrà un po' prima che si schiuda, ma quando succederà avrai un fantastico animaletto!", 0xad05c1dd, nil, nil, 0x09b8849d, 0xb8311bf6, ".mm.." },
  [7961] = { "Wabbit biwbanti!", "Uccidi 5 conigli e torna da Jon LeCraft, vicino alla forgia sull'⟦Designer Island=Isola degli Sviluppatori⟧.", "Questi conigli si riproducono in modo incontrollabile. Bisogna fare qualcosa!\n\nAiutaci, {name}, sei la nostra unica speranza.", nil, nil, 0x26e1428c, 0x7c67e5a2, 0x62029839, nil, nil, "...mm" },
  [7962] = { "Pelli di Wabbit", "Porta 3 LeCrafty Rabbit Pelt a Jon LeCraft.", "Voglio pelli di LeCrafty Rabbit. Procuramene un po' dai LeCrafty Rabbit.\n\nÈ importante!", nil, nil, 0x1ebd053c, 0xfd9305aa, 0x7ff5eaf6, nil, nil, "...mm" },
})
